window.COMMON_BANK = window.COMMON_BANK || {};
window.COMMON_BANK["tech"] = window.COMMON_BANK["tech"] || {name:"科技常识", items:[]};
window.COMMON_BANK["tech"].items.push(
{"id": "tech-427", "q": "下列关于植物食用部分的叙述不正确的是：", "options": ["马铃薯的食用部分是根部", "洋葱的食用部分是茎部", "甘薯的食用部分是根部", "甘蓝的食用部分是叶部"], "a": 0, "e": ".【A】A项错误，马铃薯的食用部分是块茎。B、C、D三项均符合事实，故正确。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-428", "q": "下列疾病不是由病毒引起的是：", "options": ["足癣和手癣", "艾滋病", "鸡瘟或猪瘟", "非典"], "a": 0, "e": ".【A】手足癣是发生于掌、跖与指、趾间皮肤的浅部真菌感染。致病菌手足癣主要有红色毛癣菌、须癣毛癣菌和絮状表皮癣菌。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-429", "q": "下列说法错误的是：", "options": ["细胞工程技术可以用于生产动物疫苗", "目前人们采用生物克隆技术培育“试管婴儿”", "人们可以使用基因工程技术培育抗虫棉新品种", "使用蛋白质技术可以改造胰岛素，制造新型药物"], "a": 1, "e": ".【B】试管婴儿在医学上的名称为体外受精—胚胎移植(简称IVF-ET)。以往在科学研究中，常使用试管，所以俗称为试管婴儿。试管婴儿具体是指从女性患者体内取出卵子，在体外培养，并与精子受精，再将在体外发育到一定阶段的胚胎移植到女性的宫腔内，使其着床发育成胎儿的过程。并非采用生物克隆技术。故B项错误。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-430", "q": "下列关于人体血压的说法，正确的是：", "options": ["心室收缩时，动脉血压值称为收缩压，也称为低压", "正常的血压是血液循环流动的前提，受到多种因素的影响", "高血压对身体健康有重大危害，低血压不会影响身体健康", "高血压病人应遵医嘱，服用降压药；血压正常后，应立刻停药"], "a": 1, "e": ".【B】本题考查医学常识。A项错误，心脏收缩时动脉血压值称为收缩压，也称为高压；B项正确，血压是血液循环流动的前提并且受到饮食、情绪、运动等多种运动影响；C项错误，低血压会对身体健康有影响，会导致头晕、乏力、听力下降、视力模糊等症状；D项错误，对于高血压病人，不建议病人完全停药，一般建议终生服药，以避免复发引起的多种并发症。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-431", "q": "下列关于维生素C 的说法正确的是：", "options": ["维生素C 不容易被热、光和氧破坏", "维生素C 是常用的脂溶性维生素之一", "长期服用大量维生素C 可引起腹泻、恶心、呕吐、胃痉挛", "人体受外伤后，伤口会自行愈合，因为人体可以产生维生素", ""], "a": 2, "e": ".【C】A项错误，维生素C加热后易受到破坏；B项错误，维生素C是常见的水溶性维生素之一；C项正确，维生素C过量服用可引起不良反应：每日服1~4g，可引起腹泻、皮疹、胃酸增多、胃液反流，每日用量超过", "tag": "科技常识"},
{"id": "tech-432", "q": "“穿花蝴蝶深深见，点水蜻蜓款款飞。”夏天，我们常会看到蜻蜓在水面中飞来飞去，还会不时地轻点水面。蜻蜓点水的目的是为了：", "options": ["饮水", "解暑", "产卵", "嬉戏"], "a": 2, "e": ".【C】蜻蜓点水就是蜻蜓产卵，卵直接产入水中，或产于水草上。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-433", "q": "人类面临移植组织、器官短缺的实际困难。转基因动物的问世给人类带来福音。科学家们首选的利用转基因技术为人类提供异种器官移植供体的动物是：", "options": ["猪", "猴", "狗", "黑猩猩"], "a": 0, "e": ".【A】科学家们首选的异种器官移植供体动物是猪。其主要原因是：猪的器官大小与人的相似，解剖结构与人类的也相同，生理指标相近；猪的血型抗原与人类的相近；生长周期短、投资少、经济，便于商品化；猪的蛋白质可直接用于治疗人类疾病，多年应用无不良反应，如猪胰岛素等。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-434", "q": "人体汗腺分布最多的部位是：", "options": ["腋窝", "腹股沟", "阴部", "手掌和脚部"], "a": 3, "e": ".【D】人体的汗腺遍布全身皮肤，其中汗腺分布最多的部位是手掌和脚部。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-435", "q": "自然界中不同生物之间的共生关系一般理解为“相互依存，互利互惠”，下列存在共生关系的是：", "options": ["寄居蟹与海葵", "菟丝子与豆科植物", "霸王花与大叶山毛榉"], "a": 0, "e": ".【A】共生是指两种不同生物之间形成的紧密互利关系。在共生关系中，一方为另一方提供有利于生存的帮助，同时也获得对方的帮助。A项寄居蟹和海葵之间便是共生关系，海葵的刺丝胞能提供寄居蟹某些程度的保护；而海葵可在壳上获得栖息的硬基质、在寄居蟹觅食时可获得碎屑。C项菟丝子又叫“豆寄生”，是一种生理构造特殊的寄生植物，其组成的细胞中没有叶绿体，主要靠寄生在豆科植物的茎叶上吸取营养物质为生。菟丝子和豆科植物之间是寄生关系。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-436", "q": "苋菜的细胞液中有一些红色物质，无论用普通清水怎么冲洗，红色物质不会溶出。但如果把苋菜放在沸水中一烫，水立即变成红色。这是因为：", "options": ["沸水使细胞膜失去选择透过性", "在清水中细胞膜没有选择透过性", "沸水中色素分解成小分子物质", "在清水中没有物质出入"], "a": 0, "e": ".【A】活细胞的细胞膜的功能特性为选择透过性，即只能让一些物质通过，不能让其他物质通过的性质。用清水冲洗时，苋菜的细胞膜具有选择透过性，阻拦色素流出细胞。而用沸水煮过后，死亡的细胞失去选择透过性，其中的物质会进入外界溶液。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-437", "q": "适当食用粗粮，增加纤维素的摄入有益人体健康。下列有关纤维素的说法，错误的是：", "options": ["纤维素在胃肠中可被分解为葡萄糖，并被人体有效吸收", "食物中的纤维素能够使人产生饱腹感，有利于减肥", "纤维素能够吸附一些有害物质，有利于体内毒素的排除", "纤维素是一种天然有机高分子化合物，能够吸附大量水分"], "a": 0, "e": ".【A】人类膳食中的纤维素主要含于蔬菜和粗加工的谷类中，不能被消化吸收，A项表述错误。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-438", "q": "降低大气中二氧化碳的含量，植树造林是比较好的措施，因为植物在光合作用时可大量地吸收二氧化碳，释放出氧气。植物吸收的这些二氧化碳在细胞内的哪个部位被合成了有机物：", "options": ["线粒体", "叶绿体", "中心体", "高尔基体"], "a": 1, "e": ".【B】本题考查光合作用，植物或部分细菌利用其细胞本身，在可见光的照射下，将二氧化碳和水转化为有机物，并释放出氧气的生化过程。这其中产生重要作用的是叶绿体。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-439", "q": "全球变暖为蚊子、苍蝇和病原微生物等提供了最佳的滋生繁衍条件，从而可以导致某些疾病的大流行。下列哪种疾病不会因此而流行：", "options": ["疟疾", "登革热", "心脏病", "流行性脑炎"], "a": 2, "e": ".【C】因为“心脏病”是指心脏器官的功能性病变，其原因不是由细菌和病毒引起的，所以“心脏病”不是传染病，不具备传染性。而疟疾、登革热和脑炎都是病毒引起的。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-440", "q": "每一种食物都有特殊的营养成分，食物搭配得当既美味又有利于营养吸收，促进健康，搭配不当则不仅不能吸收原有的营养成分，反而在一定程度上会损害人体的健康。下列食物搭配得当的是：", "options": ["虾与维生素", "", "鸭肉与山药", "螃蟹与茄子", "红糖与皮蛋"], "a": 1, "e": ".【B】A项错误，海产品由于含有砷，而维生素C是强氧化剂，因此，在氧化剂的作用下，砷会被氧化成三氧化二砷，也就是我们所俗称的砒霜；B项正确，鸭肉营养丰富，但是脂肪含量较高，山药则可以消除油腻感，山药和鸭肉同时食用，可降低血液中胆固醇的含量，还可起到很好的滋补效果；C项错误，螃蟹与茄子同食伤肠胃，容易造成拉肚子；D项错误，皮蛋忌红糖，食则泻肚。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-441", "q": "下列说法正确的是：", "options": ["广谱抗生素是非处方药可自行购买", "广谱抗生素的效果优于窄谱抗生素", "使用广谱抗生素不容易产生抗药性", "致病菌未知应优先选择广谱抗生素"], "a": 3, "e": ".【D】A项错误，抗生素是处方药，使用过量对机体不利，应该在医生指导下适量用药，不能自己随意用药。B项错误，广谱抗生素是指抗菌谱比较宽的药物，也就是能够抵抗大部分细菌的药物，与之相对的是窄谱抗生素，它指的是专门杀灭某一种或一类细菌的药物。广谱抗生素和窄谱抗生素各有用处，不存在优劣问题。C项错误，广谱抗生素是抗生素的一种，重复使用一种抗生素可能会使致病菌产生抗药性。D项正确，广谱抗生素主要是用在致病菌还未知，但需要杀菌的时候，如果致病菌已明确，就要用窄谱抗生素特异性地杀菌了。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-442", "q": "下列有关医药常识不正确的是：", "options": ["脾脏是人体的消化器官之一", "腮腺炎是呼吸道传染病", "河豚的毒素在其内脏中含量最高", "很多矿物质可以作为中药材使用"], "a": 0, "e": ".【A】A项错误，脾脏是人体最大的周围淋巴样器官，其实质由红髓和白髓构成，具有造血和血液过滤功能，也是淋巴细胞迁移和接受抗原刺激后发生免疫应答、产生免疫效应分子的重要场所；B项正确，腮腺炎是由腮腺炎病毒侵犯腮腺引起的急性呼吸道传染病，是儿童和青少年中常见的呼吸道传染病，成人中也有发病，由腮腺炎病毒所引起。C项正确，河豚毒素主要聚集在血液和内脏中。D项正确，硼砂、雄黄等矿物质也可作为中药使用。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-443", "q": "不是生物多样性的组成部分之一的是：", "options": ["遗传多样性", "物种多样性", "环境多样性", "生态系统多样性"], "a": 2, "e": ".【C】生物多样性是指一定范围内多种多样活的有机体（动物、植物、微生物）有规律地结合所构成的稳定的生态综合体。这种多样包括动物、植物、微生物的物种多样性，物种的遗传与变异的多样性及生态系统的多样性。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-444", "q": "下列有关新陈代谢的表述不正确的是：", "options": ["光合作用属于绿色植物新陈代谢的过程", "生物的新陈代谢过程都需要氧气的参与", "新陈代谢既有能量交换又有物质转化", "能否进行新陈代谢是区分生物与非生物的标准之一"], "a": 1, "e": ".【B】生物体与外界环境之间的物质和能量交换以及生物体内物质和能量的转变过程叫做新陈代谢。根据生物体在氧化作用过程中对氧的需求情况，新陈代谢的基本类型可以分为需氧型、厌氧型和兼性厌氧型三种。厌氧型这一类型的生物有乳酸菌和寄生在动物体内的寄生虫等少数动物，它们在缺氧的条件下，仍能够将体内的有机物氧化，从中获得维持自身生命活动所需要的能量。这种新陈代谢类型叫做厌氧型，也叫做无氧呼吸型。并非生物的新陈代谢都需要氧气的参与。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-445", "q": "某战士在抗击强台风“梅花”时，受伤失血过多需要输血。如果该战士是O 型血，则应给他输入：", "options": ["A 型血", "B 型血", "AB 型血", "O 型血"], "a": 3, "e": ".【D】输血时应该以输入同型血为原则。例如：正常情况下A型血人输A型血，B型血的人输B型血。紧急情况下，AＢ血型的人可以接受任何血型，Ｏ型血可以输给任何血型的人，但如果异血型者之间输血输得太快太多，输进来的凝集素来不及稀释，也可能引起凝集反应。但无论如何O型血只能接受输入O型血，否则含有A（或B）凝集原的红细胞与含有抗A（或抗B）凝集素的血清混合时，由于相对抗的凝集原和凝集素（如A与抗A）的相互作用，使红细胞凝集成团。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-446", "q": "运动中扭伤后可采取的正确措施是：", "options": ["立即用冰袋冷敷，以防止毛细血管破裂后充血", "立即用热水袋热敷，以促进血液循环，加快痊愈", "立即用手揉捏受伤处，以散解淤血，防止肿胀", "不做任何处理，等待其自然恢复"], "a": 0, "e": ".【A】一般而言，扭伤后应立即停止活动，在扭伤发生后的24小时内需采取冷敷处理（冷水、冰水、冰块等），使局部血管收缩，减少出血和渗出，减少肿胀，这对功能康复至关重要，千万不能揉或用酒精去按摩。24小时后可采取热敷或涂抹药膏活血化瘀。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-447", "q": "下列关于血管的说法，哪一项是错误的：", "options": ["血管包括动脉、静脉及毛细血管三大部分", "动脉是血液从全身流向心脏的管道，而静脉正好相反", "我们平常在自己胳膊上、腿上看到的“青筋”是静脉", "我们平常所说的脉搏，也就是医生诊病时所摸的脉，是动脉"], "a": 1, "e": ".【B】动脉是将从心脏流出的血液运送到身体各部位的血管，静脉正好与之相反。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-448", "q": "遗传变异与特种演化是生物界中存在的普遍现象，这种现象产生的原因是：", "options": ["有不同的“父母”的原因", "基因的重组或突变", "基因的交叉组合", "不同的生物之间的融合"], "a": 1, "e": ".【B】现代生物学研究显示，生物的衍化过程中出现的遗传变异与特种演化现象一般是由于基因的重组或突变。“不同的父母”或“不同生物的融合”可能偶尔会产生新的物种，但并不是“生物界中存在的普遍现象”。由此可知，基因的重组或突变才是遗传变异与特种演化的重要原因。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-449", "q": "生命中最主要的物质基础是：", "options": ["水和蛋白质", "核酸和蛋白质", "糖类和蛋白质", "脂类和蛋白质"], "a": 1, "e": ".【B】核酸和蛋白质是构成生命中最主要的物质基础，蛋白质是一种复杂的有机物，搭建生命体的基础单位，而核酸是遗传物质的载体，对物种延续和遗传有着决定作用。糖类和脂肪属于能量来源，并非构建生命的物质基础。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-450", "q": "下列关于各类植物的说法，不正确的是（）。", "options": ["裸子植物全都是木本植物", "无花植物不包括种子植物", "孢子生殖在被子植物中不存在", "人类的大部分食物和营养来源于被子植物"], "a": 1, "e": ".【B】本题考查生物常识。A项正确，裸子植物全部为多年生木本植物，大多为单轴分枝的高大乔木，少为灌木，稀为藤本；次生木质部几乎全由管胞组成，稀具导管。B项错误，无花植物可分为四大类：藻类、苔藓类、蕨类和裸子类。裸子植物既是颈卵器植物，又是种子植物。裸子植物是不开花植物中较先进的一种，具有深根及防止水分散失的叶子，所以可以长在较干燥的地方。C项正确，孢子生殖是很多孢子植物和真菌等利用孢子进行的生殖方式。孢子是细菌、原生动物、真菌和植物等产生的一种有繁殖或休眠作用的生殖细胞，能直接发育成新个体。用孢子繁殖的植物，主要包括藻类植物、菌类植物、地衣植物、苔藓植物和蕨类植物五类。极为密切的关系，人类直接地通过农作物或园艺作物如谷类、豆类、薯类、瓜果和蔬菜等，或者间接地通过被子植物为牧场提供牲畜所需的饲料。被子植物还提供建筑、造纸、纺织和塑料制品、油料、纤维、食糖、香料、虫蜡、医药、树脂、鞣酸、麻醉剂、饮料等多得不可计数的原材料。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-451", "q": "关于人体相关知识，下列表述错误的一项是（）。", "options": ["甲状腺激素由人体最大的内分泌腺所分泌", "砒霜其实也是一味中药", "胰岛素可以促进糖类转化为蛋白质和脂肪", "人体消化道中最长的器官是大肠"], "a": 3, "e": ".【D】本题考查科技常识。A项正确，甲状腺激素由甲状腺分泌，可以促进代谢，促进生长发育，提高神经系统的兴奋性（如体内甲状腺激素过多，人就会消瘦，且情绪容易激动）。甲状腺是人体最大的内分泌腺。B项正确，砒霜是一味中药。为砒石经升华而成的三氧化二砷精制品，具有蚀疮去腐，杀虫，劫痰，截疟之功效。常用于痔疮，瘰疬，痈疽恶疮，走马牙疳，癣疮，寒痰哮喘，疟疾等。C项正确，胰岛素由胰腺内的胰岛B细胞分泌，胰岛素的主要功能是调节糖类在体内的吸收（合成肝糖原、肌糖原）、利用（氧化分解产生能量）和转化（合成脂肪和蛋白质），从而降低血液内糖含量，平衡血糖浓度。当人体胰岛素分泌不足时，细胞吸收、利用和转化血糖的能力就会减弱，从而导致血糖浓度超过正常水平，一部分血糖就会进入尿液，形成糖尿。D项错误，人体消化道中最长的器官是小肠，小肠的长度占到整个胃肠道的，是食物消化吸收的主要场所。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-452", "q": "下列说法错误的是（）。", "options": ["马铃薯可供食用的部分是根部", "水果浆汁和蜂蜜中均含有果糖", "果冻中添加琼脂可以增稠凝固", "人体不能合成维生素", ""], "a": 0, "e": ".【A】本题考查科技常识。A项错误，马铃薯，又称土豆、洋芋等，块茎可供食用，是全球第四大重要的粮食作物，仅次于小麦、稻谷和玉米。故马铃薯可供食用的部分不是根部，是块茎。B项正确，果糖，是一种单糖，是葡萄糖的同分异构体。它以游离状态大量存在于水果的浆汁和蜂蜜中。C项正确，琼脂，学名琼胶，是植物胶的一种，为无色、无固定形状的固体，可用作增稠剂、凝固剂等。广泛用于制造各种饮料、果冻、糕点食品。D项正确，维生素C又叫抗坏血酸，是一种水溶性维生素。人体不能自主生成维生素C，因此必须每天从富含维生素C的食物中摄取来满足全身需要。维生素C在维持人体正常代谢和生理功能中发挥重要作用。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-453", "q": "根茎是植物的重要器官，对于根茎下列说法正确的是（）。", "options": ["根是植物蒸腾作用的主要器官", "根、茎都是植物的营养器官", "胡萝卜、生姜食用部位是茎", "土豆、红薯食用部位是根"], "a": 1, "e": ".【B】本题考查科技常识。A项错误，蒸腾是水分从活的植物体表面(主要是叶子)以水蒸汽的形式散失到大气中的过程。蒸腾作用的主要器官是叶，叶表皮的气孔是植物蒸腾失水的“门户”。B项正确，根除了支持植物体外，能给植物体运输水分和无机盐；茎除了支持植物体外，茎中木质部的导管能够自下而上运输水和无机盐，韧皮部的筛管能够将叶通过光合作用制造的有机物自上而下运输，供给其它组织细胞生命活动的需要；叶能够通过光合作用制造有机物储存在植物体内，利于植株的生长，因此根、茎、叶称作营养器官。C项错误，胡萝卜食用部位是植物的根，生姜食用部位是茎。根和茎的区别在于茎上都有叶、节、芽,而根则没有。D项错误，土豆（马铃薯）食用部位是茎，属于块茎，由茎的侧枝变态成的短粗的肉质地下茎，贮藏组织特别发达，内贮丰富的营养物质；红薯（甘薯、番薯）食用部位是根，属于贮藏根，里边存储有大量营养物质，用于植物度过冬天，是变态根的一种。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-454", "q": "下列关于植物蒸腾作用说法不正确的是（）。", "options": ["气孔蒸腾是植物蒸腾作用的最主要方式", "蒸腾作用可以降低叶片温度", "沙漠中的植物成针刺状是为了减少蒸腾作用", "蒸腾作用只发生在白天"], "a": 3, "e": ".【D】本题考查科技常识。蒸腾作用是水分从活的植物体表面（主要是叶子）以水蒸汽状态散失到大气中的过程。蒸腾作用不仅受外界环境条件的影响，而且还受植物本身的调节和控制，因此它是一种复杂的生理过程。其主要过程为：土壤中的水分→根毛→根内导管→茎内导管→叶内导管→气孔→大气。蒸腾作用分为皮孔蒸腾、角质层蒸腾和气孔蒸腾。木本植物经由枝条的皮孔和木栓组织的裂缝的蒸腾，叫做皮孔蒸腾；通过叶片和草本植物茎的角质层的蒸腾，叫做角质层蒸腾；通过气孔的蒸腾，叫做气孔蒸腾，气孔蒸腾是植物蒸腾作用的最主要方式。A项正确，通过气孔的蒸腾，叫做气孔蒸腾，气孔蒸腾是植物蒸腾作用的最主要方式。气孔是植物进行体内外气体交换的重要门户。水蒸气、二氧化碳、氧气都要共用气孔这个通道，气孔的开闭会影响植物的蒸腾、光合、呼吸等生理过程。B项正确，当太阳光照射到叶片上时，大部分能量转变为热能，如果叶子没有降温的本领，叶温过高，叶片会被灼伤。而在蒸腾过程中，水变为水蒸气时需要吸收热能，降低叶片的温度，保护植物不被阳光灼伤。C项正确，植物进行光合作用的过程中，必须和周围环境发生气体交换，植物体内的水分就不可避免地流失。沙漠里的植物为了适应干旱缺水、酷暑的环境，叶子退化变成了针状或刺状，减少了蒸腾面，最大限度地减少水分的蒸发，另一方面又能大量贮存水分。D项错误，只要植物气孔打开就会发生蒸腾作用，白天光照、温度高，蒸腾作用强，夜间只是蒸腾作用减弱，并不是没有蒸腾作用的发生。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-455", "q": "下列有关维生素的说法，错误的是（）。", "options": ["维生素均以维生素原的形式存在于食物中", "维生素能够产生能量，参与机体代谢", "维生素D 是唯一一种人体可以少量合成的维生素", "肝脏、牛奶中富含维生素B2"], "a": 1, "e": ".【B】本题考查科技常识。A项正确，维生素原指原来没有维生素活性，在体内能转变为维生素的物质，维生素均以维生素原（维生素前体）的形式存在于食物中。B项错误，维生素不是机体组织和细胞的组成成分，其不会产生能量。维生素的作用主要是参与机体代谢的调节，它在天然食物中仅占极少比例，但又为人体所必需。C项正确，对于大多数的维生素而言机体不能合成或合成量不足，不能满足机体的需要，必须通过食物获得，而维生素D是唯一一种人体可以少量合成的维生素。D项正确，维生素B2又叫核黄素，微溶于水，缺乏维生素B2易患口腔溃疡，其可通过肝脏、鸡蛋、牛奶、豆类等食物来补充。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-456", "q": "下列动物行为与求偶无关的是（）。", "options": ["孔雀开屏", "蜘蛛跳舞", "蜻蜓点水", "飞蛾传味"], "a": 2, "e": ".【C】本题考查科技常识。动物的求偶行为即交配前行为，是繁殖行为的重要环节，目的是吸引异性完成交配。动物求偶可通过声音、炫耀、行为动作、建巢穴、信息素、喂食以及一些其他方式中的一种或多种方式。A项正确，孔雀开屏是孔雀的一种本能的求偶表现。雄孔雀羽毛绮丽华美，尤其是背部羽毛和尾羽。当每年四五月生殖季节到来时，雄孔雀为了吸引雌孔雀常将尾羽高高竖起，形状像大圆扇，绚丽夺目。雌孔雀则根据雄鸟羽屏的艳丽程度来决定自己的选择，然后再进行交配。B项正确，蜘蛛在求偶时，雄蛛要在雌蛛面前做一番“舞蹈表演”，边跳舞边小心翼翼地向雌蛛靠近。这时，雌蛛如果不动，并把前两对足缩到胸前，轻轻抖动它的触须，就表示接受了对方的爱情。然后，雄蛛就会迈着轻快的步伐，爬进网内和雌蛛举行婚礼。如果雄蛛贸然前往，很有可能被雌蛛吃掉。C项错误，蜻蜓点水，是指蜻蜓在水面飞行时用尾部轻触水面，这是蜻蜓产卵生育后代的方式，蜻蜓排出的卵会在水草上孵化出幼虫，叫做“水虿”。因此，蜻蜓点水是蜻蜓产卵的方式，而不是求偶行为。D项正确，在雌蛾体上存在一种特殊的化学物质，即性外激素。通过性外激素的扩散，把雄蛾从遥远的地方招引来，进行交配。性外激素分泌的量虽然很少，但作用却很大。飞蛾这种以气味传情，寻找配偶的方式，在生物学中称为“化学通讯”。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-457", "q": "人们经常利用植物去判断生长地的环境，下列有关说法正确的是：", "options": ["矮牵牛含有的花青素对二氧化硫有指示作用", "树林中所有树冠西边稀疏东边繁盛，说明东风盛行", "胡杨的生长地土壤通常呈现深褐色", "地衣大量生长反映空气湿度较低​"], "a": 0, "e": ".【A】本题考查科技常识。A项正确，花青素的颜色因酸碱度不同而异，在酸性条件下呈红色，在碱性条件下为蓝色。随着一天从早晨到晚上空气中二氧化硫含量的增加，矮牵牛对二氧化硫吸收量也逐渐加大，花中的酸性不断提高，从而造成花色由蓝变红。B项错误，树木向风面的芽体由于受风的袭击而损坏，因此向风面枝条稀疏；而背风面的芽体则因受风的影响较小而存活较多。选项中树冠西边稀疏东边繁盛，说明风从西边吹来，即西风盛行。C项错误，胡杨主要分布于中国西北各地，喜沙质土壤，常于沙漠地区水源附近形成绿洲，故胡杨的生长地土壤通常呈现黄色。D项错误，地衣的生长一般喜爱高湿度、低温度及低光照强度。这些因素中湿度是其生长最重要的因素，因此地衣大量生长反映空气湿度较高。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-458", "q": "关于生物，下列说法错误的是：", "options": ["酸菜和腐乳的制作过程中都离不开乳酸菌的发酵", "病毒只能寄生在活细胞中进行生命活动", "细菌有完整的能量代谢系统，可以独立地生长繁殖", "木耳是真菌的一种，常生长在阴湿、腐朽的树干上"], "a": 0, "e": ".【A】A项错误，制作酸菜过程要用到乳酸菌，在无氧的条件下，乳酸菌发酵产生乳酸，使得酸菜具有特殊的风味；而腐乳的主要生产工序分为前期发酵和后期发酵，前期发酵使得豆腐上开始生长毛霉，前期发酵的作用，一是使豆腐表面有一层菌膜包住；二是毛霉分泌以蛋白酶为主的各种酶，有利于豆腐所含有的蛋白质水解为各种氨基酸。后期发酵通过腌制并配入各种辅料，促进其他生化反应，生成腐乳的香气。故在腐乳的制作过程没有乳酸菌的参与。B项正确，病毒没有细胞结构，不能独立生活，它具有高度的寄生性，必须依赖宿主细胞的能量和代谢系统，获取生命活动所需的物质和能量。因此，病毒只能寄生在活细胞中进行生命活动。C项正确，细菌是一种具有细胞壁的单细胞微生物。细胞是生命活动的单位，一些生命活动的基本过程，如物质代谢、能量转换、运动、发育、繁殖和遗传等，都是以细胞为结构基础来实现的。能进行能量转换是因细胞具有完整的能量代谢系统。细菌作为细胞生物，因而具有完整的能量代谢系统。D项正确，木耳是担子菌纲木耳科木耳属植物。担子菌纲是真菌门的一个大纲，因而属于真核生物。真核生物是一类比较高等的微生物，有完整的细胞核，主要靠菌丝体分解吸收现成的营养物质。木耳寄生于阴湿、腐朽的树干上，单生或本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-459", "q": "某人扁桃体化脓，医生建议其静脉注射头孢，药液从其手背静脉到达扁桃体患处所经过的途径是：上肢静脉→右心房→①→②→左心房→③→④→动脉→扁桃体毛细血管（患处）。依次填入①②③④正确的是：", "options": ["肺循环；右心室；左心室；主动脉", "左心室；肺循环；主动脉；右心室", "主动脉；右心室；左心室；肺循环", "右心室；肺循环；左心室；主动脉"], "a": 3, "e": ".【D】本题考查生物常识。人体内血液循环分为两大部分，体循环和肺循环。体循环是指血液由左心室进入主动脉，再流经全身的各级动脉、毛细血管网，各级静脉，最后汇集到上、下腔静脉，流回右心房的循环途径。肺循环是指血液由右心室进入肺动脉，流经肺部的毛细血管网，再由肺静脉流入左心房的循环途径。体循环和肺循环同时进行，并且在心脏处汇合在一起，组成一条完整的循环途径。本题中药物从上肢静脉随血液流入，进入右心房，然后到右心室，经过肺循环进入左心房，再到左心室进入体循环，经过主动脉，各级动脉，最后到达扁桃体毛细血管（患处）。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-460", "q": "克隆属于无性生殖。如果人们将黑色兔子的乳腺细胞核移植到白色兔子的去核卵细胞中，形成重组细胞，再经过一系列培育，克隆出一只兔子。那么，这只克隆兔子的毛色是（）。", "options": ["白色", "黑色", "黑白相间", "灰色"], "a": 1, "e": ".【B】本题考查与克隆相关的生物常识。克隆是指生物体通过体细胞进行的无性繁殖，以及由无性繁殖形成的基因型完细胞核是遗传物质的载体，白色兔子卵细胞，被剔除细胞核，再从黑色兔子乳腺细胞中取出细胞核，移植到白色兔子去核卵细胞内，胚胎发育时必然是黑色兔子的遗传性状得到表达，所以，克隆出的兔子毛色是黑色的。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-461", "q": "下列关于恐龙的说法正确的是：", "options": ["主要活跃在中生代时期", "霸王龙和剑龙都是肉食性动物", "属于脊椎亚门类动物中的哺乳纲", "可通过某个DNA 片段克隆出恐龙"], "a": 0, "e": ".【A】恐龙的祖先属于古生代，到了中生代开始发展壮大。恐龙生活在距今约24500万年至6500万年。因此中生代被誉为“恐龙的时代”，故A项正确。暴龙又名霸王龙，属暴龙科中体型最大的一种，名字的意思是残暴的蜥蜴王，是史上最庞大的陆地肉食性动物之一和最著名的食肉恐龙；剑龙为一种巨大的草食性恐龙，是一种生存在侏罗纪晚期的食草性动物，故B项错误。恐龙属于爬行纲，故C项错误。克隆需要完整的DNA序列，只有某个DNA片段没办法克隆完整的恐龙，故D项错误。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-462", "q": "下列与土壤有关的说法正确的是：", "options": ["犁地可以增加土壤中的矿物质", "红壤的pH 值大于7，是碱性土壤", "土壤的形成与岩石的风化作用有关", "土壤的有机质可被植物的根部直接吸收"], "a": 2, "e": ".【C】本题考查科技常识。A项错误，犁过的土地，土壤间隙增大，透气性好，水和空气能够很好地进入土壤中，并且能够很好地保留下来，并不能增加土壤中的矿物质。B项错误，酸性土壤是pH值小于7的土壤总称。包括砖红壤、赤红壤、红壤、黄壤和燥红土等土类。红壤是酸性土壤。C项正确，风化作用使岩石破碎，理化性质改变，形成结构疏松的风化壳，故土壤的形成与岩石的风化作用有关。D项错误，土壤的有机质不能被直接吸收，必须经过微生物的发酵，将有机物分解为无机物，比如铵态氮、硝态氮、矿物质离子，之后才能被吸收。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-463", "q": "下列与人体有关的说法错误的是：", "options": ["消化和吸收的主要场所是小肠", "尿液中糖分过多可能是由于胰岛素分泌不足", "分泌生长激素，促进人体生长发育的器官是垂体", "人能看清远处和近处的物体是因为瞳孔的大小可以调节"], "a": 3, "e": ".【D】本题考查科技常识。A项正确，小肠上端起于胃幽门口，下端止于回盲瓣，是消化管中最长的一部分，成人全长5-7m，按位置与形态，分为十二指肠、空肠和回肠三部分，是食物消化与吸收的主要场所。B项正确，胰岛素的主要功能是调节糖在体内的吸收、利用和转化等，如促进血糖合成糖元，加速血糖的分解，从而降低血糖的浓度，若胰岛素分泌不足，会使血糖浓度超过正常水平，导致尿液中糖分过多。C项正确，垂体是人体最重要的内分泌腺，分前叶和后叶两部分。它分泌多种激素，如生长激素、促甲状腺激素、促肾上腺皮质激素、促性腺素、催产素、催乳素、黑色细胞刺激素等，还能够贮藏并释放下丘脑分泌的抗利尿激素。这些激素对代谢、生长、发育和生殖等有重要作用。D项错误，人能够看清远近不同的物体，是因为睫状体能够调节晶状体的曲度大小，而瞳孔的大小是控制进入眼球内部光线的多少。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-464", "q": "下列关于植物种子传播方式的说法错误的是：", "options": ["柳树的种子利用风力传播", "樱桃会自己裂开通过弹力传播种子", "莲蓬的种子利用水流传播", "野葡萄靠鸟类食用和排泄传播种子"], "a": 1, "e": ".【B】本题考查科技常识。A项正确，柳树种子上有附生的白色绒毛，即柳絮，柳树种子成熟后靠柳絮随风飞扬把种子传播到远处。B项错误，樱桃种子的传播主要是靠鸟类或其他小型哺乳动物的食用和排泄。这些动物会把樱桃果实吃掉，种子很难消化，然后就会随着粪便排出，从而把种子传播开来。C项正确，莲蓬的种子是莲子，莲子能够长出新的植株，一般等莲子自然老去，会掉落到水中，随后随着水流遇到合适的环境就会自己发芽生长。D项正确，野葡萄是某些鸟类或小型哺乳动物的食物，被吃下后，种子会因为动物的迁移，随着它们的粪便四处传播，形成新的生命个体。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-465", "q": "下列说法正确的是：", "options": ["甲亢症患者应多食用富含碘元素的食物", "一般情况下，将水煮沸能起到软化作用", "声呐利用次声波定位物体位置，探测水的深度等", "洗洁精是利用表面活性剂将油污溶解成水的原理去污的"], "a": 1, "e": ".【B】本题考查生物常识。A项错误，甲亢是甲状腺功能亢进的简称。甲亢是由甲状腺激素分泌过多所致的一种分泌疾病。甲亢患者饮食应以高热量、高蛋白、高维生素，适量脂肪和钠盐摄入为原则，少用辛辣刺激性佐料食物和高碘食物，比如海带、紫菜、海蜇、海苔以及藻类食物等。B项正确，硬水软化就是将硬水中的钙、镁等可溶性盐除去的过程，硬水软化的方法很多，常用的有煮沸法、化学软化法、离子交换软化法等。C项错误，声呐是一种利用超声波在水下的传播特性，通过电声转换和信息处理，完成水下探测和通讯任务的电子设备。D项错误，洗洁精去污主要是依据乳化原理。借助乳化剂，一般乳化剂是两亲分子（既亲水又亲油），乳化剂的亲油端可以将油污包裹在里面，而亲水端露在外面。根据相似相溶原理，被乳化剂包裹的一个个“油污”便可以分散到水中，被洗涤下来。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-466", "q": "下列食物经过人体口腔能够初步消化的是：", "options": ["牛肉和鱼", "鸡蛋和牛奶", "青菜和螃蟹", "米饭和馒头"], "a": 3, "e": ".【D】本题考查科技常识。A项错误，牛肉和鱼肉中含有大量蛋白质和少量脂肪，口腔中不含蛋白酶和脂肪酶，不能完成牛肉和鱼的初步消化。蛋白质的消化开始于胃，蛋白质进入胃以后，在胃液中胃蛋白酶的作用下进行初步消化后进入小肠，小肠里的胰液和肠液含有消化蛋白质的酶，在这些酶的作用下，蛋白质被彻底消化为氨基酸而被人体吸收利用；而脂肪的消化开始于小肠，先是胆汁（不包含任何消化酶）将脂肪颗粒乳化为脂肪微粒，再在肠液和胰液中脂肪酶的作用下，被彻底分解为甘油和脂肪酸。B项错误，鸡蛋和牛奶的主要成分是蛋白质，在胃中完成初步消化。C项错误，青菜中含有大量纤维素，但由于人体缺乏分解纤维素的酶，因此青菜的主要成分在人体不能被消化吸收；螃蟹肉主要成分是蛋白质和脂肪，蛋白质在胃中完成初步消化，脂肪在小肠中完成初步消化。D项正确，米饭和馒头的主要成分是淀粉，口腔中含有唾液淀粉酶，能将淀粉初步分解为麦芽糖，因此米饭和馒头可以在口腔内初步消化。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-467", "q": "定的等级。下列属于动物社会行为的是（）。", "options": ["母猩猩哺育幼猩猩", "乌贼遇敌喷出墨汁", "蜂王依靠工蜂喂养", "狗为吃骨头而争斗"], "a": 2, "e": ".【C】本题考查生物常识。A项错误，母猩猩哺育幼猩猩属于亲子关系，其本身还不能视为社会行为，而应当视为动物的繁殖行为。繁殖行为是与动物繁殖后代有关的行为，主要包括识别、占有繁殖空间、求偶、交配、孵卵、哺育等。B项错误，乌贼遇敌喷出墨汁属于动物的防御行为，防御行为是指动物为对付外来侵略、保卫自身的生存、或者对本族D项错误，狗为吃骨头而争斗属于动物的攻击行为，攻击行为是指在动物界中，同种动物个体之间常常由于争夺食物、配偶，抢占巢区、领域而发生相互攻击或战斗。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-468", "q": "瑞典卡罗琳医学院10 月5 日宣布,将2015 年诺贝尔生理学或医学奖授予中国药学家屠呦呦以及爱尔兰科学家威廉·坎贝尔和日本科学家大村智。其中，屠呦呦的获奖理由是（）", "options": ["发现治疗蛔虫寄生虫新疗法", "发现构成大脑定位系统的细胞", "发现幽门螺杆菌及其在胃炎和胃溃疡中所起的作用", "发现治疗疟疾的新疗法"], "a": 3, "e": ".【D】2015年10月，屠呦呦获得诺贝尔生理学或医学奖，理由是她发现了青蒿素，这种药品可以有效降低疟疾患者的死亡率。她成为首获科学类诺贝尔奖的中国人。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-469", "q": "下列与动物行为有关的表述正确的是：", "options": ["蜜蜂用蜡筑造蜂房和蜘蛛织网均属本能行为", "本能行为不需要通过自然选择而进化", "动物的拟态现象不属于防御行为", "动物的行为不存在生理基础"], "a": 0, "e": ".【A】本题考查科技常识。A项正确，动物的行为分为先天性行为和学习行为。先天性行为是一种本能行为，由遗传物质决定，是生来就有的一种行为能力。蜜蜂筑巢、蜘蛛织网均属于动物的本能行为。而学习行为是在体内遗传因素的基础上，通过环境因素的作用，由生活经验和学习而获得的行为。如小狗做算术题。B项错误，先天性行为是一种本能行为，虽是由遗传物质决定的，但也需要通过自然选择进化而来。C项错误，拟态是指一种生物在形态、行为等特征上模拟另一种生物，从而使一方或双方受益的生态适应现象。某种动物通常模拟另一种动、植物或周围环境的形状、颜色、斑纹等，借以保护自身、免受其他动物攻击。因此，动物的拟态现象通常属于防御行为。D项错误，神经系统和内分泌系统是动物行为的生理学基础，因此，动物行为存在生理基础。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-470", "q": "血液透析后，发生的最主要变化是（）。", "options": ["蛋白质增加", "二氧化碳减少", "含氧废物减少", "氧气增加"], "a": 2, "e": ".【C】本题考查科技常识。血液透析（HD）是急慢性肾功能衰竭患者肾脏替代治疗方式之一。它通过将体内血液引流至体外，经一个由无数根空心纤维组成的透析器中，血液与含机体浓度相似的电解质溶液（透析液）在一根根空心纤维内外，通过弥散、超滤、吸附和对流原理进行物质交换，清除体内的代谢废物，维持电解质和酸碱平衡，同时清除体内过多的水分，并将经过净化的血液回输。血液透析液中的一些小分子的溶质及水分即通过空心纤维上的小孔进行交换，交换的最终结果是血液中的尿毒症毒素及一些电解质、多余的水分进入透析液中被清除，透析液中一些碳酸氢根及电解质进入血液中。从而达到清除毒素、水分、维持酸碱平衡及内环境稳定的目的。因此血液透析后，含氧废物将大大减少。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-471", "q": "农村学生营养午餐改善计划实施以来，学生的身体素质得到提高。某学校为学生提供的一份午餐包括馒头、素炒黄瓜、苹果。这份午餐搭配中缺少的营养元素是：", "options": ["油脂", "蛋白质", "维生素", "糖类"], "a": 1, "e": ".【B】馒头是以面粉经发酵制成，主要营养成分是碳水化合物（糖类），是人们补充能量的基础食物。素炒黄瓜中含有一定量的油脂和维生素。苹果被称为“全方位的健康水果”，含有丰富的碳水化合物、维生素和微量元素。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-472", "q": "下列关于血糖的说法错误的是：", "options": ["正常人进食后血糖浓度会升高", "正常人空腹超过12 小时会引起低血糖", "南瓜能抑制葡萄糖吸收，具有降血糖作用", "胰岛素是人体产生的唯一能够降低血糖的激素"], "a": 1, "e": ".【B】本题考查科技常识。A项正确，食物中存在大量的淀粉等糖类。人在进食后，糖类被人体消化吸收，因此会使血糖含量升高。B项错误，空腹（禁食）数小时不吃饭会导致血糖浓度降低，此时会刺激胰高血糖素分泌增加，促进肝糖原和非糖物质转化为葡萄糖，以维持正常的血糖浓度，因此不会出现题目中表述的低血糖。C项错误，人们普遍认为，南瓜含糖量均较低，其中的南瓜多糖能有效地控制糖尿病症状，可刺激胰岛素的分泌，从而抑制葡萄糖吸收，产生降糖功能。但新华网等则认为南瓜不降血糖。D项正确，胰岛素是体内唯一能够降低血糖浓度的激素，它不仅能够促使葡萄糖分解，还能抑制非糖物质转化为葡萄糖。本题为选非题，正确答案为BC，从命题角度考虑，粉笔题库倾向性答案为B。", "tag": "科技常识"},
{"id": "tech-473", "q": "在温暖的环境中，苹果、梨放久了会逐渐变成空心，重量明显减轻。其主要原因是（）。", "options": ["苹果、梨的蒸腾作用散失了较多的水分", "苹果、梨的呼吸作用消耗了其中的有机物", "苹果、梨的中央被细菌、真菌分解掉了", "苹果、梨细胞的分裂和生长停止"], "a": 1, "e": ".【B】本题考查科技常识。A项错误，蒸腾作用指的是植物通过蒸发而失水的过程。苹果、梨进行蒸腾作用，散失了较多的水分，这样将会导致其大量失水，出现皮皱缩现象，但不会出现空心现象。B项正确，植物的呼吸作用是指植物体吸收氧气，将有机物转化为二氧化碳和水并释放能量的过程。在温暖的环境中久放的苹果、梨会逐渐变成空心，重量明显减轻是因为苹果、梨进行呼吸作用，体内的有机物消耗较多，有机物减少，使其空心。C项错误，苹果、梨被周围的细菌和真菌等分解者分解，会出现腐烂现象，但不会出现空心现象。D项错误，苹果、梨长成后，高度分化的细胞的确会停止分裂和生长，但不会出现空心现象。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-474", "q": "春天来了，花红柳绿、鸟语花香。下列关于有花植物说法正确的是：", "options": ["花的香气吸引昆虫有利于花粉的传播", "漫天飞舞的柳絮是柳树的花", "鸟类取食果实不利于植物繁衍", "雌花、雄花都可以结出果实"], "a": 0, "e": ".【A】A项正确：多数有花植物依靠昆虫传播花粉进行繁殖，花的香气可以吸引昆虫来采花粉，促进花粉传播。B项错误：漫天飞舞的柳絮是柳树的种子。C项错误：鸟类取食植物的种子和果实后，随着鸟的飞行，一些没有消化的种子随粪便排出体外，而后萌发生长，因此鸟类取食果实有利于植物的繁殖。D项错误：雄花不能结果，只有雌花结果。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-475", "q": "木本植物指根和茎因增粗生长形成大量的木质部，而细胞壁也多数木质化的坚固的植物，是草本植物的对应词，以下属于木本植物的是（）", "options": ["牡丹", "玉米", "菊花", "棉花"], "a": 0, "e": ".【A】A项正确：木本植物依形态不同可分为乔木、灌木和半灌木三类，牡丹是多年生落叶小灌木，茎高达2米，分枝短而粗，属于木本植物；B项错误：玉米是禾本科玉蜀黍属，是一年生草本植物；C项错误：菊花是菊科、菊属的多年生宿根草本植物；D项错误：棉花是锦葵科棉属植物的种籽纤维，是一年生草本植物。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-476", "q": "关于贫血，下列说法正确的是：", "options": ["体内叶酸缺乏会导致贫血", "用铁锅炒菜可有效预防缺铁性贫血", "葡萄糖酸锌口服液可预防小儿贫血", "做血常规抽血出现眩晕是因为贫血"], "a": 0, "e": ".【A】本题考查科技常识。A项正确，体内缺乏叶酸，可形成巨幼红细胞性贫血，易出现头晕、乏力、腹痛，腹泻，唇炎，舌炎，可口服叶酸和b12来治疗。B项错误，在高温下，铁元素会少量的渗入食物中，在客观上起到补铁的作用。但是铁锅溶出的铁元素为非血红素铁，能被人体吸收的比例并不高，而人体血液所需的、且能更有效吸收的是血红素铁，因此铁锅炒菜不能有效预防缺铁性贫血，如需有效预防还需要补充富含铁的食物。C项错误，常见小儿贫血有缺铁性贫血、营养性巨幼细胞性贫血、溶血性贫血。葡萄糖酸锌口服液可用于治疗缺锌引起的营养不良、厌食症、儿童生长发育迟缓等。该口服液主要是补充锌元素，对锌缺乏引起的食欲不佳有一定的改善作用，对于营养不良引起的贫血能起到间接辅助作用，而不能治疗其他原因引起的小儿贫血。D项错误，血常规抽血量不大，引起眩晕的原因可能是晕血症，也可能是血糖低，并不能确定是贫血引起的。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-477", "q": "下列有关输血和输液的说法错误的是：", "options": ["输血时一般应该是以输同型血为原则", "根据病情需要有时可以进行成分输血", "成年人一次献血500cc 不影响健康", "输血前先鉴定献血者与受血者血型"], "a": 2, "e": ".【C】C项错误，人体血液量一般是体重左右，一个体重50公斤的人，血液量约4公斤，也就是4000毫升左右，一次性失血不超过血液总量是安全的。因此我国规定献血者体重男士50公斤以上,女士45公斤以上，一次献血量最高为400毫升，这样可以保证每个献血者献血都在安全范围。因此成年人一次献血500毫升可能会影响健康。A项正确，输血以输同型血为原则。例如：正常情况下A型人输A型血，B型血的人输B型血。紧急情况下，AB血型的人可以接受任何血型，O型血可以输给任何血型的人。B项正确，根据病情需要有时可以进行成分输血，即将血液的各种成分加以分离提纯通过静脉输入体内，优点为：一血多用，节约血源，针对性强，疗效好，副作用少，便于保存和运输。D项正确，输血前先鉴定献血者与受血者血型，输血时一般应该是以输同型血为原则。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-478", "q": "下列关于生物常识的说法错误的是：", "options": ["基因工程育种能产生新的基因，改变生物性状", "酵母呼吸作用产生的二氧化碳可使馒头膨大松软", "向日葵向阳而生是由于光引起其生长素分布不均", "加酶洗衣粉能平整织物表面，是因为它有纤维素酶"], "a": 0, "e": ".【A】本题考查科技常识。A项错误，所谓基因工程是指在体外将核酸分子插入病毒、质粒或其他载体分子，构成遗传物质的新组合并使之掺入到原先没有这类分子的寄主细胞内，而能持续稳定地繁殖的技术。或者说，基因工程是对DNA（脱氧核酸）大分子上的遗传单元（基因）进行体外操作，把不同来源的基因按照单元设计的蓝图，重新构成新的基因组合（即重组），再把它引入细胞中，构成具有新的遗传特性的生物。基因工程的原理是基因重组，而不是产生新的基因。B项正确，面粉里的酵母菌将葡萄糖发酵，酵母菌分解葡萄糖产生丙酮酸，丙酮酸在缺氧和微酸性的条件下，转变成酒精同时产生二氧化碳，二氧化碳遇热膨胀，蒸熟的馒头就会暄软多孔。C项正确，向日葵的生长素主要在茎尖形成，并向基部运输。生长素的分布受到光的影响：向光的一侧生长素浓度低，背光的一侧浓度高。这样，向光的一侧生长区生长较慢，背光的一侧生长区生长较快，由此茎就产生了向光性弯曲。D项正确，目前在加酶洗衣粉中使用的共有4种：蛋白酶、脂肪酶、淀粉酶、纤维素酶。纤维素酶的作用对象不是衣物上的污垢，而是织物表面因多次洗涤而在主纤维上出现的微毛和小绒球。用纤维素酶处理后，织物表面的微毛和绒球就被除去，可以平整织物表面，同时有增白效果。另外，纤维素酶将主纤维上的微毛和绒球除去后，使主纤维变得光滑，减少了微纤维之间的纠缠，而使纤维变得柔软。因此添加纤维素酶的洗衣粉具有增白、柔软两个独特功能。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-479", "q": "日常生活中，人们通常把鱼出现上浮并翻肚子称为“翻塘”，该情形极易导致鱼死亡，那么，若无污染、沼气等影响，在一天中，鱼儿最容易因缺氧而“翻塘”的时间是（）。", "options": ["早晨", "上午", "下午", "晚上"], "a": 0, "e": ".【A】本题考查科技常识。影响水体溶氧最主要的几个因素中，首先是温度，水温升高，水体的细菌、藻类、鱼类和其它水生动物活动加强，水中的溶氧就会降低；水温越高，水中溶氧的饱和度就越低。一天之中，池塘中的溶氧也是动态变化的。白天光照强，通过光合作用产生较多的氧气溶解于水中，中、上层水的溶解氧在自然状态下开始上升，在中午过后逐渐达到最高值，溶解氧甚至能达到过饱和状态。到了夜晚，由于没有了光合作用，而池塘内对氧气的消耗量并没有明显减少，使得水体的溶解氧含量逐渐减少，一天之中黎明和清晨的温度最低，所以一天中，早晨池塘中的氧最少。因此早晨最容易出现鱼儿最容易因缺氧而“翻塘”。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-480", "q": "下列关于维生素说法错误的是：", "options": ["人体无法完全依靠自身合成维生素，食物是人类获取维生素的主要来源", "维生素", "K 的重要作用分别是抗氧化、延缓衰老和维持视力、免疫力", "维生素可分为水溶性维生素和脂溶性维生素，维生素D 属于后者", "新鲜的西红柿、猕猴桃、辣椒等果蔬含有丰富的维生素", ""], "a": 1, "e": ".【B】本题考查生物常识。需结合具体选项予以分析。A项正确，研究发现，早在40亿年以前，维生素对原始生物来说就已经必不可少了。原始生命可以自己合成维生素，但有些物种却失去了这样的能力——比如我们人类，自身仅能合成维生素D，必须依靠其他物种才能取得维生素，新鲜水果和蔬菜是人类获取维生素的主要食物来源。B项错误，维生素E能抗氧化、保护机体细胞免受自由基的毒害，延缓衰老、有效减少皱纹的产生，保持青春的容貌；维生素K主要功能为促进血液正常凝固。维持视力、免疫力的是维生素A。C项正确，维生素是个庞大的家族，现阶段所知的维生素就有几十种，大致可分为脂溶性和水溶性两大类。维生素D为类固醇衍生物，属于脂溶性维生素。D项正确，维生素C的主要食物来源是新鲜蔬菜与水果。《中国食物成分表2012修正版》中记录，每100新鲜的西红柿、猕猴桃、辣椒分别含维生素C的量为19、62、144。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-481", "q": "下列选项中，不是生命体共同特征的是（）。", "options": ["新陈代谢", "光合作用", "生长和繁殖", "遗传和变异"], "a": 1, "e": ".【B】本题考查科技常识。A项正确，新陈代谢是生物体内全部有序化学变化的总称，其中的化学变化一般都是在酶的催化作用下进行的。一切生物都能进行新陈代谢，故属于生命体共同特征。B项错误，光合作用，通常是指绿色植物或部分藻类吸收光能，把二氧化碳和水合成富能有机物，同时释放氧气的过程。而除了绿色植物或部分藻类外，其他生物并不能进行光合作用，故不属于生命体共同特征。C项正确，一切生物都可以进行生长和繁殖，故属于生命体共同特征。D项正确，遗传就是子代在这个连续系统中重复亲代的特性和特征（性状）的现象，其实质则是由于亲代所产生的配子，带给子代按亲代性状进行发育的遗传物质──基因。相同的基因规定着生物体发育相同的性状，于是表现为遗传，体现了生物界的稳定性。但这种稳定性是相对的，因为基因在世代延绵的长期发展过程中，难免会在此时或彼时发生结构的改变。结构改变了的基因使生物体发育不同于改变前的性状，于是出现了变异（可遗传变异）。一切生物都可以进行遗传和变异，故属于生命体共同特征。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-482", "q": "关于人体器官——小肠，下列说法正确的是：", "options": ["小肠是人体食物消化、废物排泄的主要器官，其长度影响食物消化和废物排出", "小肠是人体食物消化和营养吸收的主要器官，其长度影响消化和吸收", "小肠是人体食物储存的主要器官，其长度缩短后影响了食物的储存", "小明的营养不良症与小肠的长短无关"], "a": 1, "e": ".【B】本题主要考查生物常识。AC项错误，就位置来讲，小肠位于腹中，上端接幽门与胃相通，下端通过阑门与大肠相连，一般根据形态和结构变化分为三段，分别为十二指肠、空肠和回肠，是食物消化吸收的主要器官，而不是废物排泄的主要器官，也不是人体食物储存的主要器官。B项正确，就构成来讲，小肠由一层细胞组成，其管壁由黏膜、黏膜下层、肌层和浆膜构成。其中小肠粘膜，特别是空肠，具有许多环状皱襞和绒毛，大大扩大了粘膜的表面积，有利于营养物质的消化和吸收，切除部分小肠直接影响到食物的消化和营养的吸收。D项错误，人体营养不良症指的是由于摄入不足、吸收不良或过度损耗营养素所造成的营养不足,也可能包含由于暴饮暴食或过度的摄入特定的营养素而造成的营养过剩。与小肠的消化和吸收有关，涉及到小肠的长短。因此，人体的营养不良症与小肠的长短有关。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-483", "q": "关于马铃薯，下列说法中错误的是：", "options": ["通过块茎繁殖", "原产于南美洲", "我国唐朝已经有种植记录", "是茄科茄属一年生草本植物"], "a": 2, "e": ".【C】本题主要考查生物常识的基本内容。A项正确，马铃薯主要利用块茎进行无性繁殖。B项正确，马铃薯原产于南美洲安第斯山区，人工栽培历史最早可追溯到大约公元前8000年到5000年的秘鲁南部地区。C项错误，根据我国科学家对资料的考证认为，马铃薯最早传入中国的时间是在明万历年间（1573年至1619年），明万历年间蒋一葵撰著的《长安客话》卷二《黄都杂记》中，记述北京地区种植的马铃薯称为土豆。康熙二十一年（1682年）编撰的《畿辅通志》物产部是我国记载马铃薯最早的志书，18世纪中叶马铃薯在京津地区已经广泛种植。所以“我国唐朝已经有种植记录”说法错误。D项正确，根据《马铃薯及其近缘种的利用》在分类学上，所有马铃薯都属于茄科茄属马铃薯亚属马铃薯组。起源于拉丁美洲秘鲁和玻利维亚等国的安第斯山脉高原地区。马铃薯是马铃薯亚组中能形成地下块茎的一年生草本、多倍性作物。故D项正确。（文献出处：金黎平.[A].中国农业科学院中国作物学会马铃薯专业委员会.2005年全国马铃薯产业学术年会论文集[C].）本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-484", "q": "植物在自然环境中会遇到生物胁迫，比如食植动物和各种病原微生物的侵害，在进化过程中，植物发展了多种物理和化学防御机制。下列叙述中，不属于植物防御生物胁迫的是：", "options": ["玫瑰长刺", "睡莲长出宽大的叶子", "巨魔芋的花散发烂鱼臭虾似的臭气", "伞形科植物释放特殊气味吸引胡蜂捕食其体上的毛毛虫"], "a": 1, "e": ".【B】本题考查科技常识。A项正确，玫瑰是一种叶子嫩绿、多花的植物，而这种植物恰好是许多食草动物喜欢的食物，这便是玫瑰遇到的生物胁迫，为了不被动物吃掉，在进化过程中，玫瑰慢慢生出了又尖又硬的刺，属于物理防御机制。B项错误，睡莲长出宽大的叶子是为了增大光合作用面积，更好的利用阳光进行光合作用，并非是为了应对生物胁迫。C项正确，巨魔芋的花朵开放时，会发出阵阵恶臭，一方面是为了招引苍蝇、甲虫等帮助传粉，另一方面也让一些食草动物无法接近，更好的保护自己，属于化学防御机制。D项正确，毛毛虫是伞形科植物遇到的生物胁迫，伞形科植物释放特殊气味吸引胡蜂捕食毛毛虫，属于化学防御机制。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-485", "q": "随着地球环境的变迁，地球生物也随之不断演化。下列关于生物进化的表述正确的是：", "options": ["个体是生物进化的基本单位", "地理隔离是物种形成和进化的必要条件", "在生物进化中自然选择的作用是不定向的"], "a": 1, "e": ".【B】本题考查科技常识。B项正确，遗传与变异是遗传现象中不可分离的两个方面，遗传和变异是对立的统一体，如果没有遗传的变异，就不会产生新的生物类型，生物就不能由简单到复杂、由低等到高等地不断进化，遗传使物种得以延续，变异则使物种不断进化，遗传与变异是生物界普遍发生的现象，也是物种形成和生物进化的基础。C项错误，隔离是物种形成的必要条件。隔离分生殖隔离与地理隔离，生殖隔离的形成往往先经过长期地理隔离，然后达到生殖隔离后就形成不同的物种。但物种的形成不一定经过地理隔离，如多倍体的形成。而生物进化与地理隔离没有必然联系，生物通过产生大量的样本增加变异的机率，因此繁殖过剩是生物进化的必要条件。频率会发生定向改变，导致生物朝着一定的方向不断进化，因此生物的变异是不定向的，自然选择是定向的。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-486", "q": "下列有关生物知识的表述错误的是：", "options": ["基因水平的突变一定会影响生物学习性的改变", "鱼类的偶鳍与人体的四肢是同源器官", "最低等的动物和植物都是单细胞的"], "a": 1, "e": ".【B】本题考查科技常识。B项错误，基因突变指基因组DNA分子发生的突然的、可遗传的变异现象。基因突变一定会导致基因结构的改变，但由于密码子的简并性等原因，基因突变不一定引起生物学习性的改变。C项正确，同源器官指不同生物的某些器官在基本结构、与生物体的相互关系以及胚胎发育的过程彼此相同，但在外形上有时并不相似，功能上也有差别。鱼的偶鳍与人体的四肢虽然具有不同的外形，功能也并不尽相同，但却有相同的基本结构，身体的相对位置也相同，故是同源器官。D项正确，在动物界中，最古老、最低等、最原始、结构最简单的是原生动物，只有一个细胞构成；在植物界，最原始、最低等的植物是藻类植物，它们结构简单，都无根、茎、叶的分化，多为单细胞，也有多细胞，其中最低等的植物为单细胞。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-487", "q": "关于人体细胞，下列说法正确的是：", "options": ["癌变后失去了增殖功能", "可以合成蔗糖和葡萄糖", "细胞器散布在细胞质中", "同一个体不同功能的细胞中含有的基因组不同"], "a": 2, "e": ".【C】本题考查生物学常识，主要涉及人体细胞及其组成的相关知识点。A项错误，癌变是指细胞在致癌因子的作用下，遗传物质发生变化，变成不受机体控制的、连续进行分裂的恶性增殖细胞。在适宜的条件下，癌细胞能够无限增殖。B项错误，人体细胞不能合成蔗糖和葡萄糖。葡萄糖、蔗糖是靠进食摄入，人体内可以把蛋白质等非糖物质转化为葡萄糖，也可以将淀粉等多糖物质分解为葡萄糖，而不能自行合成。蔗糖是普遍存在于植物中的二糖，不存在于人体细胞内。C项正确，细胞质是一种细胞内的凝胶状物质，是生命活动的主要场所。细胞器是分布于细胞质内，具有一定形态、在细胞生理活动中起重要作用的结构。D项错误，23对染色体共同构成了人类的基因组，这些基因是DNA分子上具有遗传效应的特定核苷酸序列的总称，是具有遗传效应的DNA分子片段。对同一个体来说，细胞都含有相同的基因组。但由于基因的选择性表达不同，从而使得其具有不同的功能。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-488", "q": "以下对人的各种感觉描述不正确的是：", "options": ["触觉感受器大部分存在于皮肤中，指尖尤其敏感", "人看到物体时，视网膜上会形成一幅上下颠倒的影像", "耳朵可以帮助人体保持平衡", "嗅觉和味觉是一起工作的，感知食物味道更多依赖味觉"], "a": 3, "e": ".【D】D项错误：我们的舌头其实只能分辨基础的味觉感知，如酸、甜、苦、咸这些。而对于味道的整体感知更多是依靠嗅觉系统完成的。所以人在感冒鼻塞时，往往尝不出食物的味道。A项正确：触觉感受器是接受接触刺激，传导触觉和压觉的感受器，大量存在于皮肤当中。皮肤表面散布着触点，尤其指腹处最多，所以指尖的触觉最为敏感。B项正确：人眼的结构相当于一个凸透镜，外界物体在视网膜上所成的像是倒立缩小的实像。因此，人看到物体时，视网膜上形成的影像实际是上下颠倒的。C项正确：人体维持平衡主要依靠内耳的前庭部、视觉、肌肉和关节等本体感觉三个系统的相互协调来完成的。其中内耳的前庭系统最重要。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-489", "q": "下列关于基因工程表述正确的是：", "options": ["各种遗传病的基因异常是不同的，同一遗传病的基因异常是相同的", "基因治疗就是把缺陷基因诱变成正常基因", "基因诊断的基本原理就是DNA 分子杂交", "一种基因探针能检测水体中的各种病毒"], "a": 2, "e": ".【C】本题考查科技常识。A项错误，人类的遗传病主要可以分为单基因遗传病、多基因遗传病和染色体异常遗传病三大类，其中多基因遗传病中的任一个基因变异都可能会得遗传病，因此同一遗传病的基因变异可能是不同的。B项错误，基因治疗是指用正常基因取代或修补病人细胞中有缺陷的基因，以纠正或补偿因基因缺陷和异常引起的疾病，达到治疗目的。C项正确，基因诊断的基本原理是DNA分子杂交，指用放射性同位素、荧光分子等标记的DNA分子做探针，利用DNA分子杂交原理，鉴定被检测样本上的遗传信息，从而达到检测疾病的目的。D项错误，基因探针是一段带有标记的，与待测基因有关的核酸序列，而各种病毒的核酸序列各不相同。因此一种基因探针只能检测水体中的一种病毒。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-490", "q": "人们常说“种豆可以肥田”，这是因为：", "options": ["豆科植物根上的根瘤菌具有固氮能力", "豆科植物根上的根瘤菌具有固磷能力", "豆科植物根上的根瘤菌具有固钾能力", "豆科植物光合作用能力强"], "a": 0, "e": ".【A】本题考查科技常识。A项正确，B、C、D三项错误。豆科植物中含有一种与豆类根部共生形成根瘤并能固氮的细菌，一般指根瘤菌属和慢生根瘤菌属。根瘤菌聚集在豆类作物的根毛周围，通过分泌一种纤维素酶，将根毛细胞壁溶解掉，随后根瘤菌从根毛尖端侵入根的内部，直到根的内皮层。根瘤菌分泌的一些物质促使内皮层处的薄壁细胞快速分裂，细胞数目增多，体积增大。与此同时，根瘤菌在皮层的薄壁细胞内大量繁殖，最终在根的表面形成“瘤子”。根瘤菌能够固定大气中的氮，不仅供给豆科植物生长需要的氮肥，还可以提高土壤的肥力，因此人们常说“种豆可以肥田”。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-491", "q": "人体在遇到寒冷时会触发一系列生理机制来应对，下列说法错误的是：", "options": ["发抖是通过骨骼肌的颤抖形成热量", "人体的体温随着温度降低相应降低，减少能量需求", "汗毛下的竖毛肌收缩形成“鸡皮疙瘩”，减少热量流失", "肾上腺素会加大分泌量，促进新陈代谢，增加热能供应"], "a": 1, "e": ".【B】本题考查科技常识。A项正确，人处于寒冷环境中时，会出现骨骼肌不由自主地颤抖，使得肌肉运动热量增加，以保持体温稳定。B项错误，人体主要通过调节产热和散热来维持体温的恒定，当外界温度低时，机体产热多，散热减少；当外界温度高时，机体产热少，散热增加，所以正常人的体温是相对恒定的。C项正确，当外界温度较低时，人体表面汗毛下的竖毛肌收缩，就是起“鸡皮疙瘩”，使得毛孔散热减少，减少热量流失，以保持体温稳定。D项正确，天气寒冷时，人体激素如肾上腺素、甲状腺激素等分泌增多，促进细胞新陈代谢加强，增加热量的产生，以维持体温稳定。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-493", "q": "二氧化碳虽然只占了空气总体积的0.03，但对动植物的生命活动起着极为重要的作用。自然界中二氧化碳的循环与下列过程无关的是", "options": ["人和动物的呼吸", "发展利用氢燃料", "含碳燃料的燃烧", "植物的呼吸作用"], "a": 1, "e": ".【B】本题考查生物常识。需结合具体选项予以分析。A项正确，人和动物的呼吸会产生二氧化碳。B项错误，氢燃料燃烧的产物是水，没有二氧化碳。C项正确，含碳燃料燃烧会产生二氧化碳。D项正确，植物的呼吸作用会产生二氧化碳。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-494", "q": "一段朽木上面长满了苔藓、地衣，朽木凹处聚积的雨水中还生活着孑孓，水蚤等，树洞中还有老鼠、蜘蛛等，下列各项中，与这段朽木的“生命系统层次”水平相当的是：", "options": ["一块稻田里的全部害虫", "一个池塘中的全部鲤鱼", "一片松林中的全部生物", "一间充满生机的温室大棚"], "a": 3, "e": ".【D】D项正确：“一间充满生机的温室大棚”也属于生态系统，所以D项正确；本题在解答时可采用排除法：A、B、C三个错误选项中都出现“全部”字眼，“全部”所指向的都是单纯的生物，没有类似“朽木”这种无机环境，可加以排除，推出D项为正确项。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-495", "q": "植物的六大器官，根、茎、叶、花、果实和种子都可以成为人类的食物，但不同植物被取食的器官各有不同。下列植物与被取食的器官对应关系，错误的是。", "options": ["萝卜—根", "白菜—叶", "竹笋—茎", "西兰花—果实"], "a": 3, "e": ".【D】本题考查科技常识。A项正确，萝卜是十字花科属能形成肥大肉质根的二年生草本植物，它的食用部分是肉质根。B项正确，白菜分结球与不结球两类，是一种叶菜类蔬菜，它的食用部分是叶。C项正确，竹笋是禾本科竹亚科植物苦竹、淡竹、毛竹等的嫩茎，它的食用部分是茎。D项错误，西兰花是十字花科芸苔属甘蓝种中以绿色花球为产品的一个变种，它的食用部分为绿色幼嫩花茎和花蕾，而不是果实。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-496", "q": "面包制作过程中使用酵母主要是利用其哪一种特性：", "options": ["酵母在生长过程中可合成蛋白", "酵母在生长过程中可分解淀粉", "酵母在生长过程中可产生乙醇", "酵母在生长过程中可产生二氧化碳"], "a": 3, "e": ".【D】酵母在面包制作中的功能：", "tag": "科技常识"},
{"id": "tech-497", "q": "下列关于人体衰老的生理现象，说法错误的是", "options": ["骨组织随人体衰老而钙质渐减，易骨折，创伤愈合缓慢", "老年人真皮乳头变低，表皮与真皮界面变平，表皮会变薄", "老年人脑重较年轻时减轻，主要原因在于神经细胞的丧失", "老年人年龄越大，肌重与体重的比例会越来越高"], "a": 3, "e": ".【D】本题考查生物常识。衰老，是指机体各器官功能普遍的、逐渐降低的过程。A项正确，人体衰老时，骨骼系统的表现是：骨组织随年龄衰老而钙质渐减，骨质变脆，易骨折，创伤愈合也比年轻时缓慢。关节活动能力下降，脊柱变短。B项正确，人体衰老时，皮肤的表现是：真皮乳头变低，表皮变薄，真皮网状纤维减少，弹性纤维渐失弹性且易断裂，胶原纤维更新变慢，老纤维居多，胶原蛋白交联增加使胶原纤维网的弹性降低。皮肤松弛，真皮含水量降低，皮下脂肪减少，汗腺、皮脂腺萎缩，由于局部黑素细胞增生而出现老年斑。C项正确，人体衰老时，神经系统的表现是：人脑重较年轻时减轻，造成减重的原因主要在于神经细胞的丧失。这种丧失有区域的特异性，例如大脑不同区域细胞减少程度不同。D项错误，人体衰老时，肌肉的表现是：老年人肌重与体重之比下降，整个肌肉显得萎缩，这种衰老变化因功能不同而异。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-498", "q": "因意外事故，小明的小肠被切除1 米，他因此患上了营养不良症。对此，下列说法正确的是：", "options": ["小肠是人体食物消化、废物排泄的主要器官，其长度影响食物消化和废物排出", "小肠是人体食物消化和营养吸收的主要器官，其长度影响消化和吸收", "小肠是人体食物储存的主要器官，其长度缩短后影响了食物的储存", "小明的营养不良症与小肠的长短无关"], "a": 1, "e": ".【B】本题考查生物常识。就位置来讲，小肠位于腹中，上端接幽门与胃相通，下端通过阑门与大肠相连，一般根据形态和结构变化分为三段，分别为十二指肠、空肠和回肠，是食物消化吸收的主要器官，而不是废物排泄的主要器官，也不是人体食物储存的主要器官。就构成来讲，小肠由一层细胞组成，其管壁由黏膜、黏膜下层、肌层和浆膜构成。其中小肠粘膜，特别是空肠，具有许多环状皱襞和绒毛，大大扩大了粘膜的表面积，有利于营养物质的消化和吸收，切除部分小肠直接影响到食物的消化和营养的吸收。因此，B项正确，ACD选项说法错误。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-499", "q": "蛋白质是维持人体生命活动所必需的营养物质。下列关于蛋白质说法错误的是", "options": ["蛋白质在生命活动中具有遗传信息功能", "皮肤中存在大量胶原蛋白", "蛋白质的基本单元结构是氨基酸", "羊毛和蚕丝的主要成分是蛋白质"], "a": 0, "e": ".【A】本题考查生物常识。需结合具体选项予以分析。A项错误，蛋白质在生命活动中的主要作用是提供生物结构的骨架，在细胞和生物体内各种生物化学反应中起催化作用，调节重要生理机能。B项正确，胶原蛋白能维持皮肤与器官的形态和结构，组成了75的真皮部分，让皮肤看起来既有弹性又有光泽。C项正确，氨基酸是蛋白质的基本组成单元。D项正确，羊毛和蚕丝属于天然纤维，主要成分为蛋白质，燃烧时有烧焦羽毛的特殊气味。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-500", "q": "血浆包括各种矿物质、糖类、脂类、蛋白质、激素和维生素等。在上述各种物质中，造成血液颜色为红色的是：", "options": ["激素", "蛋白质", "糖类", "维生素"], "a": 1, "e": ".【B】血液呈红色是因为红细胞中含有的血红蛋白，血红蛋白是具有运输氧气能力的蛋白质。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-501", "q": "下列说法与其所涉及的生物学术语对应不正确的是（）", "options": ["一朝被蛇咬，十年怕井绳——条件反射", "一母生九子，连母十个样——遗传", "入芝兰之室，久而不闻其香——适应", "大树之下无丰草，大块之间无美苗——竞争"], "a": 1, "e": ".【B】本题主要考查生物常识。A项正确，条件反射是指在一定条件下，外界刺激与有机体反应之间建立起来的暂时神经联系，分为第一信号系统的反射和第二信号系统的反射。“一朝被蛇咬，十年怕井绳”说明有了被蛇咬的非条件反射，才建立了害怕类似蛇的井绳的条件反射。B项错误，遗传是指亲子之间以及子代个体之间性状存在相似性，表明性状可以从亲代传递给子代。“一母生九子，连母十个样”表明母亲和九个孩子之间存在的差异，而生物学上把后代与亲代之间以及后代的个体之间存在的差异现象称为变异。C项正确，适应是指生物的形态结构和生理机能与其赖以生存的一定环境条件相适合的现象。“入芝兰之室，久而不闻其香”意为香气刺激嗅觉时间久了好像就闻不到香气了，说明香气刺激对感受器的持续作用而使感受性发生变化，属于适应。挡阳光，下面的草儿光照不足，自然也长不丰茂；整地时土块不充分整细，导致苗的生长不整齐，选项表明树与草、地块之间进行有利条件的竞争现象。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-502", "q": "海洋动物科学考察的结果显示，近十年来，许多海洋“有壳类”动物，如贝类、螺类和虾蟹类等，有外壳变薄、变软的趋势，这种现象的主要原因是：", "options": ["海洋“有壳类”动物面临食物短缺的困境，经常出现营养不良", "外壳轻便的海洋动物更易于游动、捕食和躲避天敌", "海水升温导致海洋动物的生长成熟周期缩短", "二氧化碳排放过多导致海水酸化"], "a": 3, "e": ".【D】全球气候变暖造成的负面影响正在进一步扩大，海洋酸化便是其中之一。一项最新研究成果显示，海水酸化导致包括贝类在内的众多小型海洋动物外壳和骨骼变薄。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-503", "q": "关于疫苗，下列说法错误的是：", "options": ["根据费用支付方式，分政府免费提供和公民自费自愿接种两类", "牛痘疫苗彻底消灭天花，是人类用疫苗迎战病毒的首次胜利", "接种疫苗是预防传染病最有效、最经济的手段", "目前乙肝疫苗是世界上使用量最大的一种疫苗"], "a": 3, "e": ".【D】A项正确，按照费用支付方式，中国预防接种的疫苗分为两类：第一类疫苗，是指政府免费向公民提供，公民应当依照政府的规定受种的疫苗；第二类疫苗，是指由公民自费并且自愿受种的其他疫苗。B项正确，18世纪后，牛痘用作免疫接种以预防高传染性的天花。世界卫生组织已经宣布天花在地球上绝迹——人类彻底消灭了天花，这是疫苗战胜病毒的首度成功案例。C项正确，接种疫苗是预防和控制传染病最经济、有效的公共卫生干预措施。D项错误，流感疫苗在全球已经使用超过60年，目前每年使用量都以亿计，是全球使用量最大的一种疫苗。乙肝疫苗并不是世界上使用量最大的疫苗。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-504", "q": "下列关于仿生生物学的应用对应关系不正确的是：", "options": ["发光纤维——萤火虫", "子弹头列车——翠鸟", "维克罗尼龙搭扣——苍耳", "全天然空调系统建筑——非洲白蚁巢穴"], "a": 0, "e": ".【A】本题考查生物常识。A项错误，发光纤维是指受到光和放射线的照射时，能发出比照射光波长长的可见光的纤维。常见的发光纤维如：以发光玻璃作芯材的纤维、以发光塑料作芯材的纤维。而萤火虫有专门的发光细胞，在发光细胞中有两类化学物质，一类被称作荧光素，另一类被称为荧光素酶。荧光素能在荧光素酶的催化下消耗ATP（腺嘌呤核苷三磷酸又称腺苷三磷酸），并与氧气发生反应，反应中产生激发态的氧化荧光素，当氧化荧光素从激发态回到基态时释放出光子。反应中释放的能量几乎全部以光的形式释放，只有极少部分以热的形式释放，萤火虫是通过这样的作用来发光的。由此可见，发光纤维并不是在仿生萤火虫。B项正确，翠鸟拥有长而平的喙，使其可以从空气迅速潜入水中，同时并不会产生过多的扰动。日本工程师中津英治仿照翠鸟喙设计出了新干线子弹头列车的车头，使其更长更平，这种新设计成功将空气阻力降低了，降低了火车的噪音。C项正确，苍耳是一种植物，它的总苞具有钩状的硬刺，可以贴附于动物的身体上。尼龙搭扣的设计正是从苍耳获得的灵感，尼龙搭扣的两边都是尼龙做的，一边是一排排的小勾，另一边是密密麻麻的小线圈，两边贴在一起的时候，小勾就勾住小线圈，使其能贴在一起。D项正确，非洲白蚁会建造巨大的巢穴系统，他们经常开启和关闭自己塔楼巢穴中的气口，使得巢穴内外的空气得以对流——冷空气从底部的气口流入塔楼，与此同时热空气从顶部的烟囱流出。从而使得巢穴中始终维持一个恒定的温度。在设计津巴布韦首都哈拉雷的约堡东门购物中心和办公大楼时，建筑大师麦克皮尔斯研究了非洲白蚁巢穴的结构，设计出了全天然空调系统，使得购物中心常年维持适宜的温度。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-505", "q": "根据红细胞表面有无抗原A 和B 可以将血液分为", "options": ["", "AB，O 四种血型。A 血型含有抗原A，B 血型含有抗原B，AB 血型", "O 型或A 型", "O 型或B 型", "A 型或B 型", "AB 型或A 型"], "a": 2, "e": ".【C】根据题意，O血型不含抗原A和B，属于隐性性状，其基因组合为ii，AB血型含有抗原A和B，属于显性性状，其基因组合为I(A)I(B)。结合遗传三大定律，丈夫是O血型，妻子是AB血型，其子女血型可能表现为I(A)i或I(B)i，即可能为A血型或B血型，C项正确。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-506", "q": "下列气体是人体能够产生的，能发挥抗炎、神经功能调节和血管松弛等作用，但若吸入过量会与血红素结合导致中毒的是：", "options": ["一氧化氮", "一氧化碳", "硫化氢", "氨气"], "a": 0, "e": ".【A】A项正确，一氧化氮是一种人体可以自然产生的物质，其具有三大功能：①内皮舒张因子。作为内皮舒张因子，一氧化氮主要产生于内皮细胞，对预防和控制心脑血管疾病有着显著的效果。具体而言，一氧化氮是一种脂溶性气体，可以快速渗透出细胞膜向下扩散，进入并作用于血管周围平滑肌细胞，随着平滑肌的舒张，血管得以扩张（使血管松弛），最终导致血压的下降；②神经传导因子。作为神经传导因子，一氧化氮产生于外周神经和大脑中，作为肾上腺素和胆碱以外的神经递质，在血管、海绵体、胃肠道、泌尿道、气管肌、肛尾肌等外周输出神经抑制反应中起到非常重要的作用；③免疫调节因子。作为免疫调节因子，一氧化氮产生于免疫系统中，合成产生的一氧化氮，通过多条途径调节炎症，在调控免疫反应中起到重要作用。具体而言，一氧化氮可辅助白细胞杀死细菌、真菌、寄生虫、肿瘤细胞等。综上可知，一氧化氮在人体内发挥血管松弛、神经功能调节、抗菌消炎的作用。同时，一氧化氮与血红蛋白有很高的亲和力，如果吸入过量，一氧化氮会夺取氧气与血红蛋白结合的位置，造成人体因缺氧而中毒。B项错误，身体组织受毒素、紫外线辐射、激素和药物等侵害时，体内会自然地产生少量一氧化碳。一氧化碳与血红蛋白具有很高的亲和力，吸入过量会造成人体因缺氧而中毒，但一氧化碳在体内不具有血管松弛、神经功能调节、抗菌消炎的作用。C项、D项错误，具有刺激性气味的硫化氢和氨气是人体代谢产生的废气，二者均不与血红蛋白结合，且不具有血管松弛、神经功能调节、抗菌消炎的作用。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-507", "q": "佛朗西斯·克里克提出的中心法则指明了遗传信息的流向，在科学发展中得到不断补充完善。根据该法则，下列哪一种遗传信息传递流程不可能发生：", "options": ["DNA 通过转录把遗传信息传递给RNA.", "RNA 通过翻译把遗传信息传递给蛋白质", "RNA 通过逆转录把遗传信息传递给DNA.", "蛋白质通过逆翻译把遗传信息传递给RNA."], "a": 3, "e": ".【D】本题考查科技常识。A、B、C项正确，中心法则指出，遗传信息的转移可以分为两类：第一类，包括DNA的复制、RNA的转录和蛋白质的翻译，即①DNA→DNA(复制)；②DNA→RNA(转录)；③RNA→蛋白质(翻译)。这三种遗传信息的转移方向普遍地存在于所有生物细胞中。第二类，是特殊情况下的遗传信息转移，包括RNA的复制，RNA反向转录为DNA和从DNA直接翻译为蛋白质，即①RNA→RNA(复制)；②RNA→DNA(反向转录)；③DNA→蛋白质。RNA复制只在RNA病毒中存在。D项错误，中心法则旨在详细说明连串信息的逐个传送，它指出遗传信息不能由蛋白质转移到蛋白质或核酸之中。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-508", "q": "孔雀开屏是动物繁衍中的一种求偶行为，是由雄性个体体内的雄性激素引起的行为，雄性个体为赢得雌性孔雀的芳心，特意打开艳丽的尾羽炫耀自己。除此之外，与动物繁衍相关的成语还有（）。", "options": ["飞蛾扑火", "雀跃万分", "金蝉脱壳", "蜻蜓点水"], "a": 3, "e": ".【D】A项错误，飞蛾扑火字面意思是飞蛾扑到火上，比喻自取灭亡或比喻不顾一切地奔赴所向往的目标；B项错误，雀跃万分是描述麻雀行走的状态，形容人高兴得像麻雀一样跳跃；C项错误，金蝉脱壳字面意思是指蝉脱去外壳的蜕变。比喻制造或利用假象脱身，使对方不能及时发觉，或比喻事物发生根本性的变化；D项正确，蜻蜓点水指的是蜻蜓在平静如镜的湖面上款款飞旋，不时地将细长的尾巴弯成弓状伸进水草中，湖面因此扩张开一圈圈波纹。蜻蜓在水面上飞翔，尾尖紧贴水面，一点一点用尾尖点水，是俗话说的“蜻蜓点水”。“蜻蜓点水”是蜻蜓生活中的自然组成部分—产卵、繁殖后代。人们通常借用这种“点水”方式告诫大家做事要深入，不要浅尝辄止。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-509", "q": "某调查小组对部分生物进行了归类，他们把胡狼、棕熊和狮子归为一类，把丹顶鹤、蝙蝠、麻雀归为一类，把黄鳝、蛇和蚯蚓归为一类，这样归类的依据最可能是：", "options": ["生活环境", "肢体形态", "运动速度", "繁殖方式"], "a": 1, "e": ".【B】B项正确：按肢体形态来分，胡狼、棕熊和狮子均有四肢，四条腿行走；丹顶鹤、蝙蝠和麻雀都有翅膀，可飞行；黄鳝、蛇和蚯蚓都无足无翅。A项错误：若按生活环境分，胡狼、狮子多分布于草原，而棕熊多分布于森林，不能归为一类；丹顶鹤多栖息于湿地，蝙蝠栖息于洞穴，麻雀喜欢靠近农田，不能归为一类；黄鳝在水中生存，蛇能水陆两栖，蚯蚓只能生存在泥土中，不能归为一类。C项错误：若按运动速度分，蚯蚓的运动速度明显比黄鳝和蛇要慢，不能归为一类。D项错误：若按繁殖方式分，蝙蝠为胎生，丹顶鹤、麻雀为卵生，不能归为一类。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-510", "q": "下列器官与所属的功能系统对应错误的是：", "options": ["骨髓：运动系统", "甲状腺：内分泌系统", "肝脏：消化系统", "扁桃体：免疫系统"], "a": 0, "e": ".【A】A项错误，运动系统由骨、骨连结和骨骼肌三种器官组成。骨以不同形式连结在一起，构成骨骼。形成了人体的基本形态，并为肌肉提供附着，在神经支配下，肌肉收缩，牵拉其所附着的骨，以可动的骨连结为枢纽，产生杠杆运动；B项正确，内分泌系统由内分泌腺和分布于其它器官的内分泌细胞组成。内分泌腺是人体内一些无输出导管的腺体。主要的内分泌腺包含甲状腺，此外还有甲状旁腺、肾上腺、垂体、松果体、胰岛、胸腺和性腺等；C项正确，消化系统由消化道和消化腺两大部分组成。消化道包括口腔、咽、食道、胃、小肠（十二指肠、空肠、回肠）和大肠（盲肠、结肠、直肠、肛管）等部分。消化腺主要有唾液腺、胃腺、肝脏、胰腺、肠腺。其中肝脏可以分泌胆汁、储存在胆囊中将大分子的脂肪初步分解成小分子的脂肪，称为物理消化，也称作“乳化”；D项正确，免疫系统是机体执行免疫应答及免疫功能的重要系统。由免疫器官含扁桃体、免疫组织、免疫细胞和免疫分子组成，是防卫病原体入侵最有效的武器，它能发现并清除异物、外来病原微生物等引起内环境波动的因素。但其功能的亢进会对自身器官或组织产生伤害。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-511", "q": "下列关于胎儿与母体关系的表述错误的是：", "options": ["胎儿与母体具有不同的遗传物质", "胎儿与母体的血液通过脐带相通", "胎儿在母体中的发育场所是子宫", "胎儿与母体通过胎盘进行物质交换"], "a": 1, "e": ".【B】A项正确：遗传物质是亲代与子代之间传递遗传信息的物质，具有典型细胞结构的生物的遗传物质是DNA，但是DNA上所携带的信息是不一样的。B项错误：胎儿所需的营养物质确切来说来自母体的血液，发育中的胎儿的血型与母体的可以不同，原因是母体与胎儿的毛细血管相互交叉但不相通，所以胎儿体内的血液与母体的血液不直接相通，母亲的血液与胎儿的血液是彻底分开的。C项正确：卵细胞受精以后开始分裂、分化，形成胚泡，然后形成囊胚，并植入母体子宫内膜中，吸收营养，继续发育。D项正确：胎盘内有许多绒毛，绒毛内有毛细血管，这些毛细血管与脐带内的血管相通，绒毛与绒毛之间则充满了母体的血液。胎儿和母体通过胎盘上的绒毛进行物质交换。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-512", "q": "某些基因突变有可能给生物体带来繁殖优势，保证基因携带者的后代能够更好地适应某种环境，因而这类突变得以广泛中血红蛋白增长的作用。血红蛋白过低会导致缺氧，过高会导致血液粘稠度升高，进而引发血栓等血液循环问题。那么）地区。", "options": ["高海拔", "海边", "寒带", "热带"], "a": 0, "e": ".【A】本题主要考查生物常识。基因突变是指基因在结构上发生碱基对组成或排列顺序的改变，即基因组DNA分子发生的突然的、可遗传的变异现象。处于高海拔地区的高度时，哺乳动物会因氧气量的减少，导致心跳加快、心率加速、血液中血红蛋白的比例降低。而题活中发生了基因的突变，这一基因的出现有利于补偿身体的缺氧情况，平衡血液循环系统，保证其后代能够更好地适应高海拔的环境。A项与缺氧有关，B、C、D三项与缺氧无关。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-514", "q": "运用试管苹果技术来推广优良苹果品种，这种技术属于：", "options": ["基因工程", "细胞工程", "酶工程", "发酵工程"], "a": 1, "e": ".【B】B项正确：细胞工程技术是细胞生物学与遗传学的交叉领域，主要利用细胞生物学的原理和方法，结合工程学的技术手段，按照人们预先的设计，有计划地改变或创造细胞遗传性的技术。在果树、林木生产实践中应用细胞工程技术主要是微繁殖和去病毒技术。几乎所有的果树都患有病毒病，而且多是通过营养体繁殖代代相传的。用去病毒试管苗技术，可以有效地防止病毒病的侵害，恢复种性并加速繁殖速度。A项错误：基因工程又称基因拼接技术和DNA重组技术，是以分子遗传学为理论基础，以分子生物学和微生物学的现代方法为手段，将不同来源的基因按预先设计的蓝图，在体外构建杂种DNA分子，然后导入活细胞，以改变生物原有的遗传特性、获得新品种、生产新产品。试管苹果并未用到该技术。C项错误：酶工程（又称蛋白质工程学），是指工业上有目的地设置一定的反应器和反应条件，利用酶的催化功能，在一定条件下催化化学反应，生产人类需要的产品或服务于其它目的的一门应用技术。试管苹果并未用到该技术。D项错误：发酵工程，是指采用现代工程技术手段，利用微生物的某些特定功能，为人类生产有用的产品，或直接把微生物应用于工业生产过程的一种新技术。发酵工程的内容包括菌种的选育、培养基的配制、灭菌、扩大培养和接种、发酵过程和产品的分离提纯等方面。试管苹果并未用到该技术。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-515", "q": "下列说法符合生物常识的是：", "options": ["蜜蜂用头部的螯针蜇人", "蜻蜓拥有咀嚼式的口器", "蚂蚁出生后由雄蚁喂养", "蟋蟀依靠口器发出声音"], "a": 1, "e": ".【B】本题考查生物常识，结合选项具体分析。A项错误，蜜蜂蜇人的刺称之为蜂针，蜂针是蜜蜂的自卫器官，当蜜蜂感受到生命受到其他生物的威胁时，会执行蜇刺的动作。蜂针位于蜜蜂的尾部而非头部。B项正确，蜻蜓是一种肉食昆虫，拥有咀嚼式口器，上颚发达，视觉极为灵敏。C项错误，蚂蚁在幼虫阶段没有任何能力,它们也不需要觅食,完全由工蚁喂养。D项错误，蟋蟀靠翅膀的摩擦来发音。在蟋蟀雄虫的前翅上，有旋涡纹状的翅膜。一边翅膀长着锉刀状的翅膜弦器，另一边翅膀长着较硬翅膜弹器。当这两种发音器相互摩擦，就能发出声音。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-516", "q": "婴儿的以下行为属于本能的是：", "options": ["说话", "走路", "笑", "吸奶"], "a": 3, "e": ".【D】本能是指一个生物体趋向于某一特定行为的内在倾向。其固定的行为模式非学习得来，也不是继承而来。固定行为模式的实例可从动物的行为观察得到。觅食反射：用手指或乳头抚摸一下新生儿的面颊或接触其嘴唇，他（她）就会转头张嘴，开始吸吮动作。这个重要的反射能使新生儿找到或吃到食物。在出生仅半小时的，醒着的新生儿身上可观察到这种反射。A、B、C三项均为后天学习的行为，排除；D项是本能反应，当选。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-517", "q": "“杂交水稻之父”袁隆平院士将野生水稻和普通水稻多次杂交，培育出高产的杂交水稻新品种，利用的原理是：", "options": ["生态系统的多样性", "染色体的多样性", "基因的多样性", "细胞的多样性"], "a": 2, "e": ".【C】杂交水稻是通过不同稻种相互杂交产生的。杂交实际上是通过不同的基因型的个体之间的交配而取得某些双亲基因重新组合的个体的方法，利用的正是基因的多样性。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-518", "q": "沙漠中生长的植物其叶子比较小，而根部极深，其原因主要是：", "options": ["根深不会被风吹倒", "沙漠中生长的植物品种都是叶小根深的", "叶小有利于减少日晒面积，不会被晒死", "沙漠中降雨量少，气候干旱，叶小是为了减少蒸发，根深利于吸收水分"], "a": 3, "e": ".【D】D项正确：沙漠地区气候干旱，雨水稀少，植物为适应干旱缺水的环境，从地下充分汲取水源，根一般扎得很深，叶子则退化成针状，以降低植物的蒸腾作用，减少水分散失。A项错误：沙漠植物的根扎得深，是为了吸收水分，而非为了防风。B项错误：并非沙漠中生长的植物品种都叶小根深，此外，大部分沙漠植物叶小根深，是为了适应干旱缺水的环境才长成这样。C项错误：沙漠植物叶小最主要的原因是减少蒸腾作用以保持水分，而非减少日晒面积。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-519", "q": "关于生物进化的先后顺序，下列选项排列错误的是：", "options": ["单细胞动物——腔肠动物——扁形动物——线形动物", "藻类植物——苔藓植物——蕨类植物——种子植物", "软体动物——节肢动物——棘皮动物——鱼类", "爬行动物——两栖类——鸟类——哺乳类"], "a": 3, "e": ".【D】本题主要考查生物常识。生物进化是指一切生命形态发生、发展的演变过程，是从水生到陆生、从简单到复杂、从低等到高等的过程，从中呈现出一种进步性发展的趋势。以下图生物进化树。ABC项正确，都符合生物进化顺序。D项错误，两栖类应当在爬行动物前面。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-520", "q": "下列关于生活医学常识的说法错误的是：", "options": ["生理盐水的浓度是", "医用消毒酒精的浓度是", "儿童缺锌会导致生长发育迟缓，抵抗力差", "剧烈运动后感觉全身酸痛是因为肌肉中生成了乳酸"], "a": 0, "e": ".【A】本题考查生物常识，主要涉及医学常识的相关内容。A项错误，生理盐水，是指生理学实验或临床上常用的渗透压与动物或人体血浆的渗透压基本相等的氯化钠溶液。浓度：用于两栖类动物时是，用于哺乳类动物和人体时是。人们平常点滴用的氯化钠注射液浓度是，可以当成生理盐水来使用。故浓度错误。B项正确，日常生活中，常见一些人用医用酒精来擦洗伤口，以达到灭菌消毒的目的。值得注意的是，在药店买到的酒精有和两种浓度，这两种浓度的酒精用途是不一样的：的酒精常用于擦拭紫外线灯；的酒精用于消毒。C项正确，锌是人体内必需的微量元素之一，缺锌将直接造成儿童免疫力低下，影响孩子的生长发育，导致身材矮小或智力发育不良等严重后果。D项正确，人体剧烈运动时，会进行无氧呼吸。而无氧呼吸产生大量乳酸等中间代谢产物，不能通过呼吸排除，就形成了乳酸堆积，造成全身肌肉酸痛。本题为选非题，故正确答案是A。", "tag": "科技常识"},
{"id": "tech-521", "q": "关于维生素，下列说法错误的是：", "options": ["维生素", "维生素", "维生素", "维生素"], "a": 0, "e": ".【A】本题考查生物常识，主要涉及维生素方面的知识。A项错误，维生素可以帮助消除口腔、唇、舌的炎症；促使毛发、皮肤、指甲正常生长。而脚气病指因为缺乏维生素引起的全身性疾病，表现为多发性神经炎、肌肉萎缩等症状。B项正确，周围神经炎一般指多发性末梢神经炎，是由多种原因造成如中毒、营养代谢障碍、感染、过敏、变态反应等引起的多发性末梢神经损害的总称，可选用、等进行治疗。C项正确，夜盲症指在光线昏暗环境下或夜晚视物不清造成完全看不见东西、行动困难的症状，该症状一般都是因缺乏维生素，因此适量服用维生素可以防治夜盲症。D项正确，巨幼细胞性贫血是由于脱氧核糖核酸（DNA）合成障碍所引起的一种贫血，主要系体内缺乏维生素和(或)叶酸所致，因此维生素可用于治疗巨幼细胞性贫血。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-522", "q": "关于人的大脑，下列说法正确的是：", "options": ["男性大脑比女性大脑更适合学数学", "成人也能够长出新的脑细胞", "昏迷其实是一种深度睡眠", "有人是左脑型性格，有人是右脑型性格"], "a": 1, "e": ".【B】本题考查生物学常识。A项错误，根据研究表明，一般来说，男性大脑比女性大脑体积要大，但并不能说明男性比女性大脑更适合学数学，二者不存在必然联系。B项正确，脑细胞是构成脑的多种细胞的通称。脑细胞主要包括神经元和神经胶质细胞，神经细胞属于永久细胞不可再生，但是神经胶质细胞主要对神经元起支持、保护和营养辅助作用，并通过再生修复受损的神经细胞，所以成人的脑细胞可以再生。C项错误，昏迷不是深度睡眠，昏迷是完全意识丧失，对外界刺激反应的迟钝或消失。深度睡眠是睡眠的一部分，神经反射减弱，能被外界的刺激唤醒。D项错误，大脑可分为左半球和右半球，一般大脑左半球具有语言、概念、数字、分析、逻辑推理等功能；大脑右半球具有音乐、绘画、想象等功能。人的左右半脑思维方式不同，但并不能作为划分人性格的依据。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-523", "q": "海参生活在海底，以吃海中小生物为生。一旦进入夏季，海参就需要夏眠，这很可能是因为（）。", "options": ["海水温度偏高，海参不耐热", "海参要为繁殖储备能量", "海参用夏眠来应对饥饿", "海参为了逃避天敌"], "a": 2, "e": ".【C】本题主要考查生物常识。海参，是生活在海边至8000米的海洋棘皮动物，以海底藻类和浮游生物为食。入夏以后，上层海水由于太阳光强烈照射的结果，温度比较高。这时，海底的小生物都浮到海面，而海参却对温度很敏感，当水温超过20度时，就会向更深的海底迁移。由于在新的地方缺少食物，没有东西可吃的海参，只好进入夏眠状态，这是海参为适应环境而养成的习惯。A项错误，本题问的是海参“夏眠”的原因，海参生活在海底，当夏季到来时，海底的小生物都浮到海面，海参缺少食物，为了适应环境，所以进行夏眠，故海参夏眠的原因不是因为不耐热。B项错误，“储备能量”应当是“多进食”，而不是夏眠。C项正确，海参迫于夏季食物中断，只好进入夏眠，“应对饥饿”是海参夏眠的主要原因。D项错误，逃避天敌不是海参夏眠的原因。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-524", "q": "下列词语与生物的繁殖行为无关的是", "options": ["藕断丝连", "蜻蜓点水", "移花接木", "孔雀开屏"], "a": 0, "e": ".【A】本题考查生物常识。A项错误，莲藕体内的运输组织呈螺旋状，当莲藕折断时，那些呈螺旋状的导管并没有真正折断，而是像弹簧一样被拉长，形成了许多丝状的物质，因此出现了“藕断丝连”的现象，该现象跟繁殖无关。B项正确，当雌雄蜻蜓交配后，雌性蜻蜓在水面上盘旋飞翔，尾尖贴着水面，一点一点地产下受精卵，为“蜻蜓点水”，该行为与蜻蜓的繁殖有关。C项正确，“移花接木”是指把一种花木的枝条或嫩芽嫁接在另一种花木上，利用植物受伤后具有愈伤的机能，将两个伤面的形成层靠近并扎紧在一起，结果因细胞增生，彼此愈合成为彼此连接的一个整体。“移花接木”属于无性繁殖的一种，跟繁殖有关。D项正确，“孔雀开屏”是雄孔雀的求偶行为。雄孔雀展开尾屏，不停地做出各种各样优美的舞蹈动作，向雌孔雀炫耀自己的美丽，以此吸引雌孔雀。待到它求偶成功之后，便与雌孔雀一起产卵育雏，该行为与繁殖有关。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-525", "q": "随着科技发展，微生物在我们的生活中发挥越来越大的作用。以下不属于微生物应用事例的是（）。", "options": ["用青霉素治疗疾病", "注射减毒疫苗", "利用木质纤维素水解发酵生产生物燃料", "在伊蚊身上植入编码了疟原虫抗体的基因"], "a": 3, "e": ".【D】本题考查微生物应用的生物常识。微生物包括细菌、病毒、真菌以及一些小型的原生生物、显微藻类等在内的一A项正确，弗莱明从青霉菌抑制其它细菌的生长中发现了青霉素，用青霉素治疗疾病属于微生物应用事例。B项正确，注射减毒疫苗即将带有病原体的微生物接种到身体内，引发机体免疫反应，起到获得长期或终生保护的作用。C项正确，木质纤维素是天然可再生木材经过化学处理、机械法加工得到的有机絮状纤维物质。木质纤维素可在水解后被微生物发酵生产燃料乙醇。D项错误，在伊蚊身上植入编码了疟原虫抗体的基因，属于基因的应用，而不是微生物的应用。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-526", "q": "甲醛是一种无色、有强烈刺激性气味的气体，在室内达到一定浓度会危害人体健康。下列花卉植物中，除（）外，均可有效吸收甲醛，净化居室空气。", "options": ["吊兰", "芦荟", "常春藤", "山茶花"], "a": 3, "e": ".【D】本题不严谨，选项中四种植物均有吸收甲醛作用，在此情况下，应选择吸收甲醛能力最弱者为本题答案。根据相关研究文献，甲醛环境下15小时内，4种植物吸收甲醛能力分别为（以每平方米叶片吸收甲醛质量计算）：常春藤[1]，吊兰为、芦荟为[2]。另有以山茶花等8种植物为对象，对比吸收甲醛能力，", "tag": "科技常识"},
{"id": "tech-527", "q": "狂犬病是一种人兽共患的病毒性传染病，死亡率很高，在高达的人类感染病例中，狂犬病毒都是由家养狗传播的，通常是通过咬伤或抓伤致病，主要经由（）传染给人。", "options": ["血液", "唾液", "毛发", "呼吸"], "a": 1, "e": ".【B】本题考查生物常识。狂犬病乃狂犬病毒所致的急性传染病，人兽共患，多见于犬、狼、猫等肉食动物，人多因被病兽咬伤而感染。狂犬病毒含5种蛋白，即糖蛋白（G）、核蛋白（N）、聚合酶（L）、磷蛋白（NS）及基质（M）等。狂犬病病毒的糖蛋白能与乙酰胆碱结合，决定了狂犬病毒的噬神经性。人被患病动物咬伤或抓伤后，动物唾液中的病毒通过伤口进入人体而引发疾病，少数患者也可因眼结膜被病兽唾液污染而患病。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-528", "q": "生物老师把六种动物分成两组，一组是鲫鱼、麻雀、牛，另一组是蜗牛、虾、蝴蝶。这样分组可能的依据是：", "options": ["是否有脊椎骨", "体温是否恒定", "胎生还是卵生", "呼吸方式的不同"], "a": 0, "e": ".【A】本题考查生物学常识，主要涉及动物特征的相关知识点。A项正确，根据动物是否由脊椎骨组成脊柱，可分为脊椎动物和无脊椎动物。鲫鱼、麻雀、牛都具有脊椎骨，属于脊椎动物；而蜗牛、虾、蝴蝶都没有脊椎骨，属于无脊椎动物。B项错误，第一组，麻雀和牛属于恒温动物，能在环境温度变化的情况下保持体温的相对稳定。但是第一组中的鲫鱼和第二组的动物都属于变温动物，它们需要寻找凉爽或温暖的环境来改变自身体温，而不能直接地控制自身体温。C项错误，题干中只有牛是哺乳类动物，属于胎生；其他动物繁殖方式都为卵生。D项错误，题干中各种动物的呼吸方式多种多样，鲫鱼和虾用鳃呼吸，牛和麻雀用肺呼吸，蝴蝶用气管呼吸，蜗牛用呼吸孔呼吸。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-529", "q": "下列与鸟有关的说法中错误的是：", "options": ["秃鹫被称为“草原清道夫”，喜食腐烂的尸体", "蜂鸟主要分布在南美洲，是世界上最小的鸟类", "鸵鸟肌肉发达，后肢粗壮有力，可以飞行", "金丝燕嘴里分泌的唾液就是燕窝"], "a": 2, "e": ".【C】本题主要考查生物常识的基本内容。A项正确，秃鹫主要以大型动物的尸体和其他腐烂动物为食，被称为“草原上的清道夫”，常在开阔而较裸露的山地和平原上空翱翔，窥视动物尸体。B项正确，蜂鸟只有在美洲有发现，且其中多数生活在南美洲的热带雨林中。蜂鸟是世界上最小的鸟类，有的甚至比黄蜂还小。体型最大的巨蜂鸟体长也不过20厘米，体重不足20克。C项错误，鸵鸟腿很长，十分粗壮，脚也极为强大，趾的下面有角质的肉垫，富有弹性并能隔热，适于在沙地中行走或奔跑，但是鸵鸟两翼退化，不能飞翔。D项正确，燕窝是一种叫“金丝燕”的雀鸟，利用苔藓、海藻和柔软植物织维混合他们的羽毛和唾液胶结而成的。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-530", "q": "下列四个选项，能正确表示食物链的是：", "options": ["大鱼", "草", "阳光", "昆虫"], "a": 1, "e": ".【B】在生态系统内，各种生物之间由于食物而形成的一种联系，叫做食物链。食物链的开始通常是绿色植物（生产者），从绿色植物开始至少要有三个营养级。B项正确：羊以草为食，狼以羊为食，且从绿色植物（草）开始。A项错误：食物链方向错误。C项错误：食物链最开始的是绿色植物（生产者）而非阳光。D项错误：昆虫已经是食草动物，没从绿色植物（生产者）开始。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-531", "q": "关于生物净化，下列说法错误的是：", "options": ["植物净化大气主要是通过叶片的作用实现的", "海洋中降解石油烃的微生物主要是酵母", "淡水生态系统中的生物净化，细菌起主导作用", "生物净化能力都有一定的限度"], "a": 1, "e": ".【B】B项错误：海洋中降解石油烃的微生物主要是细菌，此外，还有酵母、放线菌和丝状真菌。A项正确：生物通过代谢作用，使污染的环境得到净化，提高环境对污染物的承载负荷，增加环境容量的作用，就叫做生物净化。植物净化大气主要是通过叶片的作用实现的。绿色植物（包括树木和草坪）净化大气的作用主要有：①吸收二氧化碳，放出氧气，维持人类环境中两者的平衡；②对降尘和飘尘有滞留过滤作用；③在植物抗性范围内能通过吸收而减少空气中二氧化硫、氟化氢、氯气等有害物质的含量；④在植物抗性范围内能减少臭氧的发生，减轻光化学烟雾污染；⑤有过滤细菌或杀菌作用；⑥对某些重金属有吸收和净化作用；⑦减轻噪声污染。C项正确：河流、湖泊、水库等水体中生活着细菌、真菌、藻类、水草、原生动物、贝类、昆虫幼虫、鱼类等生物，对污染物会产生生物净化作用。淡水生态系统中的生物净化，细菌起主导作用。D项正确：水体、空气和土壤的污染，只要不超过生态系统的负载能力，污染物就可以通过物理的、化学的和生物学的作用得到净化。如果环境污染物超过了生态系统的负载能力，生物净化作用就会遭到破坏，整个生态系统就有可能失去平衡，产生不良的后果。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-532", "q": "未使用染色剂的生猪肉香肠晾晒一段时间后会变得更红亮，其主要原因是：", "options": ["瘦肉风干发酵时其酸碱值降低，导致其中肌红蛋白被氧化，血红素分解，染红整根香肠", "肥肉富含饱和脂肪酸，经发酵氧化后释放出复合红色素，油脂液化，使红色素均匀分布", "肠衣在保护肠肉的同时，自身水分逐渐丢失，表面上的红霉菌较为均匀的繁殖，经紫外线照射分解死亡，留下润泽的", "肠内的粗盐、料酒等调料本身具有淡黄、淡红等颜色，经乳酸菌发酵，红色素会不断沉淀"], "a": 0, "e": ".【A】A项正确：香肠在发酵时，瘦肉的PH值会降低，也就是变酸，导致肌肉中的肌红蛋白被氧化，里面的血红素发生分解，染红了整根香肠。故正确答案为A。（资料来源：中国国家地理网）", "tag": "科技常识"},
{"id": "tech-533", "q": "关于人体消化和吸收的叙述，错误的是：", "options": ["胃吸收酒精的能力较强", "胆汁不具有促进脂肪消化的功能", "大肠的作用是排泄未吸收的食物", "肝被誉为“物质代谢中枢”"], "a": 1, "e": ".【B】A项正确：酒的化学成分是乙醇，在消化道内不需要消化即可吸收，吸收快而且完全。一般在胃中吸收。胃内有无食物、胃壁的功能状况、饮料含酒精的多少以及饮酒习惯均可影响酒精的吸收。B项错误：肝脏分泌的胆汁中不含消化酶，但胆汁对脂肪有乳化作用，能把脂肪变成微小颗粒，增加了脂肪与消化酶的接触面积，从而有利于脂肪的消化。C项正确：大肠是对食物残渣中的水分进行吸收，并且可以将食物残渣自身形成粪便排出的脏器。D项正确：被誉为“物质代谢中枢”的是肝脏，肝脏是身体内以代谢功能为主的一个器官，并在身体里面扮演着去氧化，储存肝糖，分泌性蛋白质的合成等等。肝脏也制造消化系统中的胆汁。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-534", "q": "严重缺氧的病人输氧时，要在纯氧中混入的（二氧化碳），目的是：", "options": ["用", "节约氧气", "让人体吸收", "用"], "a": 0, "e": ".【A】A项正确，给严重缺氧的病人输氧时，一方面要满足病人对氧的需要，另一方面还要提高病人的呼吸中枢的兴奋性，加强病人的呼吸能力。二氧化碳是调节呼吸的有效生理刺激。当吸入二氧化碳含量较高的混合气体时，会使肺泡内二氧化碳含量升高，动脉血中二氧化碳的含量也随之升高，这样就形成了对呼吸中枢的有效刺激，呼吸中枢的活动就加强，使呼吸加强。因此给严重缺氧的病人输氧时，要在纯氧中混入的，目的是用维持呼吸中枢的兴奋。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-535", "q": "下列哪一选项描述的是竞争关系：", "options": ["鹬蚌相争", "不见兔子不撒鹰", "螳螂捕蝉，黄雀在后", "鸠占鹊巢"], "a": 3, "e": ".【D】生物间的关系按性质可归并为两类。一是种间互助性的相互关系，如共栖、共生等；二是种间对抗性的相互关系，如寄生、捕食、竞争等。A项错误，鹬是一种水鸟，常在浅水边或水田中捕食小鱼、昆虫、河蚌等。鹬以蚌为食，两者为捕食关系。B项错误，兔子与鹰是捕食关系。C项错误，蝉与螳螂、螳螂与黄雀都是捕食关系。D项正确，成语中“鸠占鹊巢”中的“鸠”指的是斑鸠，两者为竞争关系。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-536", "q": "香烟点燃后，所产生的能减低红血球将氧输送到全身的成分是：", "options": ["焦油", "一氧化碳", "苯并芘", "尼古丁"], "a": 1, "e": ".【B】A项错误，焦油不能与血红蛋白结合。B项正确，一氧化碳极易与血红蛋白结合，形成碳氧血红蛋白，使血红蛋白丧失携氧的能力和作用，造成组织窒息，严重时死亡。C项错误，苯并芘是一种常见的高活性间接致癌物和突变原。苯并芘不能与血红蛋白结合。D项错误，尼古丁会使人上瘾或产生依赖性，重复使用尼古丁会增加心跳速度和升高血压并降低食欲。大剂量的尼古丁会引起呕吐以及恶心，严重时人会死亡。尼古丁不能与血红蛋白结合。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-537", "q": "下列选项中，没有体现生命现象的是：", "options": ["梅雨季节，门环惹铜绿", "遭遇污染，汪洋变赤潮", "只待时日，化蛹成彩蝶", "水沁石板，青苔绘碧痕"], "a": 0, "e": ".【A】本题考查生物常识。生命现象最本质的是新陈代谢，生殖和遗传也是重要的特征。A项错误：“门环惹铜绿”是门环中的铜、水、空气中的氧气、二氧化碳，四种物质一起发生了化合反应生成了绿色的碱式碳酸铜，俗称“铜锈”，是化学变化，没有体现生命现象。B项正确：赤潮是在特定的环境条件下，海水中某些浮游植物、原生动物或细菌爆发性增殖或高度聚集而引起水体变色的一种有害生态现象，其中植物动物有生命现象。C项正确：“化蛹成彩蝶”是完全变形昆虫在幼虫和成虫之间的一个发育阶段。化蛹时，幼虫结构解体，成虫结构形成，初次出现翅，蛹皮裂开，咬开一条出路而蜕出，有生命现象。D项正确：青苔是水生苔藓植物，色翠绿，生长在水中或陆地阴湿处，有生命现象。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-538", "q": "从生物学角度来讲，下列骨髓配对移植成功概率最大的是：", "options": ["A", "B", "C", "D"], "a": 2, "e": ".【C】骨髓移植即造血干细胞移植，是指正常人的造血干细胞通过静脉输注到患者体内，重建患者的造血功能和免疫功能，达到治疗某些疾病的目的。在移植过程中人类白细胞抗原（HLA），是决定移植排斥反应高低的重要因素。在进行骨髓和其它器官移植时，供者和受者之间人类白细胞抗原（HLA）相容程度越高，排斥反应的发生率就越低，移植成功率和移植器官长期存活率就越高；反之，就越容易发生排斥反应。A项错误，骨髓配型是做HLA分型，和血型无关，且子女与父母之间只有一半HLA抗原相合的机会（因为染色体一半来自父亲、另一半来自母亲），不可能有完全相合的机会，医学上叫做半相合，通常不能相互移植。B项错误，丈夫和妻子之间没有血缘关系，而人类非血缘关系的HLA型别中，相合几率是四百分之一到万分之一。C项正确，理论上说，HLA配型完全相合在同卵（同基因）双生兄弟姐妹间最高为，在非同卵（异基因）双生或亲生兄弟姐妹间其次，为1/4。兄妹二人虽然年龄相差12岁，但由于同父同母，配对移植成功率相比其它三个选项是最高的。D项错误，爷爷为孙子献血和肝脏只能说明血型一致以及肝脏匹配度高，并不能说明HLA配型相合度高。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-539", "q": "下列表述错误的是：", "options": ["长期饮用缺氟的水容易患上龋齿", "纤维素属于糖类，是植物的主要成分", "锌、钙、铁等在人的生长发育期是必不可少的", "油脂在体内经氧化放出能量，为维持恒定体温提供能量"], "a": 1, "e": ".【B】A项：正确，龋齿俗称虫牙、蛀牙，是细菌性疾病，可以继发牙髓炎和根尖周炎。氟是人体重要的微量元素，是形成坚硬骨骼的必需元素，长期饮用缺氟的水容易患上龋齿，中老年人缺氟还会导致骨骼变脆而骨折。B项：错误，纤维素是由葡萄糖组成的大分子多糖，不溶于水及一般有机溶剂，是植物细胞壁的主要成分，并非植物的主要成分。C项：正确，钙铁锌都是人体必需的微量元素，钙，促进成骨和骨质强壮，还是神经肌肉等必不可少的物质；铁，合成血红蛋白必不可少的物质，缺乏会致贫血、乏力等；锌，亦是人体内环境中必不可少的微量元素，缺乏会致发育不良、头发枯黄、注意力分散等。D项：正确，油脂的主要生理功能是贮存和供应热能，在代谢中可以提供的能量比糖类和蛋白质约高一倍。一克油脂在体内完全氧化时，大约可以产生39.8千焦的热能。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-540", "q": "角蛋白是一种控制细胞形状和稳定性的蛋白。以下对角蛋白认识错误的是：", "options": ["人的头发、指甲主要是由角蛋白构成的", "角蛋白是爬行动物鳞片、羽毛、爪子的主要成分", "在人的皮肤中，角蛋白主要分布在真皮层", "角蛋白来源于外胚层分化而来的细胞，是一种硬蛋白"], "a": 2, "e": ".【C】C项错误：角蛋白是硬蛋白之一，是一类具有结缔和保护功能的纤维状蛋白质，来源于外胚层分化而来的细胞。它是外胚层细胞的结构蛋白，包括毛发、指甲、羽毛等，它还是一种不能直接为畜禽所吸收利用的硬蛋白，主要存在于动物的鳞片、毛发、羽毛和蹄中。在人体的皮肤中，角蛋白主要分布在表皮层。A、B、D三项均正确。本题为选非题，故正确答案为C。备注：B项表述不严谨：羽毛应当为鸟类标志。", "tag": "科技常识"},
{"id": "tech-541", "q": "地球上生物的种类极其丰富，从表面上看，不同的生物之间似乎并没有相同之处，但其实所有的生物都具有一些共同特征。以下不属于生物共同特征的是：", "options": ["由单细胞构成", "需要能量才能生存", "具有生命周期", "新陈代谢"], "a": 0, "e": ".【A】A项错误：生物组成多种多样。有单细胞生物（如衣藻等部分藻类、草履虫）、多细胞生物（如裸子植物、被子植物、哺乳动物），也有无细胞生物（如病毒）。因此，“由单细胞组成”非生物的共同特征。B项正确：所有的生物都需要能量来维持生命。C项正确：生物学上的生命周期是指生物体从出生、成长、成熟、衰退到死亡的全部过程。所有的生物都具有生命周期。D项正确：机体与机体内环境之间的物质和能量交换以及生物体内物质和能量的自我更新过程叫作新陈代谢。新陈代谢属于生物的共同特征。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-542", "q": "微生物在我们的生活中有着广泛的用途，下列关于微生物的使用，错误的一项是：", "options": ["利用醋酸菌酿醋", "利用酵母菌制作泡菜", "利用乳酸菌制作酸奶", "利用青霉菌提取青霉素"], "a": 1, "e": ".【B】本题考查生物常识。A项正确，醋酸菌如果在糖源充足的情况下，可以直接将葡萄糖变成醋酸；如果在缺少糖源的情况下，先将乙醇变成乙醛，再将乙醛变成醋酸；如果在氧气充足的情况下，能将酒精氧化成醋酸，从而制成醋。B项错误，制作泡菜是利用乳酸菌，不是酵母菌，酵母菌多用来做馒头等面食。C项正确，乳酸菌指发酵糖类主要产物为乳酸的一类无芽孢、革兰氏染色阳性细菌的总称，常用于制作酸奶、乳酪、德国酸菜、啤酒、葡萄酒、泡菜、腌渍食品和其他发酵食品。D项正确，青霉素是抗菌素的一种，是指分子中含有青霉烷，能破坏细菌的细胞壁并在细菌细胞的繁殖期起杀菌作用的一类抗生素。青霉素是从青霉菌中提取出来的。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-543", "q": "在克隆羊的培育过程中，某只白细毛公羊提供了细胞核，某只黑细毛羊提供了去核卵细胞，某只白粗毛羊进行代孕，那么克隆羊的体表的毛和性别分别为：", "options": ["白色粗羊毛、公羊", "白色细羊毛、母羊", "黑色粗羊毛、母羊", "白色细羊毛、公羊"], "a": 3, "e": ".【D】D项正确：本题解析关键在弄清楚遗传物质的来源。生物的遗传物质存在于细胞核内，细胞核是遗传的控制中心。从题干可知，克隆羊体内的遗传物质来自于白细毛公羊的细胞核，具有白细毛公羊的全部遗传物质，因此最终克隆羊的形状应该是最像提供细胞核的白色细毛公羊，体表的毛为白色细羊毛，性别为公羊。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-544", "q": "生物多样性是指在一定时间和一定地区内所有生物物种及其遗传变异和生态系统的复杂性。衡量生物多样性丰富程度的基本标志是：", "options": ["遗传多样性", "基因多样性", "环境多样性", "物种多样性"], "a": 3, "e": ".【D】总和；C选项错误，环境多样性会对生物产生影响，但不是生物多样性的标志；生物多样性是指在一定时间和一定地区所有生物(动物、植物、微生物)物种及其遗传变异和生态系统的复杂性的总称；D选项正确，衡量生物多样性丰富程度的基本标志是物种多样性。故本题答案选D。", "tag": "科技常识"},
{"id": "tech-545", "q": "自然界中，我们看到大部分植物的叶片都呈现绿色，对此解释正确的是（）。", "options": ["叶片进行光合作用吸收了绿光", "叶片进行光合作用释放出绿光", "叶片反射了太阳光中的绿光", "叶片表皮覆盖着一层绿色物质"], "a": 2, "e": ".【C】不透明的物体的颜色是由它反射的光的颜色决定的，植物叶子是不透明的。当阳光照在叶片上，阳光的七彩颜色被叶片吸收，只有绿色光被反射。所以，植物的叶子大多是绿色的。其他选项本身说法错误。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-546", "q": "关于“螳螂捕蝉，黄雀在后”，下列说法错误的是：", "options": ["蝉、螳螂和黄雀都是消费者", "螳螂和黄雀的行为都属于先天性行为", "螳螂、蝉和黄雀组成了一个生态系统", "蝉和螳螂属于节肢动物，黄雀属于鸟类"], "a": 2, "e": ".【C】A项正确，消费者在自然界中的定义：为食物链中的一个环节，代表着不能生产，只能通过消耗其他生物来达到自我存活的生物。螳螂、蝉、黄雀符合消费者的概念。B项正确，先天性行为，就是生来就有的一种本能，由动物体内的遗传物质所决定的行为，如蜜蜂采蜜，蚂蚁建巢，蜘蛛织网，鸟类迁徙，动物捕食等。与先天性行为相对的后天性行为是在相应环境中通过学习而建立起来的一种反射和习惯，能让生物更好的适应环境。它们都是自养生物；分解者，以各种细菌（寄生的细菌属于消费者，腐生的细菌是分解者）和真菌为主，也包含屎壳郎、蚯蚓等腐生动物；消费者，见A项解释。故螳螂、蝉和黄雀不能构成一个生态系统。D项正确，螳螂和蝉属于无脊椎动物中的节肢动物，黄雀属于鸟类。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-547", "q": "关于水稻，下列说法错误的是：", "options": ["是一年生的禾本科植物", "大多为自花授粉并结出种子", "中国、印度、日本都是主产国", "淀粉含量是早、中、晚品种的分类标准"], "a": 3, "e": ".【D】A项正确，水稻是一年生禾本科植物，禾亚科稻属。水稻所结子实即稻谷，稻谷(粒)去壳后称大米、香米、稻米。世界上近一半人口都以大米为食。B项正确，自花授粉指一株植物的花粉，对同一个体的雌蕊进行授粉的现象。大部分水稻是自花授粉并结出种子。C项正确，水稻的主要生长区域是中国南方、朝鲜半岛、日本、东南亚、南亚、地中海沿岸、美国东南部、中美洲、大洋洲和非洲部分地区。D项错误，早、中、晚稻主要根据播种期和收获期而划分。以中国长江中下游地区为例，早稻一般于3月底4月初播种，", "tag": "科技常识"},
{"id": "tech-548", "q": "下列自然保护区与主要保护的珍稀动物对应错误的是：", "options": ["卧龙自然保护区----大熊猫", "扎龙自然保护区----丹顶鹤", "喀纳斯自然保护区----金丝猴", "可可西里自然保护区----藏羚羊"], "a": 2, "e": ".【C】本题考查我国珍稀动物的相关知识。A项对应正确：卧龙自然保护区位于四川盆地西缘，主要保护西南高山林区自然生态系统及大熊猫等珍稀动物；B项对应正确：扎龙自然保护区位于黑龙江省齐齐哈尔市东南30千米处，主要保护对象为丹顶鹤等珍禽及湿地生态系统。该保护区具有中国北方同纬度地区中保留最完整、最原始、最开阔的湿地生态系统；C项对应错误：喀纳斯自然保护区位于新疆北部阿尔泰山南坡，主要保护对象为寒温带针阔叶混交林生态系统和自然景观。保护区内珍稀动物有盘羊、雪豹、北山羊、紫貂、石貂、马鹿、兔狲、扫雪、猞猁、雪兔、黑琴鸡、花尾棒鸡、丹顶鹤、黑颈鹤等。但该保护区内没有金丝猴，金丝猴在我国一般分布于西南山区；D项对应正确：可可西里自然保护区位于青海省玉树藏族自治州西部，主要保护对象为藏羚羊、野牦牛、藏野驴、藏原羚等珍稀野生动物、植物及其栖息环境。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-549", "q": "近年来为治疗和改善冠心病引起的心肌供血不足、心脏动脉阻塞的常用新技术是（）", "options": ["心脏修补手术", "心脏瓣膜手术", "心脏搭桥手术", "心脏支架手术"], "a": 3, "e": ".【D】急性心肌梗死是在冠心病的基础上，心肌发生急性严重缺血所致的心肌部分坏死。这种坏死是不可逆的，是内科危急重症，在条件好的医院死亡率也高达10%～14%，至少50%死于症状发作后1h内,因此及时正确的处理至关重要。近年来，随着医院水平的不断提高，介入治疗发展迅速，对有适应症的患者在就诊后90分钟内直接急诊心肌梗死支架介入治疗，可改善冠心病引起的心肌供血不足，心脏动脉堵塞。A项错误，是对心脏缺损的一种修补手术。B项错误，是将病变的瓣膜给予修复以达到治疗目的，其通常适用于瓣膜关闭不全的病例。C项错误，是取病人本身的血管（如胸阔内动脉、下肢的大隐静脉等）或者血管替代品，将狭窄冠状动脉的远端和主动脉连接起来，让血液绕过狭窄的部分，到达缺血的部位，改善心肌血液供应，进而达到缓解心绞痛症状，改善心脏功能，提高患者生活质量及延长寿命的目的。这种手术称为冠状动脉旁路移植术，是在充满动脉血的主动脉根部和缺血心肌之间建立起一条畅通的路径。D项正确，是最近20年来开展的改善冠心病引起的心肌供血不足，心脏动脉阻塞的新技术。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-550", "q": "结核病是由结核分枝杆菌引起的慢性传染病，可侵及许多脏器，以肺部结核感染最为常见。下列有关预防结核病的说法，错误的是：", "options": ["打喷嚏时要用手帕捂住嘴，避免面对其他人", "勤洗手，多通风，不随地吐痰", "到人员密集场所，应该一直戴口罩", "多锻炼，提高免疫力"], "a": 2, "e": ".【C】预防结核病，应尽量避免到人员密集场所。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-551", "q": "“旅行者1 号”空间探测器经过36 年的人类星际探索，沿途探索①木星②土星③土卫二④土卫六是否存在生命迹象，并发回资料。阅读表格，依据探测资料判断将来最有可能孕育生命的天体是：", "options": ["①", "②", "③", "④"], "a": 2, "e": ".【C】现代科学证明，液态水是天体中有生命存活的基础。因为只有在适宜的温度条件下水才能以液态形式存在。因此，温度与水密切结合成一切生命现象的环境与资源基础。四个选项中只有C符合。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-552", "q": "生物种间争夺资源和空间的竞争现象，竞争的结果往往对一方不利，甚至于被消灭。生物与生物之间的生活方式和习性、栖所及食物类型越接近，其竞争程度越激烈。下列成语和俗语中描写这种生物种间竞争现象的是：", "options": ["鸠占鹊巢", "一母生九子，连母十个样", "一山不容二虎", "螳螂捕蝉，黄雀在后"], "a": 0, "e": ".【A】A项正确，鸠占鹊巢是指斑鸠占据喜鹊的巢，反映了斑鸠和喜鹊两种生物对资源和空间的竞争现象。B项说的是生物间的差异，C项指的是种内生物间的斗争关系，D项描述的是生物之间的捕食关系。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-553", "q": "人受伤后，如果伤口范围较大或损伤较严重，那么伤口在康复的过程中，尤其是最后结痂时，会有很痒的感觉。产生痒的感觉的原因是：", "options": ["伤口在愈合时，刺激了毛细血管的修复，旧组织被分解吸收，从而产生痒的感觉", "伤口在愈合的过程中，快速生长的新生组织会刺激挤在一起的新生神经，产生痒的感觉", "伤口在愈合时，人体的免疫细胞会清除伤口中的细菌、细菌尸体刺激伤口从而产生痒的感觉", "伤口在愈合的过程中，新组织的生长和旧组织的脱落会摩擦皮肤，从而在伤口周围产生痒的感觉"], "a": 1, "e": ".【B】伤口范围较大，深达真皮的伤口快愈合时常会发痒，这是因为较深伤口的愈合是由一种新的组织补上去的，这种新的组织叫结缔组织。新生的血管和神经都要长出结缔组织。这些新生的血管和神经特别密，都挤在一起，新生的神经容易受到刺激，因为神经非常敏感，所以产生痒的感觉。B项正确。故正确答案为B。本题相关知识点：伤口的愈合过程可分三个阶段：第一个阶段就是凝血止血的过程；第二个阶段是白细胞聚集在伤口，这对抵抗感染有非常重要的作用；第三个阶段就是增生阶段，期间有新的血管和神经形成，以及新鲜肉芽组织生长。伤口瘙痒发生在增生阶段，此时新的血管和神经等都在积极修复伤口，这些组织挤在一起，特别密集，新生的神经容易受到刺激。同时，新生的神经，其末梢神经非常敏感，因此病人会产生瘙痒的感觉。", "tag": "科技常识"},
{"id": "tech-554", "q": "如果父亲和孩子都是A 型血，那么孩子的母亲的血型有几种可能：", "options": ["四种", "三种", "两种", "一种"], "a": 0, "e": ".【A】按照下图可以展现各种ABO配偶所生子女的血型表格:红色部分为符合父亲和孩子都是A型血的情况。则母亲可能的血型有A、B、AB、O四种可能。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-555", "q": "新陈代谢是生物体内全部有序化学变化的总称，其中的化学变化一般都是在酶的催化作用下进行的。下列选项中，直接体现生命新陈代谢的是：", "options": ["长江后浪推前浪，一浪高过一浪", "今春，香肌瘦几分？缕带宽三寸", "江畔何人初见月，江月何年初照人", "庭中地白树栖鸦，冷露无声湿桂花"], "a": 1, "e": ".【B】本题考查科技常识。新陈代谢是指生物体与外界环境之间的物质和能量交换以及生物体内物质和能量的转变过程，它包括物质代谢和能量代谢两个方面。A项错误，“长江后浪推前浪，一浪高过一浪”比喻事物的不断前进，多指新人新事代替旧人旧事，没有直接体现生命新陈代谢。B项正确，“今春，香肌瘦几分？缕带宽三寸”出自元代的《十二月过尧民歌别情》，形容春天身体消瘦，衣带宽出三寸。诗句中的“香肌瘦”直接体现了生命体物质和能量交换过程，即新陈代谢。C项错误，“江畔何人初见月，江月何年初照人”出自唐代张若虚的《春江花月夜》，表现了诗人神思飞跃，但又紧紧联系着人生，探索着人生的哲理与宇宙的奥秘，并未直接体现生命新陈代谢的过程。D项错误，“庭中地白树栖鸦，冷露无声湿桂花”出自唐代王建的《十五夜望月》，意为庭院中月映地白树栖昏鸦，那寒露悄然无声沾湿桂花，描绘了自然现象，并未直接体现生命新陈代谢。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-556", "q": "关于医学常识，下列说法正确的是：", "options": ["在正常情况下，人的血糖值的正常范围在", "成年人安静时心率超过", "父母血型分别为A 型和B 型时，子女血型不可能为O 型", "临床上通常用口腔温度、直肠温度和腋窝温度来代表体温"], "a": 3, "e": ".【D】D项正确：正常体温根据测试部位的不同，体温的正常值稍有差异。临床上常用的体温包括：口腔温度、直肠温度和腋窝温度。A项错误：正常情况下，人的空腹全血血糖正常值范围在，血浆血糖为。B项错误：成年人安静时心率超过时为心动过速。C项错误：根据血型的遗传规律，父母血型分别为A型和B型时，子女血型可能为A型、B型、AB型、O型。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-557", "q": "我国大气，地表水环境与资源管理中实行污染物排放总量控制，这一规定体现的生态规律是：", "options": ["物质循环转换与再生规律", "环境资源的有效极限规律", "物质输入输出的动态平衡规律", "相互依存与相互制约的互生规律"], "a": 1, "e": ".【B】本题考查生物常识，主要考查生态规律相关知识。题干表述污染物的排放要与大气、地表水的承受能力相对应，而不能超过承受极限，否则会造成更为严重的后果，说明环境资源的承受能力是有极限的。B项正确：环境资源的有效极限规律，是指生态系统中作为生物赖以生存的各种环境资源，在质量、数量、空间、时间等方面，都有一定的限度，而不能无限制地供给，因此，每一个生态系统对任何外来干扰都有一定的忍耐极限，当外来干扰超过此极限时，生态系统就会被损伤、破坏甚至瓦解。这一规律要求我们要注意极限，坚持适度原则。A项错误：物质循环转换与再生规律，是指生态系统中，植物、动物、微生物和非生物成分，借助能量的不停流动，由此形成不停顿的物质循环。未体现环境资源的承受能力。C项错误：物质输入输出的平衡规律，是指当一个自然生态系统不受人类活动干扰时，生物与环境之间的输入与输出是相互对立的关系，对生物体进行输入时，环境必然进行输出，反之亦然。未体现环境资源的承受能力。D项错误：相互依存与相互制约的互生规律，主要分为两类：（1）普遍的依存与制约，也称“物物相关”，是指有相同规律，即每一种生物在食物链或食物网中，都占据一定的位置，并具有特定的作用。未体现环境资源的承受能力。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-558", "q": "关于发酵过程，下列说法错误的是：", "options": ["发酵泛指利用微生物制造工业原料或者工业产品的过程", "发酵可以在无氧条件下进行，也可能在有氧条件下进行", "在微生物能量代谢中，发酵仅指专性厌氧微生物和兼性厌氧微生物在无氧的条件下分解各类有机物产生能量的一种方", "柠檬酸和乳酸都可以作为发酵的催化剂"], "a": 3, "e": ".【D】本题考查科技常识。A项正确，发酵一般泛指利用微生物制造工业原料或产品的过程。由微生物（细菌、酵母等）、有机物（主要是碳水化合物）、培养基等在一定的温度和pH条件下进行。B项正确，发酵可在无氧或有氧条件下进行，前者如酒精发酵、乳酸发酵和丙酮、丁醇发酵，后者如抗生素发酵、醋酸发酵、氨基酸发酵和维生素发酵等。C项正确，在微生物能量代谢中，发酵仅指专性厌氧微生物和兼性厌氧微生物在无氧条件下分解各类有机物产生能量的一种方式。如某些酵母菌通过糖酵解途径从分解葡萄糖产生酒精的过程中获得能量。D项错误，微生物合成的有机酸有50多种，其中在国民经济中具有较大用途并已工业生产的有：柠檬酸、乳酸、醋酸、葡萄糖酸、苹果酸等。因此柠檬酸和乳酸都属于发酵产物而不是催化剂，发酵的催化剂一般是微生物，如酵母菌、乳酸菌等。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-559", "q": "下列生物及其生殖方式对应不正确的是（）。", "options": ["酵母菌——出芽生殖", "变形虫——分裂生殖", "蘑菇——孢子生殖", "大肠杆菌——营养生殖"], "a": 3, "e": ".【D】本题主要考查生物常识——生物的生殖方式。生物体产生自己的后代的过程，叫做生物的生殖。生物分有性生殖和无性生殖两种。有性生殖：必须经过两性生殖细胞（精子，卵细胞）的结合形成受精卵再发育成新个体。无性生殖：不通过两性生殖细胞，由母体产生新个体，无性生殖方式主要有分裂生殖，出芽生殖，孢子生殖和营养生殖。A项正确，出芽生殖又叫芽殖，其中“芽”是指在母体上长出的芽体，即芽基，芽基并不立即脱离母体，而与母体相连，继续接受母体提供养分，直到个体可独立生活才脱离母体，如珊瑚虫、水螅、酵母菌等；B项正确，分裂生殖又叫裂殖，即母体分裂成两个或多个大小形状相同的新个体的生殖方式，如变形虫、草履虫、细菌等；C项正确，孢子生殖是很多孢子植物和真菌等利用孢子进行的生殖方式。孢子是细菌、原生动物、真菌和植物等产生的一种有繁殖或休眠作用的生殖细胞，能直接发育成新个体，如蘑菇、青霉等；D项错误，营养生殖是由高等植物的根、茎、叶等营养器官发育成新个体的生殖方式。例如，甘薯的块根繁殖、草莓的匍匐茎繁殖、马铃薯的块茎繁殖、百合和洋葱的鳞茎繁殖、水仙和芋的球茎繁殖及秋海棠的叶芽繁殖等。大肠杆菌属于细菌的一种，其生殖方式为分裂生殖，而不是营养生殖。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-560", "q": "中医的四诊“望”“闻”“问”“切”是摸脉象。这里的脉是指：", "options": ["筋腱", "静脉", "动脉", "经络"], "a": 2, "e": ".【C】C项正确：中医认为，脉是气血运行的通道，脉诊是中医四诊不可或缺的一个方面。中医诊的“脉”指的是桡动脉，动脉具有搏动性，有助医生通过脉象判断病情。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-561", "q": "在日常生活当中，我们要关照老年人的行走和坐车安全，特别要防止老年人跌倒，这是因为老年人的骨骼（）。", "options": ["有机物增多，硬度小，易骨折", "有机物增多，硬度小，易变形", "无机物增多，弹性小，易骨折", "无机物增多，弹性大，易变形"], "a": 2, "e": ".【C】少年儿童的骨成分有机物超过1/3，无机物不到2/3，这样的骨柔韧，弹性大，不易发生骨折，但易变形。中年人的骨的成分有机物约为1/3，无机物约为2/3，这样的骨骼既坚韧，又有弹性。老年人的骨的成分有机物不到1/3，无机物超过2/3，这样的骨硬、脆，易发生骨折。综上所述，老年人跌倒后容易发生骨折，这是因为老年人骨骼无机物增多，弹性小，易骨折，C正确。A、B选项有机物比较多的是少年儿童的骨骼，D选项易变形的是少年儿童的骨骼。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-562", "q": "一般情况下，人体内的血液约有20%贮存在贮血器官里。下列不属于人体贮血器官的是（）。", "options": ["脾脏", "肝脏", "心脏", "皮肤"], "a": 2, "e": ".【C】A项正确，脾的主要功能是过滤和储存血液，被称为“血液仓库”。B项正确，肝是贮藏血液的主要器官，有调节血量的功能。C项错误，心脏是人体循环系统的主要器官，在人体的血液循环过程中提供主要动力。D项正确，皮肤是人体最大的器官，由表皮、真皮（中胚层）、皮下组织三层组成，真皮层中有很多毛细血管和小静脉丛，平时血流比较缓慢，当人体亟需时，也可将贮存的血液释放到循环中。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-563", "q": "在北京田径世锦赛上，当看到中国运动员夺金时，许多观众会出现心跳加快、面红耳赤、血压升高的现象。这种现象是由于（）。", "options": ["肾上腺激素分泌增多", "性激素分泌增多", "甲状腺激素分泌增多", "生长激素分泌增多"], "a": 0, "e": ".【A】A项正确，肾上腺素能使心肌收缩力加强、兴奋性增高，传导加速，心输出量增多。外在表现就是心跳加快、面红耳赤、血压升高等现象。B项错误，性激素的作用是促进性器官成熟、副性征发育及维持性功能等。C项错误，甲状腺素的主要作用是促进物质与能量代谢,促进生长和发育过程。D项错误，生长激素的主要生理功能是促进神经组织以外的所有其他组织生长；促进机体合成代谢和蛋白质合成；促进脂肪分解。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-564", "q": "呼吸作用是生物体细胞把有机物氧化分解并产生能量的过程，没有氧气参与的呼吸称为无氧呼吸，无氧呼吸是指细胞在缺氧的条件下，通过酶的催化作用把葡萄糖等有机物分解为尚未彻底氧化的产物。下列现象与无氧呼吸有关的是：", "options": ["人剧烈运动后肌肉酸痛", "用糯米和酒曲酿造米酒", "农作物受涝时短时间内不会死亡", "把生水果和熟苹果放在密闭的缸里催熟"], "a": 0, "e": ".【A】呼吸作用是指生物体内的有机物在细胞内经过一系列的氧化分解，最终生成二氧化碳、水或其他产物，并且释放出能量的总过程。有氧气参与时的呼吸作用，称之为有氧呼吸；没氧气参与的反应，则称为无氧呼吸。A项无氧运动是指肌肉在“缺氧”的状态下高速剧烈地运动，这一过程需要能量（糖分），且没有氧气参与，属于无氧呼吸。B项运用的是酵母菌的繁殖，并非是细胞的呼吸，也不涉及能量的释放。C项农作物受涝时，也会产生无氧呼吸，对植物来说无氧呼吸就意味着死亡，选项说不会死亡，不是因为无氧呼吸，而是因为及时地进行了有氧呼吸。简单地说，如果植物死了和无氧呼吸有关，如果没有，说明和无氧呼吸无关。D项把生水果和熟苹果放在密闭的缸里催熟原理是水果在密闭空间里，果皮表面逸散分泌出一种叫做“乙烯”的气体，这种气体具有加速水果成熟的功用。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-565", "q": "下列关于水生动物的说法错误的是：", "options": ["鲨鱼用鳃呼吸，鲨鱼属于鱼类", "黄鳝的鳃严重退化无法用鳃呼吸，黄鳝不属于鱼类", "蓝鲸没有鳃，用肺进行呼吸，蓝鲸属于哺乳动物", "海龟没有鳃，用肺进行呼吸，海龟不属于哺乳动物"], "a": 1, "e": ".【B】黄鳝的鳃已经退化，不能独立完成水中呼吸，所以口腔及咽腔壁膜帮助呼吸，常将头伸露水面外进行呼吸。水枯竭时，尚能退到低湿处或钻入淤泥内较长时间而不致死亡。但黄鳝仍属于鱼类。A、C、D三项均正确。本题为选非题，故正确答案选B。", "tag": "科技常识"},
{"id": "tech-566", "q": "下列生活中保存食物的方法，理解错误的是：", "options": ["盐腌制食品是因为盐可以形成高渗环境，抑制了微生物的生理活动", "真空保存食物可以破坏需氧菌类的生存环境", "冷藏保存食物是因为低温可以将细菌冻死", "充入氮气保存食品是为了隔绝食品和氧气的接触"], "a": 2, "e": ".【C】食物放在冰箱中可以保存较长时间，原因是低温可以抑制细菌生长繁殖，并不是低温将细菌冻死。A、B、D三项保存食物的方法都正确。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-567", "q": "DNA 检测技术的应用对执法部门侦破案件起到重要作用，有效地减少了错案的出现。下列有关遗传物质的说法正确的是：", "options": ["DNA 是一种遗传物质，同一家族每个人都相同", "DNA 是一种蛋白质，每个人都不同", "只有染色体才是遗传物质，父子之间一模一样", "DNA 是一种遗传物质，它可由亲代遗传给子代"], "a": 3, "e": ".【D】D项正确，DNA是一种遗传物质，多数生物的基因由脱氧核糖核酸（DNA）构成，并在染色体上作线状排列，DNA可由亲代遗传给子代，D项正确。A项错误，世界上没有两个人的DNA是完全相同的；B项错误，DNA属于核酸，不是蛋白质；C项错误，染色体并非遗传物质，只是遗传物质的载体。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-568", "q": "父母血型分别是A 和AB，其子女可能的血型是（）。", "options": ["", "", "AB.", "", "", "AB、O", "", "AB、O", "", "", "O"], "a": 0, "e": ".【A】一般来说血型是终生不变的。人类的血型通常分为A、B、O和AB四种。血型遗传借助于细胞中的染色体。人类细胞中共有23对染色体，每对染色体分别由两条染色体组成，其中一条来自父亲，另一条来自母亲。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-569", "q": "下列关于果酒、果醋、泡菜等的制作，叙述正确的一项是（）。", "options": ["均可以使用自然菌种", "均需高温高压灭菌", "均需控制无氧条件"], "a": 1, "e": ".【B】B项正确：果酒、果醋、泡菜等的制作均可以使用自然菌种使其自然发酵。A项错误：果酒的制作需用酵母菌，酵母菌是真核细胞，而非原核细胞。C项错误：三者制作都需要利用菌种，而非灭菌。D项错误：果酒的制作过程中酵母菌无氧呼吸产生酒精，不需要氧气；泡菜的制作过程中乳酸菌将葡萄糖发酵为乳酸，不需要氧气；果醋的制作过程中醋酸杆菌有氧呼吸产生乙酸，需要氧气。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-570", "q": "以下有关动物的说法不正确的是：", "options": ["孵化小海龟时的温度决定了它们的性别", "现存最原始的哺乳动物鸭嘴兽仅分布于澳大利亚", "青蛙和乌龟的体温会随环境的变化而变化"], "a": 0, "e": ".【A】A项错误，珊瑚礁是石珊瑚目的动物形成的一种结构，在深海和浅海中均有珊瑚礁存在，它们是成千上万的由碳正确。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-571", "q": "关于夜盲症，下列说法不正确的是：", "options": ["夜盲症在光线昏暗的环境下视物不清", "多食用橘子有助于夜盲症的治疗", "夜盲症可能来自遗传", "缺乏维生素A 可能引起夜盲症"], "a": 1, "e": ".【B】A、C、D三项正确，夜盲就是在暗环境下或夜晚，视力很差或完全看不见东西。夜盲症俗称“雀蒙眼”，在夜间或光线昏暗的环境下视物不清，行动困难。夜盲症发生的原因如下：（1）暂时性夜盲：由于饮食中缺乏维生素A或因某些消化系统疾病影响维生素A的吸收，致使视网膜杆状细胞没有合成视紫红质的原料而造成夜盲。这种夜盲是暂时性的，只要多吃猪肝、胡萝卜、鱼肝油等，即可补充维生素A的不足，很快就会痊愈。（2）获得性夜盲：往往由于视网膜杆状细胞营养不良或本身的病变引起。常见于弥漫性脉络膜炎、广泛的脉络膜缺血萎缩等，这种夜盲随着有效的治疗、疾病的痊愈而逐渐改善。（3）先天性夜盲：系先天遗传性眼病，如视网膜色素变性，杆状细胞发育不良，失去了合成视紫红质的功能，所以发生夜盲。B项错误，橘子富含维生素C，夜盲症主要是缺乏维生素A。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-572", "q": "下列关于生物的描述不正确的是：", "options": ["蚯蚓属于雌雄异体的动物", "梅花先开花后长叶子", "大鲵（娃娃鱼）属于两栖动物", "母鸡无须交配就可以下蛋"], "a": 0, "e": ".【A】蚯蚓是对环节动物门寡毛纲类动物的通称。在科学分类中，它们属于单向蚓目。身体两侧对称，具有分节现象；没有骨骼，在体表覆盖一层具有色素的薄角质层；除了身体前两节之外，其余各节均具有刚毛；雌雄同体，异体受精，生殖时借由环带产生卵茧，繁殖下一代。B、C、D三项描述均正确。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-573", "q": "下列关于人体的描述不正确的是：", "options": ["最小的骨头是听小骨", "硬度最高的部分是头骨", "皮肤是最大的器官", "最大的内分泌腺是甲状腺"], "a": 1, "e": ".【B】牙齿是一种在很多脊椎动物身上都存在的器官，是人体最坚硬的部分。一般而言，牙齿呈白色（正常人略带微黄色），质地坚硬。牙齿的各种形状适用于多种用途，包括撕裂、磨碎食物等。牙齿是动物天生的自卫武器。人类语言发音与口中前排上下的牙齿密切相关，古汉族标准语被称为“雅言”。牙齿的整洁，甚至关系到社交活动和地位。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-574", "q": "关于化石燃料，下列说法不正确的是：", "options": ["是古代生物遗体在特定地质条件下形成的、可作燃料和化工原料的沉积矿产", "包括煤、石油和沼气", "大量使用该燃料，会引起全球气候变暖", "是不可再生的资源"], "a": 1, "e": ".【B】化石燃料亦称矿石燃料，是一种碳氢化合物或其衍生物，其包括的天然资源有煤、石油和天然气等。它是古代生物遗体在特定地质条件下形成的、可作燃料和化工原料的沉积矿产。人类不断地燃烧化石燃料而排放二氧化碳（温室气体的主要来源之一）是加快全球变暖的因素之一。化石燃料是不可再生的珍贵资源。而沼气是各种有机物质在隔绝空气（还原条件）并在适宜的温度、湿度下，经过微生物的发酵作用产生的一种可燃性气体，沼气不是化石燃料。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-575", "q": "下列生化指标与体检项目对应正确的是：", "options": ["转氨酶——血常规检查", "总胆固醇——血脂检查", "血肌酐——肝功能检查", "血小板——肾功能检查"], "a": 1, "e": ".【B】A项错误，血常规检查是临床上最基础的化验检查之一。血常规检查项目包括红细胞、白细胞、血红蛋白及血小板数量等。因而，血常规检查不包括转氨酶，而转氨酶为肝功能的检查项目；B项正确，血脂检查是对血液(血浆)中所含脂类进行的一种定量测定方法。血脂是血浆中的中性脂肪(甘油三酯和胆固醇)和类脂(磷脂、糖脂、固醇、类固醇)的总称,广泛存在于人体中。它们是生命细胞的基础代谢必需物质；C项错误，肝功能有两层意思，一是指肝脏的生理功能，即解毒功能、代谢功能、分泌胆汁、免疫防御功能等；另一方面是指医院检验科里的医学检验项目，包括胆红素、白蛋白、球蛋白、转氨酶、r-谷氨酰转肽酶等等；D项错误，常用尿液显微镜检查和化学检查以及血液的某些化学检查等指标来衡量肾功能的变化。常用的测定项目有：尿样、尿比重、尿沉渣镜检、尿素氮、肌酐、非蛋白氮定量以及酚红排泄实验等。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-576", "q": "下列药品中，没有杀毒消菌作用的是：", "options": ["生理盐水", "紫药水", "双氧水", "碘酒"], "a": 0, "e": ".【A】A项错误，生理盐水，是指生理学实验或临床上常用的渗透压与动物或人体血浆的渗透压相等的氯化钠溶液。生理盐水浓度用于两栖类动物时是0.67%～0.70%，用于哺乳类动物和人体时是0.85%～0.9%人们平常点滴用的氯化钠注射液浓度是0.9%,可以当成生理盐水来使用。生理盐水的作用是避免细胞破裂，它的渗透压和细胞外的一样，所以不会让细胞脱水或者过度吸水；B项正确，甲紫属于三苯甲烷类染料消毒剂，和微生物酶系统发生氢离子的竞争性对抗，使酶成为无活性的氧化状态，从而发挥杀菌作用。主要对革兰氏阳性菌如葡萄球菌、白喉杆菌，以及绿脓杆菌、白念珠菌、表皮癣菌有杀灭作用；C项正确，过氧化氢化学式为，俗称双氧水。外观为无色透明液体，是一种强氧化剂，其水溶液适用于伤口消毒及环境、食品消毒；D项正确，碘酊也叫碘酒，碘和碘化钾的酒精溶液。能渗入皮肤杀死细菌（2%～3%碘酊用作皮肤消毒，1%碘酊用作口腔黏膜消毒）。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-577", "q": "关于农作物，下列说法正确的是：", "options": ["中国是最早栽培大豆的国家", "玉米是通过丝绸之路传入中国的", "花生是世界上最主要的油料作物", "泰国是世界上最大的稻米出口国"], "a": 0, "e": ".【A】A项正确，大豆起源于中国，中国学者大多认为原产地是云贵高原一带。我国是最早种植大豆的国家，也是最早利用大豆制成豆腐制品的国家；B项错误，玉米是在1492年哥伦布发现美洲以后，才传到旧大陆各国的，不是通过丝绸之路传入中国的；C项错误，受人口的增长和市场对植物油需求量不断增加的影响，世界油料作物快速发展。与1990年相比，四大主要油料作物分别是大豆、油菜、花生、向日葵，产量呈现出较大幅度的增长；D项错误，虽然在过去两、三年时间里，泰国大米出口受到多重不利因素的影响，导致2012、2013年连续两年失去世界第一大米出口国的宝座，落在印度和越南之后，并造成泰国大米库存量居高不下。但表达过于绝对，属于半正确选项，而A项大豆是客观描述，正确。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-578", "q": "下列说法错误的是：", "options": ["蓝藻对地球表面从无氧到有氧的大气环境起了巨大作用", "植物光合作用主要在细胞的线粒体进行", "呼吸作用分为有氧呼吸和无氧呼吸两种类型", "种子植物是地球表面绿色的主体"], "a": 1, "e": ".【B】A项正确，蓝藻是原核生物，又叫蓝绿藻、蓝细菌；大多数蓝藻的细胞壁外面有胶质衣，因此又叫粘藻。在所有藻类生物中，蓝藻是最简单、最原始的一种。蓝藻对地球表面从无氧到有氧的大气环境起了巨大作用；B项错误，植物呼吸作用主要在细胞的线粒体进行；光合作用在细胞的叶绿体进行；C项正确，生物的呼吸作用包括有氧呼吸和无氧呼吸两种类型；D项正确，种子植物是植物界进化程度最高的种类，世界上已分化出20余万种，是现今地球表面绿色的主体。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-579", "q": "下列哪组不属于夺命“急症”：", "options": ["肺栓塞、哮喘", "冠心病、毒品过量", "脑出血、急性坏死性胰腺炎", "阑尾炎、腹膜炎"], "a": 3, "e": ".【D】心源性疾病，特别是冠心病、急性心肌梗死患者最为多见，容易猝死，常见的夺命“急病”有：肺栓塞、脑出血、尾炎是指阑尾由于多种因素而形成的炎性改变，为外科常见病；腹膜炎是由细菌感染、化学刺激或损伤所引起的外科常见的一种严重疾病，如未能及时治疗，可死于中毒性休克。腹膜炎属于夺命急症而阑尾炎不是，故D项表述错误。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-580", "q": "下列与现代通讯科技有关的说法错误的是：", "options": ["高密度无线网络技术是5G 移动通信技术的关键之一", "计算机通信的基本原理是将逻辑信号转换为电信号", "路由器可以根据信道情况自动选择和设定路由", "无线局域网利用射频技术进行通信连接​"], "a": 1, "e": ".【B】本题考查科技常识。A项正确，5G移动通信标志性的关键技术主要体现在超高效能的无线传输技术和高密度无线网络技术。B项错误，计算机通信的基本原理是将电信号转换为逻辑信号，其转换方式是将高低电平表示为二进制数中的1和0，再通过不同的二进制序列来表示所有的信息。C项正确，路由器是连接因特网中各局域网、广域网的设备，它会根据信道的情况自动选择和设定路由，以最佳路径，按前后顺序发送信号。D项正确，无线局域网是计算机网络与无线通信技术结合的产物，它以无线信道作传输媒介，利用射频技术实现局域网的全部功能，是一种更灵活、建网速度快、适合移动办公及有线网络难以达到的接入方式。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-582", "q": "关于核磁共振，下列说法错误的是：", "options": ["核磁共振技术可以进行地下水探测", "核磁共振技术常用于脑肿瘤的检测", "核磁共振会产生电离辐射影响人体健康", "带有心脏起搏器的病人不能做核磁共振"], "a": 2, "e": ".【C】本题考查科技常识。核磁共振是磁矩不为零的原子核，在外磁场作用下自旋能级发生塞曼分裂，共振吸收某一定频率的射频辐射的物理过程。A项正确，核磁共振地下水探测技术是一种进行地下水探测的新方法，是通过测量地层水中的氢核来实现直接找水的新技术。具有可以直接反演出地下0-150m深度的含水层位置、含水量大小、介质孔隙度及电导率等地质水文信息的优点，已广泛应用于我国的地下水勘探领域，尤其是在旱区进行水文地质调查，为缓解旱灾提供了有效的技术支持。B项正确，核磁共振是一种生物磁自旋成像技术，利用人体中的遍布全身的氢原子在外加的强磁场内受到射频脉冲的激发，产生核磁共振现象，经过空间编码技术，用探测器检测并接受以电磁形式放出的信号，输入计算机，形成人体各组织的形态形成图像。脑磁共振具有无放射线损害，无骨性伪影，能多方面、多参数成像，有高度的软组织分辨能力，能不用对比剂即可显示血管结构，即在磁共振照片上也就把肿瘤的轮廓勾勒出来了。C项错误，核磁共振成像是一种利用核磁共振原理的最新医学影像新技术。由于核磁共振是磁场成像，没有放射性，所以对人体无害，是非常安全的。D项正确，由于金属会对外加磁场产生干扰，患者进行核磁共振检查前，必须把身体上的金属物全部拿掉。戴有心脏起搏器的病人，体内有顺磁性金属植入物，如金属夹、支架、钢板和螺钉等，这些金属都对外加磁场进行干扰，无法正常地检查。因此，带有心脏起搏器的病人不能做核磁共振。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-583", "q": "2016 年3 月，阿尔法围棋程序（AlphaGo）对战世界围棋冠军、职业九段选手李世石，以4:1 的总比分获胜。阿尔法围棋程序的工作原理基于下列哪项技术？", "options": ["量子计算", "深度学习", "纳米技术", "基因编辑"], "a": 1, "e": ".【B】B项正确：“深度学习”是机器学习研究的一个新领域。其动机在于建立、模拟人脑进行分析学习的神经网络，让机器模仿人脑机制来解释数据甚至进行“思考”，例如图像、声音和文本。阿尔法围棋程序正是运用了这样的技术，当选；A项错误：量子计算是一种依照量子力学理论进行的新型计算。同普通计算机相比，量子计算机的寄存器可同时存储四个二进制数，因此具有更强的计算能力。应用此技术可以大幅提高计算机运算能力，但此技术与阿尔法围棋程序无关，排除；C项错误：纳米技术是用单个原子、分子制造物质的科学技术，研究结构尺寸在1-100纳米范围内材料的性质和应用。在计算机方面更多地应用于将硬件零件缩小化，用以提高计算机性能，但与阿尔法围棋程序无关，排除；D项错误：基因编辑是指生物学中能够让人类对目标基因进行“编辑”，实现对特定DNA片段的敲除、加入等的技术，属于生物范畴的技术。阿尔法围棋程序属于计算机范畴应用，两者无关，排除。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-584", "q": "下列关于航天器的说法正确的是：", "options": ["“风云”系列气象卫星通过光纤实现与地面的数据传输", "“玉兔”号月球车在月球上行走的动力驱动是电动车", "“长征一号”属于二级运载火箭", "“北斗二号”属于通信广播卫星"], "a": 1, "e": ".【B】B项正确：由于月球表面没有空气，常规动力（风力、内燃机动力等）不具备供给条件，而月球光照充足，太阳能电池功能是目前的最优解决方案，所以在月球上可以用太阳能电池提供电能，因此“玉兔”号月球车在月球上行走的动力驱动是电动车，当选；A项错误：“风云”系列气象卫星的数据传输是通过几个不同的波段实时数据传输信号的方式进行传输。题干中的光纤是有线的，不可能从卫星上连接到地球，排除；C项错误：“长征一号”是为发射我国第一颗人造地球卫星东方红一号而研制的三级运载火箭，排除；D项错误：“北斗二号”卫星导航系统是中国独立开发的全球卫星导航系统，属于通信卫星，但不属于广播卫星，排除。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-585", "q": "下列我国重大科技成就时间先后顺序排列正确的是：①第一颗人造卫星发射成功②第一台亿次巨型计算机研制成功③神舟五号载人飞船成功返航④第一株籼型杂交水稻培育成功⑤第一颗原子弹爆炸成功⑥三峡大坝全线修建成功", "options": ["①④⑤③⑥②", "⑤①④②③⑥", "④①⑤⑥②③", "⑤⑥①②④③"], "a": 1, "e": ".【B】本题考查科技常识。①“东方红一号”卫星，是中国发射的第一颗人造地球卫星，于1970年4月24日在酒泉卫星发射中心成功发射，由此开创了中国航天史的新纪元，使中国成为继苏、美、法、日之后世界上第五个独立研制并发射人造地球卫星的国家。②1983年12月22日，国防科技大学研制成功我国第一台亿次巨型计算机银河-I，运算速度每秒1亿次。③2003年10月16日，神舟五号载人飞船成功返航。④1973年，袁隆平在世界上首次培育成功籼型杂交水稻。⑤1964年10月16日下午3时，在我国西部地区新疆罗布泊上空，中国第一次将原子核裂变的巨大火球和蘑菇云升上了戈壁荒漠，第一颗原子弹爆炸成功。⑥三峡水电站是中国湖北省宜昌市境内的长江西陵峡段与下游的葛洲坝水电站构成梯级电站。三峡大坝于2006年全线修建成功。我国重大科技成就时间先后顺序排列为⑤①④②③⑥。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-586", "q": "2019 年是中国航天的超级大年，在这一年取得的成就不包括的是：", "options": ["嫦娥4 号在月球背面登陆", "长征11 号火箭中国首次海上平台发射", "长征三号运载火箭发射北斗卫星第54 颗", "中国运力最强的长征五号遥三“胖五”发射"], "a": 2, "e": ".【C】本题考查科技常识。A项正确，2019年1月3日，“嫦娥四号”探测器成功着陆在月球背面，这也是迄今为止人类首次在月球背面进行登陆活动。B项正确，2019年6月5日，长征11号火箭在我国黄海实施发射，成功将捕风一号A/B卫星、中电网通一号A/B卫星、吉林一号高分03A卫星、天启三号卫星和潇湘一号04星共计7颗卫星送入轨道。此次发射填补了我国运载火箭海上发射空白，为中国快速进入太空提供了新型发射模式。C项错误，2020年3月9日，我国在西昌卫星发射中心用长征三号乙运载火箭，成功发射北斗系统第54颗导航卫星。卫星顺利进入预定轨道，后续将进行变轨、在轨测试、试验评估，适时入网提供服务。D项正确，“胖五”特指我国长征五号系列运载火箭，它是是我国最大推力的大型运载火箭，具备近地轨道25吨级、地球同步转移轨道14吨级的运载能力。2019年12月27日，长征五号遥三运载火箭在文昌卫星发射中心点火起飞，成功将实践二十号卫星送入预定轨道。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-587", "q": "下列关于激光的说法错误的是：", "options": ["“激光”一词是受激辐射放大光的简称", "产生激光的必要条件是要有泵浦源和谐振腔", "激光按不同的波长可以分为红外激光、可见激光和紫外激光", "激光由于能量高、方向性好，目前广泛应用于测量、加工和军事等领域"], "a": 2, "e": ".【C】本题考查科技常识。A项正确，1916年爱因斯坦提出了一套全新的技术理论“光与物质相互作用”。这一理论是说在组成物质的原子中，有不同数量的粒子（电子）分布在不同的能级上，在高能级上的粒子受到某种光子的激发，会从高能级跳到（跃迁）到低能级上，这时将会辐射出与激发它的光相同性质的光，而且在某种状态下，能出现一个弱光激发出一个强光的现象。这就叫做“受激辐射放大光”，简称激光。B项正确，产生激光需要增益介质、泵浦器和谐振腔三个条件。增益介质是工作物质，比如二氧化碳、蓝宝石等，都可以作为增益介质。泵浦器是用于激发增益介质中的粒子，使得高能粒子增加，这种激发方式被形象地称为泵浦。被激发的强度往往很弱，达不到实用强度，因此使用谐振腔进行放大。通过以上三个条件，才能获得激光。因此，泵浦器和谐振腔是产生激光的必要条件。C项错误，激光按不同的波长可分为：红外激光、可见激光、紫外激光、X射线激光和多波段可调谐激光。D项正确，激光是20世纪60年代的新光源，具有方向性好、亮度高、单色性好和高能量密度等特点。以激光器为基础的激光工业在全球发展执着迅猛，现在已广泛应用于工业生产、测量、通讯、信息处理、医疗卫生、军事、文化教育以及科研等方面。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-588", "q": "国家最高科学技术奖自设立以来，已有33 位杰出科学工作者获得该奖。下列国家最高科学技术奖得主与其主要贡献对应正确的是：", "options": ["李振声一一中国现代预警机事业的开拓者和奠基人，被誉为“中国预警机之父”", "闵恩泽一一从事石油炼制催化剂制造技术领域研究，被誉为“中国催化剂之父”", "曾庆存一一为中国核潜艇事业的发展做出重要贡献，被誉为“中国核潜艇之父”", "侯云德一一从事医学病毒学、新发传染病控制研究，被誉为“中国传染病学之父”"], "a": 1, "e": ".【B】本题考查科技常识。A项错误，李振声，中国科学院院士、第三世界科学院院士，著名小麦遗传育种学家，中国小麦远缘杂交育种奠基人，有“当代后稷”和“中国小麦远缘杂交之父”之称。王小谟，中国现代预警机事业的开拓者和奠基人，被誉为“中国预警机之父”，2013年1月18日荣获2012年度国家最高科学技术奖。B项正确，闵恩泽，石油化工催化剂专家，2007年度国家最高科学技术奖获得者，中国炼油催化应用科学的奠基者，石油化工技术自主创新的先行者，被誉为“中国催化剂之父”。C项错误，曾庆存，气象学、地球流体力学家，为现代大气科学和气象事业的两大领域——数值天气预报和气象卫星遥感做出了开创性和基础性的贡献，2020年1月10日，获得2019年度国家最高科学技术奖。黄旭华，中国第一代攻击型核潜艇和战略导弹核潜艇总设计师，被誉为“中国核潜艇之父”，2020年1月10日，获得2019年度国家最高科学技术奖。D项错误，侯云德，医学病毒学专家，我国分子病毒学和基因工程药物的开拓者，在国内首先研制成功临床级人白细胞干扰素，被誉为“中国干扰素之父”，2018年1月8日，获得2017年度国家最高科学技术奖。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-589", "q": "传媒艺术产生于19 世纪上半叶的摄影术，因此传媒艺术将现代科技对艺术生产作用作为与传统艺术的重要区别之一，正是因为有了光学技术、电子技术、数字技术、人工智能、新媒体技术、数据模型等现代科技，传媒艺术才有了更丰富的艺术表现领域。下列属于传媒艺术的是：", "options": ["电影艺术", "书法艺术", "草编艺术", "剪纸艺术"], "a": 0, "e": ".【A】本题考查科技常识。传媒艺术指自摄影术诞生以来，借助工业革命之后的科技进步、大众传媒发展和现代社会环境变化，在艺术创作、传播视艺术、新媒体艺术等艺术形式，同时也包括一些经现代传媒和传媒技术改造了的传统艺术形式。A项正确，电影艺术是现代科学技术与艺术相结合的产物。电影艺术是以画面和音响为媒介，在银幕上创造出感性直观的形象，再现和表现生活的一门艺术，属于传媒艺术。B项错误，书法艺术的第一批作品是一些刻画符号——象形文字或图画文字。C项错误，草编艺术是民间广泛流行的一种，草编工艺品利用茅草、蒲草、苇草及野草、农作物秸秆，用手工编制而成，具有家具的实用价值、艺术品的观赏、收藏价值的工艺品。D项错误，剪纸艺术是最古老的中国民间艺术之一，作为一种镂空艺术，它能给人以视觉上以透空的感觉和艺术享受。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-590", "q": "2020 年6 月23 日，我国在西昌卫星发射中心用长征三号乙运载火箭，成功发射了北斗三号最后一颗全球组网卫星。至此北斗三号全球导航系统星座部署比原计划提前半年全面完成。下列关于北斗卫星导航系统的说法错误的是：", "options": ["北斗卫星导航系统实施的是“三步走”战略，即北斗一号、北斗二号和北斗三号", "目前，全球三分之一的国家都开始使用北斗卫星导航系统", "北斗卫星导航系统总共由55 颗导航卫星组成", "北斗系统工程于1994 年启动建设"], "a": 1, "e": ".【B】本题考查科技常识。北斗卫星导航系统是我国自主建设、独立运行的全球卫星导航系统，为用户提供全天候、全天时、高精度全球定位导航授时服务。A、D项正确，1994年，我国正式启动北斗卫星导航系统建设。20多年来，探索适合国情的卫星导航系统发展道路，逐步形成了“三步走”发展战略：2000年年底，建成北斗一号系统，向中国提供服务；2012年年底，建成北斗二号系统，向亚太地区提供服务；2020年，建成北斗三号系统，向全球提供服务。B项错误，北斗卫星导航系统广泛开展国际合作，持续推动系统兼容共用。截至2019年年底，国产北斗导航型芯片模块出货量已超1亿片，季度出货量突破1000万片。北斗导航型芯片、模块、高精度板卡和天线已输出到100余个国家和地区。因此三分之一的国家明显低估。C项正确，2020年6月23日，我国在西昌卫星发射中心用长征三号乙运载火箭，成功发射北斗系统第五十五颗导航卫星，暨北斗三号最后一颗全球组网卫星，至此北斗三号全球卫星导航系统星座部署比原计划提前半年全面完成。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-591", "q": "边缘计算指的是在网络边缘结点来处理、分析数据。边缘结点指的就是在数据产生源头和云中心之间任一具有计算资源和网络资源的结点。根据上述信息判断，下列关于边缘计算的说法不正确的是。", "options": ["手机可以看作人与云中心之间的边缘结点", "采用边缘计算会增加网络数据流量", "采用边缘计算可以减少能源的消耗", "采用边缘计算可以减少响应时间"], "a": 1, "e": ".【B】本题考查科技常识。边缘计算指的就是在数据产生源附近分析、处理数据，这样能够减少请求响应时间、提升电池续航能力、减少网络带宽同时保证数据的安全性和私密性。A项正确，根据边缘节点的定义，手机是人（数据产生源头）和云中心之间具有计算资源和网络资源的智能终端，可以看作人和云中心的边缘节点。B项错误，由于边缘计算的数据不需要全部传输到云端，减少了智能设备和数据中心传输的数据量，所以边缘计算会减少网络数据流量。C项正确，部分计算任务从云端卸载到边缘之后，可以减少网络传输和多级转发带来的带宽和时延损耗，故边缘计算可以减少能源的消耗。D项正确，由于数据大多是在边缘结点进行处理和分析，而不是在远程的数据中心或云端进行，减少了传输时间，有效地降低了延迟。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-592", "q": "我国在区块链领域拥有良好基础，要加快推动区块链技术和产业创新发展，积极推进区块链和经济社会融合发展。关于区块链的特征和作用，下列说法不正确的是", "options": ["省去第三方中间环节，降低交易成本", "打通部门间的数据壁垒，实现信息共享", "解决经济社会发展中的“存证”难题，维护社会秩序", "排除管理员外任何人修改信息的可能性，确保信息安全"], "a": 3, "e": ".【D】本题考查科技常识。A项正确，区块链技术通过“去中心化”和“点对点”的特征，进一步减少中间环节，消除了第三方交易中介存在的必要性，从而降低交易成本。因为实现了点对点的交易，中央处理或清算组织成为冗余；因为交易的真实性是由区块链上所有参与者共同验证和维护的，所以作为第三方的信用中介也失去了存在价值。B项正确，区块链“分布式”的特点，可以打通部门间的“数据壁垒”，实现信息和数据共享。与中心化的数据存储不同，区块链上的信息都会通过点对点广播的形式分布于每一个节点，通过“全网见证”实现所有信息的“如实记录”。C项正确，区块链“不可篡改”的特点，为经济社会发展中的“存证”难题提供了解决方案。只要能够确保上链信息和数据的真实性，那么区块链就可以解决信息的“存”和“证”难题。比如在版权领域，区块链可以用于电子证据存证，可以保证不被篡改，并通过分布式账本链接原创平台、版权局、司法机关等各方主体，可以大大提高处理侵权行为的效率。在金融、司法、医疗、版权等对数据真实性要求高的领域，区块链都可以创造安全、高效的应用场景。D项错误，区块链通过时间戳保证每个区块依次顺序相连。时间戳使区块链上每一笔数据都具有时间标记。简单来说，时间戳证明了区块链上什么时候发生了什么事情，且任何人无法篡改，甚至管理员也无法修改。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-593", "q": "下列关于云计算的表述中，错误的是（）。", "options": ["对网络连接的大量计算资源进行统一管理和调度", "云计算的服务器为虚拟系统", "可为用户提供计算及存储服务", "搜索引擎是云计算的典型应用"], "a": 1, "e": ".【B】本题考查科技常识。①云计算是一种通过Internet以服务的方式提供动态可伸缩的虚拟化的资源的计算模式。②云计算服务有三种：基础设施即服务(IaaS)，平台即服务(PaaS)和软件即服务(SaaS)。A项正确，云计算的核心思想就是将大量用网络连接的计算资源统一管理和调度，构成一个计算资源池向用户按需服务。B项错误，云计算的服务器是真实的物理服务器，不是虚拟系统，这区别于云计算的系统虚拟化，后者可以将一台物理服务器上的多个虚拟机完全隔离开来，提高资源利用效率。C项正确，云计算平台可以提供计算服务、数据库服务、存储服务等。这属于云计算服务中的基础设施即服务。D项正确，搜索引擎由线上部分和线下部分组成，它是云计算产生和发展的重要应用，代表有百度、谷歌等等。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-594", "q": "下列文物中，最可能是赝品的是：", "options": ["拍摄于19 世纪70 年代的，展示沙俄宫廷的照片", "制作于明代末年，起矫正视力作用的眼镜", "战国时期记录如何制作青花瓷的竹简", "3000 年前西亚赫梯人使用的铁器"], "a": 2, "e": ".【C】本题考查科技常识中与历史相关的科技成就。A项正确，沙俄时代是指1721年彼得一世加冕为皇帝后，至1917年尼古拉二世退位为止的俄罗斯国家，而照相机是", "tag": "科技常识"},
{"id": "tech-595", "q": "2018 年我国科技界取得了一系列重大成果，这些成果中不包括：", "options": ["第二艘航母出海试航", "嫦娥四号探测器发射成功", "造岛神器“天鲲号”下水", "国产大型水陆两栖飞机水上首飞"], "a": 2, "e": ".【C】本题考查政治常识。A项正确，2018年5月13日，我国第二艘航母从大连造船厂码头启航，赴相关海域执行海上试验任务，主要检测验证动力系统等设备的可靠性和稳定性。B项正确，2018年12月8日2时23分，我国在西昌卫星发射中心用长征三号乙运载火箭成功发射嫦娥四号探测器，开启了月球探测的新旅程。嫦娥四号探测器后续将经历地月转移、近月制动、环月飞行，最终实现人类首次月球背面软着陆，开展月球背面就位探测及巡视探测，并通过已在使命轨道运行的“鹊桥”中继星，实现月球背面与地球之间的中继通信。C项错误，2017年11月3日，由我国自主设计研发的新一代国之重器——“天鲲号”自航绞吸挖泥船成功下水。从被称为“造岛神器”的“天鲸号”，到目前亚洲最大最先进的“天鲲号”，中国自航绞吸挖泥船的自主研制实力再一次让世人惊叹。D项正确，2018年10月20日，中国自主研制的大型水陆两栖飞机——“鲲龙”AG600在湖北荆门漳河机场成功实现水上首飞。至此，中国大飞机终于迈出“上天入海”完整步伐，建设航空强国轮廓愈发明晰。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-596", "q": "2019 年央视春晚给观众带来了全新的视觉体验，采用了一系列“黑科技”，包括5G、4K、VR、AR 等技术。关于这些“黑科技”，下列说法错误的是", "options": ["5G 是一种移动通信技术", "4K 是一种网络传播技术", "VR 是一种虚拟现实技术", "AR 是一种通过虚拟增强现实感官的技术"], "a": 1, "e": ".【B】本题考查科技常识。A项正确，5G是指第五代移动电话行动通信标准，也称第五代移动通信技术。与4G网络相比，5G网络不仅传输速率更高，而且在传输中呈现出低时延、高可靠、低功耗的特点。B项错误，4K，是一种高清显示技术。主要应用于电视行业、电影行业、手机行业等。在数字技术领域，通常采用二进制运算，而且用构成图像的像素来描述数字图像的大小。由于构成数字图像的像素数量巨大，通常以K来表示，因此4K分辨率即4096×2160的像素分辨率，属于超高清分辨率。在此分辨率下，观众将可以看清画面中的每一个细节。因此，", "tag": "科技常识"},
{"id": "tech-597", "q": "2019 年1 月3 日，嫦娥四号探测器在月球背面成功着陆，并与玉兔二号巡视器顺利分离，实现了多个国际首次。对此，下列说法不正确的是", "options": ["首次进行了月基低频射电天文观测", "首次在月球背面软着陆和巡视探测", "首次实测了月球表面浅层月壤温度", "首次实现地球和月球背面的中继通信"], "a": 2, "e": ".【C】本题考查科技常识。A项正确，2019年1月3日，嫦娥四号探测器登陆月球背面，搭载了由中国科学院空天信息研究院研制的巡视器（“玉兔二号”月球车）测月雷达和着陆器低频射电频谱仪有效载荷。1月4日00时20分，低频射电频仪成功加电开机，设备自检正常；当日8时42分，测月雷达成功加电开机，设备自检正常。我国成为国际上首次实现在月球背面开展低频射电天文观测的国家，填补了对100KHz", "tag": "科技常识"},
{"id": "tech-598", "q": "下列关于航天员的太空生活说法不正确的是：", "options": ["太空食品与我们日常食品并无显著差异", "航天员在舱内睡眠可采取直立、倒挂等姿势", "航天员在太空舱内可以直接用语言进行交流", "航天员在舱内工作时可以穿比较舒适的工作服"], "a": 0, "e": ".【A】本题考查科技理论与成就的相关知识。A项错误，太空食品是指经特殊工艺加工而成，专门在太空环境下食用的食物。它包括在太空执行任务和返回着陆等待救援期间供航天员食用的食品和饮水。由于空间环境的不同和航天员生活工作的特点，对太空食品提出了许多特殊要求，如体积小、质量轻、营养丰富、方便进食等。因此，太空食品与日常食品存在显著差异。B项正确，在太空舱内微重力条件下，航天员睡觉不受姿势的限制，可以躺着睡、坐着睡、站着睡，甚至倒立着睡。C项正确，声音的传播需要介质，太空舱内是有空气介质的。因此，宇航员在太空舱内可以直接交流。但在太空舱外作业时，他们之间通话必须借助通信设备进行交流。D项正确，舱内工作服是航天员在飞船入轨后正常飞行时脱去舱内航天服后穿的服装。比如有连身式或分身式长袖服，连身式舱内工作服款式与连身式内衣基本相同，领口为立领，腰部有松紧。因此，航天员在舱内工作时可以穿比较舒适的工作服。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-599", "q": "下列关于我国C919 大型客机研发意义的表述错误的是：", "options": ["社会效益方面，C919 能带动上下游产业发展，增加就业岗位，促进经济社会发展", "技术方面，C919 能提升我国航空工业研发能力，促进航空人才队伍建设，提升民航工业水平", "军事方面，以C919 为平台改装成大型军用特种飞机的潜力巨大，短期内实现其军民两用前景良好", "经济方面，C919 使我国民航不再依赖进口中层干线客机，打破了西方航空垄断，进而节省外汇"], "a": 2, "e": ".【C】本题考查科技常识。C919项目在技术、经济、军事等方面具有很大积极意义。A项正确，在社会效益方面，C919项目能带动上下游产业发展，增加大量高收入的就业岗位，拉动地方经济发展。B项正确，在技术方面，C919能够锻炼中国航空工业在干线客机方面的设计和制造能力，锻炼一批航空人才，提升中国民用航空工业水平。C项错误，在军事方面，用C919改装预警机、高新机等大型军用特种飞机的潜力巨大。事实上，从西方国家大型军用特种飞机改装经验来看，选择的都是经过市场验证，证明是性能可靠、安全成熟的干线客机平台。比如，日本空自现役主力大型空中预警机E-767采用的是1984年交付的波音767-200ER，而波音公司进行首架E-767机体改装工作的时间已经是11年后的1995年。C选项后半句“短期内实现其军民两用前景良好”表述错误。D项正确，在经济方面，C919不仅能使中国民航不再依赖于从欧美进口波音和空客的中层干线客机，并且打破欧美航空巨头垄断，为国家节省了大量外汇。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-600", "q": "无人机，广义上为不需要驾驶员登机驾驶的各式遥控飞行器。一般特指军方的无人侦察飞机。当今世界，在军用无人机开发领域最为先进的两个国家是：", "options": ["美国和英国", "中国和俄罗斯", "美国和中国", "美国和以色列"], "a": 3, "e": ".【D】本题考查科技常识，主要考查无人机的相关知识。在军用无人机领域，美国和以色列这两个国家是世界上最强的两个研发、生产并将无人机投入实际应用的两大无人机强国，尤其是在高端军用无人机方面，长期以来，两国一直遥遥领先。因此，D项正确，A、B、C项错误。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-601", "q": "“慧眼”全称硬X 射线调制望远镜，是我国首颗大型射线天文卫星。科学家们将其用来观测宇宙中最神秘的天体，它们是：", "options": ["白矮星和黑洞", "暗物质和中子星", "白矮星和暗物质", "黑洞和中子星"], "a": 3, "e": ".【D】本题主要考查科技理论与成就的相关知识。“慧眼”的全名叫硬射线调制望远镜卫星。它是我国首颗射线天文观测卫星，通过接收宇宙中的射线，研究黑洞与中子星活动特性。“慧眼”卫星应用我国科学家首创的直接解调成像方法，实现宽波段、高灵敏度、高空间分辨率射线巡天、定点和小天区观测，在世界现有射线天文卫星中，具有先进的暗弱变源巡天能力、独特的多波段快速光变观测能力等优势。因此选项A、B、C错误。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-602", "q": "海水稻是指耐盐碱高产水稻的简称，由我国最早发现和培育。关于海水稻，下列表述错误的是：", "options": ["海水稻可在环境恶劣的海边滩涂和盐碱地中生长，保持较低的产量", "海水稻富含大量微量元素，具有很高的营养价值", "海水稻具有不需施肥和抗病虫以及耐盐碱等独特生长特性", "海水稻对资源节约的绿色农业生产大有裨益"], "a": 0, "e": ".【A】本题考查科技常识，主要考查海水稻相关知识。A项错误，海水稻是耐盐碱水稻的简称，这是一种在海边滩涂等盐碱地生长的特殊水稻。2017年10月，海水稻的测产最高亩产达到621公斤，产量较高，不是保持较低产量。B项正确，海水稻生长在盐碱地的土壤，微量元素较高，具有很高的营养价值。C项正确，海水稻在条件恶劣的盐碱地中生长，很少会患有普通水稻的病虫害，基本不需要农药。因此海水稻具有不需施肥、抗病虫、耐盐碱的独特生长特性。D项正确，海水稻基本上不需要农药，是天然的绿色有机食品。海水稻的灌溉用水可以用半咸水，能够节约淡水资源，对资源节约的绿色农业生产大有裨益。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-603", "q": "下列关于北斗卫星导航系统用途的说法中，不正确的一项是（）。", "options": ["导航与通信的集成增强了导航能力和搜索救援能力，可实现用户信息共享和信息交换", "多系统兼容服务，可以实现公开服务相互兼容，必要时提供多系统监测信息和差分改正信息", "卫星使用寿命较长，目前尚未组建完毕，只能提供单向授时授权服务", "以双向伪距时间同步方法摆脱卫星时间同步与精密轨道之间的依赖关系"], "a": 2, "e": ".【C】北斗卫星导航系统是中国着眼于国家安全和经济社会发展需要，自主建设、独立运行的卫星导航系统，是为全球用户提供全天候、全天时、高精度的定位、导航和授时服务的国家重要空间基础设施。主要用途有四个方面：(1)导航与通信的集成增强了导航能力和搜索救援能力,可实现用户信息共享和信息交换。(2)多系统兼容服务，可以实现公开服务相互兼容，必要时提供多系统监测信息和差分改正信息。(3)提供双向授时授权服务。(4)以双向伪距时间同步方法摆脱卫星时间同步与精密轨道之间的依赖关系。所以，C项表述“只能提供单向授时授权服务”错误，A、B、D项正确。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-604", "q": "下列选项不属于航空航天中货运飞船主要任务的是：", "options": ["货运飞船发射升空完成后，会与空间站自动或人工交会对接", "货运飞船进行空间站实验和技术试验，将获取的研究数据回传", "货运飞船为空间站补加推进剂以及空气，带来饮水、食物等补给物资", "货运飞船可充当空间站的“垃圾桶”，将站内废弃物品搬运至货运飞船"], "a": 1, "e": ".【B】本题考查的是科技常识的相关知识。货运飞船是一种专门运送货物到达太空一次性使用的航天器，主要任务是向空间站定期补给食品、货物、燃料和仪器设备等。它是国际空间站补给物资的重要运输工具，也是空间站的地面后勤保障系统。A项正确，货运飞船发射升空后，可以与空间站自动或人工交会对接，从而输送空间站需要的补给物资。B项错误，空间站实验和技术试验，将获取的研究数据回传这是空间站的任务，而不是货运飞船的任务。C项正确，货运飞船可以补给空间站推进剂的消耗，向空间站定期补给饮水、食品等物资。D项正确，空间站丢弃的废弃物和生活垃圾等也可以搬运至货运飞船，随货运飞船进入大气层及地面进行处理。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-605", "q": "关于洲际导弹下列说法错误的是：", "options": ["射程在8000 公里以上", "目前仅有中、美、俄三国拥有", "弹头一般采用核弹头", "中国的东风5 型属于洲际导弹"], "a": 1, "e": ".【B】本题考查与洲际导弹相关的科技常识。A项正确，洲际导弹通常的射程一般大于8000公里，其属于远程弹道式导弹。B项错误，目前洲际导弹的主要拥有国家有美国、俄罗斯、中国、英国和法国。C项正确，洲际导弹的弹头一般都是核弹头。洲际导弹问世后，核聚变弹头进一步发展，使弹头进一步小型化，并便于使用多弹头，从而能够更有力地打击目标。D项正确，中国的东风5型导弹是一种储存在固定的发射井中的洲际弹道导弹，1971年9月首次试验，1981年服役。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-606", "q": "下列关于通讯技术的说法正确的是：", "options": ["蓝牙是一种短距离无线通信技术", "光纤通信抗电磁干扰能力差", "移动通信可直接使用无线电波通讯", "对讲机使用时需要网络支持"], "a": 0, "e": ".【A】本题主要考查科技理论与成就的相关知识。A项正确，蓝牙是一种支持设备短距离通信（一般10m内）的无线电技术。能在包括移动电话、PDA、无线耳机、笔记本电脑、相关外设等众多设备之间进行无线信息交换，故表述正确。B项错误，光纤通信是以光波作为信息载体，以光纤作为传输媒介的一种通信方式。光纤通信通过激光在光导纤维中传输信号，由于激光的频率远高于微波，所以不易受其他无线电波信号的干扰，而且保证了传输的稳定性，所以光纤通信的抗电磁干扰能力强，故表述错误。C项错误，移动通信主要是指陆地移动蜂窝通信系统，由移动台、基台、移动交换局组成，基站之间最常见的信号交流方式是光缆，基站和移动端之间是无线电波，这是蜂窝通信，也就是现在我们说的移动通信的原理。因此C项说法片面。D项错误，对讲机之间是通过无线电波的方式来传输语音信号的，不需要网络，是一对一的工作模式，即一台发射信号，另外的就接收信号，只要两台（或者两台以上的）对讲机在同一频率。故正确答案是A。", "tag": "科技常识"},
{"id": "tech-607", "q": "我国古代在医药科技方面取得了累累硕果，出现了不少重要的医学或科学名著。下列名著按成书年代排序，正确的是（）。", "options": ["《黄帝内经》《齐民要术》《本草纲目》《梦溪笔谈》", "《本草纲目》《梦溪笔谈》《黄帝内经》《齐民要术》", "《梦溪笔谈》《本草纲目》《齐民要术》《黄帝内经》", "《黄帝内经》《齐民要术》《梦溪笔谈》《本草纲目》"], "a": 3, "e": ".【D】本题考查科技常识。《黄帝内经》创作年代是先秦至汉，成书于汉代；《齐民要术》成书于南北朝时期北魏末年；《梦溪笔谈》成书于北宋时期；《本草纲目》成书于明代。因此排序应为：《黄帝内经》《齐民要术》《梦溪笔谈》《本草纲目》。D项按成书年代排序，完全正确。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-608", "q": "2017 年4 月，我国首艘货运飞船（）在文昌航天发射场成功发射，标志着我国即将开启空间站时代。", "options": ["嫦娥一号", "天宫一号", "天舟一号", "丝路一号"], "a": 2, "e": ".【C】本题考查科技常识。A项错误，“嫦娥一号”是我国首颗绕月人造卫星，于2007年10月24日在西昌卫星发射中心升空。B项错误，“天宫一号”是我国第一个目标飞行器，于2011年9月29日在酒泉卫星发射中心发射。C项正确，“天舟一号”是我国第一艘面向空间站建造和运营任务全新研制的货运飞船，于2017年4月20日在海南文昌航天发射场发射成功。其成功发射，是我国载人航天工程“三步走”发展战略第二步的收官之作，标志着我国即将开启空间站时代。D项错误，“丝路一号”不是货运飞船，而是科学试验卫星，随天舟一号货运飞船升空。其主要任务是为西部地区及丝路沿线国家提供便捷稳定的增强导航和遥感影像服务，不是为宇宙空间探测。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-609", "q": "2017 年5 月18 日，我国宣布可燃冰试采获得成功，标志着我国成为全球第一个在海域可燃冰试开采中获得连续稳定产气的国家。可燃冰的主要有效成分是：", "options": ["甲烷", "乙炔", "甲醇", "乙醇"], "a": 0, "e": ".【A】本题考查科技常识，主要涉及可燃冰的相关知识。可燃冰，是分布于深海沉积物或陆域的永久冻土中，由天然气与水在高压低温条件下形成的类冰状的结晶物质。A项正确，可燃冰是一种白色固体物质，有极强的燃烧力，主要由水分子和烃类气体分子（主要是甲烷）组成。B项错误，乙炔，俗称风煤或电石气，在室温下是一种无色、极易燃的气体，主要用于工业用途，特别是烧焊金属方面。C项错误，甲醇是结构最为简单的饱和一元醇，是无色有酒精气味易挥发的液体。用于制造甲醛和农药等，并用作有机物的萃取剂和酒精的变性剂等。D项错误，乙醇俗称酒精，是一种有机物，在常温常压下是一种易燃、易挥发的无色透明液体，可用于制造醋酸、饮料、香精、染料、燃料等。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-610", "q": "下列属于20 世纪人类科技成就的是①电话的发明②发电机的问世③世界上第一架飞机试飞成功④电报的发明⑤因特网的发明⑥卫星的发明", "options": ["①②③", "①③⑥", "④⑤⑥", "③⑤⑥"], "a": 3, "e": ".【D】本题考查科技常识，主要涉及20世纪人类的科技成就。①电话是由美国发明家贝尔于1876年发明。因此电话属于19世纪人类的科技成就。②1866德国人西门子制成发电机，到70年代实际可用的发电机问世，人类社会进入电气时代。因此发电机属于19世纪人类的科技成就。③1903年，美国的莱特兄弟造出了世界上第一架飞机并试飞成功。因此该项属于20世纪人类的科技成就。④19世纪90年代意大利人马可尼试验无线电报获得成功，为信息的迅速传播提供了方便。因此电报属于19世纪人类的科技成就。⑤因特网，前身是美国国防部于1969年建立的阿帕网，1983年，正式将TCP/IP协议作为网络标准，之后全世界不断有新的网络按照这个标准加入因特网。因此因特网属于20世纪人类的科技成就。⑥1957年10月4日，苏联成功发射了世界上第一颗人造地球卫星。因此卫星属于20世纪人类的科技成就。所以属于20世纪人类科技成就的是③⑤⑥。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-611", "q": "被我国军迷亲切称为“胖妞”的运-20 在庆祝中国人民解放军建军90 周年阅兵中首次亮相。以下有关运-20 的说法中，错误的是：", "options": ["是中国自主研发的新一代重型军用运输机", "是一种200 吨级大型、多用途运输机", "是世界上最大的运输机", "已正式加入我国空军空运部队序列"], "a": 2, "e": ".【C】本题考查科技理论与成就，主要涉及有关运-20的相关知识。A项正确，运-20是我国自主研发的新一代重型军用运输机，于2013年1月26日首飞成功。B项正确，运-20是大型、多用途运输机，最大起飞重量可达200多吨，可在复杂气象条件下，执行各种物资和人员的长距离航空运输任务。C项错误，世界上最大的运输机是安-225运输机，起飞重量可达640吨，是由前苏联安东诺夫设计局研制的超大型军用运输机，现归乌克兰所有。D项正确，2016年7月6日，空军运-20飞机授装接装仪式举行，中国自主发展的运-20飞机正式列装空军航空兵部队，标志着空军战略投送能力迈出关键性一步，也标志着我国大型飞机设计制造能力取得突破性进展。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-612", "q": "十八大以来，我国大力实施创新驱动发展战略，创新型国家建设成果丰硕，下列有关重大科技成果中，名称与研发项目对应有误的是：", "options": ["“天宫一号”——空间实验室", "“悟空号”——量子科学实验卫星", "“蛟龙号”——载人潜水器", "“中国天眼”——射电望远镜"], "a": 1, "e": ".【B】本题考查科技理论与成就，主要涉及我国研发项目的相关知识。A项正确，空间实验室是一种可重复使用和多用途的载人航天科学实验空间站。“天宫一号”是我国首个空间实验室，于2011年9月29日在酒泉卫星发射中心发射升空。B项错误，“悟空号”是暗物质粒子探测卫星，于2015年12月17日在酒泉卫星发射中心发射升空。我国研制的量子科学实验卫星是“墨子号”，于2016年8月16日在酒泉卫星发射中心发射升空，因此对应错误。C项正确，载人潜水器是具有水下观察和作业能力的潜水装置。“蛟龙号”是由我国自行设计、自主集成研制的载人潜水器。D项正确，500米口径球面射电望远镜，简称FAST，位于贵州省黔南布依族苗族自治州平塘县大窝凼，被誉为“中国天眼”，于2016年9月落成。“中国天眼”是具有我国自主知识产权、世界最大单口径的射电望远镜。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-613", "q": "人们常用“杏林春暖”、“杏林满园”、“誉满杏林”来赞扬医生的精湛医术和高尚医德，“杏林”典出下列哪一医家：", "options": ["张仲景", "华佗", "董奉", "扁鹊"], "a": 2, "e": ".【C】A项错误：张仲景与杏林典故无关，人称“医圣”。B项错误：华佗与杏林典故无关，华佗发明了全身麻醉药“麻沸散”。C项正确：三国时，吴国名医董奉，常年为人免费治病，只需病人种植杏树若干棵，久之成为一片杏林，于是筑庐隐居其中。后人于是用“杏林”称颂医生，用“杏林春暖”、“杏林春满”、“杏林满园”或“誉满杏林”等成语来赞扬医生的高明医术和高尚医德。D项错误：扁鹊与杏林典故无关，扁鹊发明了四诊法，人称“脉学之宗”。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-614", "q": "旅行者2 号探测器于1977 年8 月20 日在肯尼迪航天中心成功发射升空，近探过太阳系的四颗行星后，飞向了外太空。这四颗行星依次为：", "options": ["水星、金星、火星、天王星", "水星、金星、木星、天王星", "木星、土星、天王星、海王星", "木星、火星、天王星、海王星"], "a": 2, "e": ".【C】旅行者2号探测器是美国航天局研制的飞往太阳系外的两艘空间探测器的第二艘。探访顺序如下：①木星，在1979年7月9日最接近，在距离木星云顶570,000公里（350,000英里）处掠过；②土星，在1981年8月25日最接近，当太空船处于土星后方时（相对地球而言），它以雷达对土星的大气层上部进行探测，并量度了气温及密度等资料；③天王星，在1986年1月24日最接近，并随即发现了10个之前未知的天然卫星；④海王星，在1989年8月25日最接近，发现了海王星的大暗斑。可知，近探顺序依次为木星、土星、天王星、海王星。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-615", "q": "鲨鱼皮泳衣能够明显提高游泳运动员的成绩，但很快被国际奥委会禁止使用，其根本原因是：", "options": ["发展中国家运动员买不起昂贵的鲨鱼皮泳衣", "鲨鱼皮泳衣按照白色人种的体型和特点设计", "鲨鱼皮泳衣模糊了技术极限和体能极限差别", "鲨鱼皮泳衣污染泳池对运动员身体造成伤害"], "a": 2, "e": ".【C】C项符合题意：鲨鱼皮泳衣是一种模仿鲨鱼皮肤制作的高科技泳衣。根据SPEEDO公司提供的数据显示，“鲨鱼皮”能将水中阻力降低，减少运动员的氧气消耗，使其成绩提高。虽然“鲨鱼皮”有助于选手提高成绩，却也使得游泳不再是运动员体能与技术的比拼，而成为了科技的比拼，这严重违背了游泳运动不借助外力的本质。因此国际奥委会2010年后全面禁止使用“鲨鱼皮”泳衣。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-616", "q": "关于诺贝尔奖，下列说法正确的是：", "options": ["诺贝尔奖分为物理、化学、生理或医学、数学、文学、和平六个奖项", "莫言是第一位获诺贝尔奖的华人", "居里夫人是第一位获得诺贝尔奖的女性", "由于创造新型抗癌药—青蒿素，屠呦呦获得诺贝尔医学奖"], "a": 2, "e": ".【C】C项正确：玛丽居里是首位诺贝尔奖女性得主，波兰裔法国籍女物理学家、放射化学家，是放射性现象的研究先驱。1903年，居里夫人与其丈夫皮埃尔居里及亨利贝克勒共同获颁诺贝尔物理学奖。A项错误：诺贝尔奖设物理、化学、生理学或医学、文学、和平、经济学六大奖项，没有数学奖。B项错误：李政道和杨振宁是最早获诺贝尔奖的华人。李政道，1926年生于上海，美籍华人，1957年获诺贝尔物理学奖，时年31岁；杨振宁，1922年生于安徽，美籍华人，1957年获诺贝尔物理学奖，时年35岁。而莫言是第一位获得诺贝尔奖的本土中国人，他于2012年获得诺贝尔文学奖。“华人”是全体中华民族之人的代称，其下包括了“中国公民”以及海外“华侨”。“美籍华人”同样属于“华人”的范畴，莫言并非第一位获得诺贝尔奖的华人，答题时从这词可果断排除此项。D项错误：2015年10月，屠呦呦获诺贝尔生理学或医学奖是由于她发现青蒿素治疗疟疾的新疗法。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-617", "q": "洲际导弹通常指射程大于8000 公里的远程弹道式导弹。目前，中国研制的洲际弹道导弹主要是什么系列的？", "options": ["“东风”系列", "“长征”系列", "“红旗”系列", "“天宫”系列"], "a": 0, "e": ".【A】A项，“东风”系列，是中华人民共和国一系列近程、中远程和洲际弹道导弹。“东风”系列是目前世界上唯一覆盖各种类型弹道导弹的陆基弹道导弹系列。B项，“长征”系列为我国运载火箭型号命名。中国自1956年开始展开现代火箭的研制工作。1964年6月29日，中国自行设计研制的中程火箭试飞成功之后，即着手研制多级火箭，向空间技术进军。经过了五年多的艰苦努力，1970年4月24日“长征一号”运载火箭诞生，首次发射“东方红一号”卫星成功。现在“长征”系列火箭已经走向世界，享誉全球，在国际发射市场占有重要一席。C项，“红旗”系列防空导弹构成了我国地空防空导弹的主体。红旗系列防空导弹涵盖了中远程、中高空到近程超低空的火力范围，已经形成一个庞大的家族，担负着中国防空的重任。D项，“天宫”系列是我国空间站项目的命名方式。早在1992年，中国就确立了以建立空间站为目标的航天计划。这一计划分三步，第一步是载人飞船阶段，目标是能够把宇航员送到太空，正常运行若干天，并成功返回。第二步是空间实验室阶段，在这个阶段要解决组装、交互对接、补给以及循环利用等四大技术。这些技术关系到空间站的组装、宇航员在空间站的生存等关键问题。“天宫”一号就是中国在第二步计划中为了解决交互对接问题而发射的一个目标飞行器。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-618", "q": "二维码目前广泛应用于汉字、数学、图片、指纹、声音等信息的存储。下列关于二维码的说法，正确的是：", "options": ["中国目前还没有制定二维码的国家标准", "“扫一扫”加关注是目前二维码应用的重要方式", "二维码在穿孔、污损引起局部损坏时就无法得到视读", "扫描二维码可能感染病毒是因为二维码本身携带病毒"], "a": 1, "e": ".【B】A项错误：随着互联网技术发展诞生的二维码，相关部门历来重视对其的管理和规范，比如2015年实施的《中华人民共和国国家标准（GB/T31022—2014）：名片二维码通用技术规范》等一系列关于二维码的国标，促进了二维码在我国的发展；B项正确：“扫一扫”加关注就是通过二维码实现共享生活信息和进行社交娱乐，这正是当下二维码的主要应用方式；C项错误：二维码容错能力强，具有纠错功能。这使得二维码在因穿孔、污损等引起局部损坏时，照样可以正确得到识读，损毁面积达50仍可恢复信息；D项错误：二维码本身不会携带病毒，但很多病毒软件可以利用二维码下载。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-619", "q": "航天员在太空行走需要穿舱外航天服，不出舱、在加压舱内穿的航天服称为舱内航天服。下列不属于舱内航天服功能的是：", "options": ["提供一定的温度保障和通信功能", "防辐射、隔热、防微陨石、防紫外线", "在座舱减压和氧气丧失时提供压力和氧气", "飞行中或着陆后遇到空气污染时，能防止吸入有毒气体"], "a": 1, "e": ".【B】航天服按用途可分为舱内航天服和舱外航天服两大类。防辐射、隔热、防微陨石、防紫外线等是舱外航天服具有的功能。故B项错误。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-620", "q": "下面关于WIFI 的说法，正确的是：", "options": ["WIFI 是一种可以将笔记本电脑、手机、PAD 等终端以无线方式连接的技术", "严格意义上来讲，WIFI 就是我们常说的WLAN", "WIFI 就是中国移动提供的无线网络服务", "所有的智能手机都具有WIFI 功能"], "a": 0, "e": ".【A】A项：Wifi是一种可以将个人电脑、手机等终端设备以无线方式互相连接的技术。常见的连接方式是通过一个无线路由器来实现。无线路由器是通过无线电波也就是电磁波向四周传递信息，光是电磁波的一种，在同种介质中电磁波的传播速度相同，所以电磁波的传播速度等于光速，正确；B项：WIFI的英文全称为wirelessfidelity，在无线局域网的范畴是指“无线相容性认证”，实质上是一种商业认证，同时也是一种无线联网的技术；WLAN是WirelessLocalAreaNetwork的缩写，指应用无线通信技术将计算机设备互联起来，构成可以互相通信和实现资源共享的网络体系。从定义上看，WIFI是以WLAN技术为基础的，错误；C项：WIFI网络工作在2.4G或5G的频段（接近直线传播），作用距离不远，有利于频率复用。中国移动和联通提供的", "tag": "科技常识"},
{"id": "tech-621", "q": "关于交通，下列说法不正确的是：", "options": ["“红眼航空”是航空公司正常安排的夜间飞行航班", "我国高速公路限制最高时速一般为110 公里", "船舶通信方式包括视觉通信、电波通信、卫星通信等", "世界上首条正式运营的高速铁路是日本的新干线"], "a": 1, "e": ".【B】B项说法错误，根据我国《道路交通安全法实施条例》的规定，我国高速公路限制最高时速为120公里。A、C、D三项说法均正确。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-622", "q": "在计算机网络通信领域中，防火墙是一项协助确保信息安全的设备。它会依据特定的规则，允许或是限制传输的数据通过。小张在自己电脑上安装了防火墙软件，下列论述正确的是()", "options": ["防火墙软件有可能导致小张的电脑不能访问特定的Web 网站", "防火墙软件有可能导致小张无法访问自己电脑硬盘上存储的文档", "防火墙软件使得小张在网络购物时，不容易被虚假广告所欺骗", "防火墙软件使得小张在和陌生网友聊天时，可以伪装自己的性别和姓名"], "a": 0, "e": ".【A】防火墙是在内部网和外部网之间、专用网与公共网之间的界面上构造的保护屏障，是一种获取安全性方法的形象说法，它是一种计算机硬件和软件的结合，是建立起的一个安全网关，因而有可能导致电脑不能访问特定的Web网站。A项正确，当选。B项读取硬盘数据无需网络数据，排除。C项是否被骗取决于个人的主观判断力，防火墙无法判断广告内容是否虚假，排除。D项的内容无需通过防火墙软件实现，排除。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-623", "q": "关于宇航员在太空的生活，下列说法不正确的是：", "options": ["宇航员可使用特定的加热器对食品进行加热", "宇航员从太空返回地面后，失重状态消失，质量会有所增加", "宇航员应睡在固定的睡袋中，以免被气流推动误碰仪器设备开关", "在同一航空器中的宇航员可以直接交谈，无须借助无线电通讯设备"], "a": 1, "e": ".【B】B项错误，质量是物体的一种属性，不随物体的形状、状态、空间位置的改变而改变。“失重”指的是失去重力而非质量。A、C、D三项均正确。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-624", "q": "下列卫星系列不属于我国对地观测卫星的是：", "options": ["“海洋”", "“风云”", "“天绘”", "“北斗”"], "a": 3, "e": ".【D】对地观测卫星用于对地球进行遥感的各种人造地球卫星和航天器。我国对地观测卫星主要有“风云”“海洋”“资源”“遥感”“天绘”等系列。“北斗”系列卫星是导航卫星，不是对地观测卫星。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-625", "q": "下列哪项是我国在“十二五”开局之年取得的科技成就：", "options": ["我国首辆高速磁浮国产化样车交付使用，标志着我国已经具备了磁浮车辆国产化设计，整车集成和制造能力", "我国具有自主知识产权的戊型肝炎疫苗研制成功，标志着我国在戊型肝炎疫苗研制上已经处于世界领先地位", "我国第一台自行设计、自主集成研制的“蛟龙号”载人潜水器3000 米级海试取得成功，标志着我国成为世界上掌握", "国内首套具有自主知识产权的“机载SAR 测图系统”研制成功，至此，我国可成功实现全天时、全天候从万米高空获"], "a": 3, "e": ".【D】“十二五”规划的起止时间：2011—2015年。A项错误，2010年4月8日，我国首辆高速磁悬浮国产化样车在成都实现交付。该样车由中航工业成都飞机工业（集团）有限公司制造，标志着该企业已经具备了磁浮车辆国产化设计、整车集合和制造能力；B项错误，2009年初厦门大学、福建省医学分子病毒学研究中心和养生堂北京万泰药业有限公司研制出我国第一种拥有核心自主知识产权的基因工程疫苗——重组戊型肝炎疫苗；C项错误，2010年8月26日上午，科学技术部与国家海洋局联合宣布，国家高技术研究发展计划（863计划）重大专项——我国第一台自行设计、自主集成研制的“蛟龙号”载人潜水器3000米级海上试验取得成功，最大下潜深度达到", "tag": "科技常识"},
{"id": "tech-626", "q": "下列有关天文知识的表述，正确的是：", "options": ["开普勒制成人类历史上第一台天文望远镜，并证实了哥白尼学说", "四象青龙、白虎、朱雀、玄武分别代表东、西、南、北四个方向", "世界最早的哈雷彗星记录是《诗经》中的\"鲁庄公七年星陨如雨\"", "月食发生时地球、月球、太阳在一条直线上，且月球居中"], "a": 1, "e": ".【B】A项错误，第一架天文望远镜是伽利略发明的；B项正确，古代汉族人民把东、西、南、北四方每一方的七宿想象为四种动物形象，叫作四象。四象在中国文化中指青龙、白虎、朱雀、玄武，分别代表东、西、南、北四个方向。C项错误，哈雷彗星的最早记录详见《春秋》“秋七月，有星孛入于北斗”；D项错误，说的是日食。月食发生时，地球、月球、太阳在同一直线上，且地球居中。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-627", "q": "下列关于人类航天史的说法，正确的是：", "options": ["载人飞船首次在地球轨道上实现交会和对接是在20 世纪60 年代", "前苏联宇航员加加林是世界上第一个进行太空行走的人", "成功将世界上第一颗人造地球卫星送入太空的是美国", "首次实现登月的载人飞船是“阿波罗13 号”"], "a": 0, "e": ".【A】A项正确，1966年3月16日，美国发射载有阿姆斯特朗和斯科特的双子星座8号，绕地球飞行6.5圈，历时10小时41分，飞行中首次实现载人飞船与一个名叫阿金纳的对接舱体对接；B项错误，世界上第一个进行太空行走的宇航员是前苏联航天员列昂诺夫，加加林是第一个进入太空的人；C项错误，1957年，苏联成功地发射了第一颗人造地球卫星“斯普特尼克1号”；D项错误，1969年7月16日，“土星5号”把“阿波罗11号”送往月球，实现了人类首次登月的壮举。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-628", "q": "关于北斗系统，下列说法错误的是：", "options": ["是中国自主研制的全球卫星导航系统", "北斗系统的卫星都是静止轨道卫星", "可实现高精度授时的功能", "能够实现汉字的短报文通信"], "a": 1, "e": ".【B】本题主要考查科技常识。A项正确，北斗系统是中国着眼于国家安全和经济社会发展需要，自主建设、独立运行的卫星导航系统，是为全球用户提供全天候、全天时、高精度的定位、导航和授时服务的国家重要空间基础设施。B项错误，北斗系统由空间段、地面段和用户段三部分组成。空间段由若干地球静止轨道卫星、倾斜地球同步轨道卫星和中圆地球轨道卫星三种轨道卫星组成混合导航星座。因此，“都是静止轨道卫星”表述错误。C项正确，北斗系统创新融合了导航与通信能力，具有实时导航、快速定位、精确授时、位置报告和短报文通信服务五大功能。D项正确，北斗系统创新融合了导航与通信能力，具有实时导航、快速定位、精确授时、位置报告和短报文通信服务五大功能。北斗系统用户终端具有双向报文通信功能，用户可以传送汉字的短报文信息。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-629", "q": "关于现代军事，下列说法错误的是：", "options": ["中国海军第一艘可搭载固定翼飞机的航空母舰是“辽宁舰”", "爱国者导弹是由美国研制的全天候多用途中程防空导弹系统", "歼-10 战斗机是我国自主研制的单座单发第二代战斗机", "生化武器因其伤害的无差别性和永久性被联合国列为禁用武器"], "a": 2, "e": ".【C】本题考查现代军事的科技常识。A项正确，辽宁号航空母舰，简称“辽宁舰”，是中国人民解放军海军第一艘可以搭载固定翼飞机的航空母舰。其前身是前苏联海军的库兹涅佐夫元帅级航空母舰次舰瓦良格号，改装后于2012年9月25日交付予中国人民解放军海军。B项正确，爱国者导弹是美国雷神公司制造的全天候多用途中程防空导弹系统，主要用于对付现代装备的高性能飞机，并能在电子干扰环境下击毁近程导弹，拦截战术弹道导弹和潜射巡航导弹。C项错误，歼-10战斗机是中国航空工业集团有限公司自主研制的第三代战斗机，是多功能、超音速、全天候空中优势战斗机，而非题干中表述的第二代。D项正确，生化武器是指以细菌、病毒、毒素等使人、动物、植物致病或死亡的物质材料制成的武器。由于其伤害的无差别性和永久性，联合国大会于1992年一致通过了《禁止化学武器公约》，所有缔约国将禁止使用、生产、购买、储存和转移各类化学武器。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-630", "q": "下列关于世界著名科学家的贡献说法不正确的是：", "options": ["俄国化学家门捷列夫发现了元素周期表，这一发现成为化学发展史上的重要里程碑", "古希腊的亚里士多德是一位百科全书式科学家，他对许多学科都做出了重要贡献", "英国科学家牛顿发现了万有引力定律，使人类对物质构成的认识有了质的飞跃", "波兰天文学家哥白尼提出了“日心说”，沉重打击了教会的宇宙观"], "a": 2, "e": ".【C】本题考查科技常识。A项正确，1869年，俄国化学家门捷列夫制作出了第一张元素周期表，揭示了化学元素间的内在联系，成为化学发展史上的重要里程碑之一。B项正确，古希腊的亚里士多德作为一位百科全书式科学家，在许多学科中写下了开创性论文，如教育学、心理学、医学、生物学等，最重要的是他把逻辑学发展成为一门科学，使之成为一切科学的工具，为近代科学创造了可借鉴的理论依据。C项错误，1687年牛顿发现万有引力，任何物体之间都有相互吸引力，这个力的大小与各个物体的质量成正比例，而与它们之间的距离的平方成反比。万有引力定律是物体间相互作用的一条定律，并非“物质构成”。D项正确，哥白尼，文艺复兴时期波兰数学家、天文学家，提出“日心说”，沉重地打击了教会的宇宙观，是唯物主义和唯心主义斗争的伟大胜利。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-631", "q": "以下关于航天科技的说法不正确的是：", "options": ["在全球的载人航天中，第一个进入太空的人是阿姆斯特朗", "电视节目的转播主要通过地球同步轨道静止卫星来实现", "中国成功研制并发射的第一颗人造地球卫星是“东方红一号”", "人造地球卫星若在轨道上运行速度过慢，会被地球引力吸引回地球"], "a": 0, "e": ".【A】本题考查科技常识的有关知识。A项错误，世界上第一个进入太空的人是前苏联的尤里加加林，美国的尼尔阿姆斯特朗是第一个登上月球的人。B项正确，同步轨道静止卫星，相对于地球保持静止，主要用于陆地固定通信，如电话通信、电视节目的转播以及海上移动通信等。C项正确，东方红一号卫星是我国于1970年4月24日成功研制并发射的第一颗人造地球卫星。我国是继苏、美、法、日之后，世界上第五个用自制火箭发射国产卫星的国家。D项正确，人造地球卫星因为速度足够大，才能环绕地球运动。若在轨道上运行速度过慢，受地球引力的作用，会被吸引回地球。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-632", "q": "下列说法中，不正确的是：", "options": ["轻轨和地铁的区别主要是运量不同", "隐形飞机运用“隐形”技术，躲避雷达侦测", "在能源领域中，一般所称的页岩气是指页岩中的天然气", "海浪主要是由地球自转形成的"], "a": 3, "e": ".【D】A项正确：轻轨和地铁主要区别是运量不同，如果用高峰小时单向最大客运量来表示的话，地铁的高峰小时单向最大客运量为3-7万人次，轻轨的高峰小时单向最大客运量为1-3万人次。B项正确：隐形飞机是通过在飞机上应用最新的技术和材料，使之不易被敌方发现。目的是为了让雷达无法侦察到飞机的存在。C项正确：页岩气是指赋存于页岩及其夹层中，以吸附和游离状态为主要存在方式的非常规天然气，成分以甲烷为主。D项错误：海浪通常指海洋中由风产生的波浪，而风的形成与大气运动有关。所以海浪不是主要由地球自转而形成的，地球自转一般跟昼夜交替有关。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-633", "q": "2016 年11 月3 日20 时43 分，从中国文昌航天发射场点火升空，完成首次发射任务并取得圆满成功的我国最大推力新一代运载火箭是：", "options": ["长征七号", "长征六号", "长征五号", "长征八号"], "a": 2, "e": ".【C】C项正确：长征五号于2016年11月3日在中国文昌航天发射场首飞成功，由此成为中国运载能力最大的火箭。A项错误：长征七号运载火箭于2016年6月25日从中国文昌航天发射场首次成功发射，这也是文昌航天发射场的首次发射任务。长征七号是中国载人航天工程为发射货运飞船而全新研制的新一代中型运载火箭。B项错误：长征六号于2015年9月20日在太原卫星发射中心点火发射，长征六号运载火箭是中华人民共和国上海航天技术研究院（中国航天科技集团公司第八研究院）研制的新一代无毒无污染小型液体运载火箭。D项错误：长征八号运载火箭是中国运载火箭技术研究院正在研制的一型采用无毒无污染推进剂的新型中型运载火箭，主要面向具有国际竞争力的商业卫星发射任务。预计将在2020年实现首飞。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-634", "q": "在量子理论发展过程中，最早提出能量子假说的是德国物理学家：", "options": ["爱因斯坦", "海森堡", "玻尔", "普朗克"], "a": 3, "e": ".【D】本题考查科技常识。A项错误，爱因斯坦是著名的犹太裔物理学家。普朗克提出能量子概念后，爱因斯坦接受了这一观点，将其运用在对光电效应的理论解释中去，提出了著名的“光电效应方程”，初步向人们展示了量子这一新工具的巨大威力，有力地证明了普朗克的“能量子”观点。B项错误，海森堡是德国著名物理学家，其得益于爱因斯坦相对论的思路，于1925年创立了矩阵力学，并提出不确定性原理及矩阵理论。C项错误，玻尔是丹麦物理学家。玻尔通过引入量子化条件，提出了玻尔模型来解释氢原子光谱；提出互补原理和哥本哈根诠释来解释量子力学。玻尔的理论大大扩展了量子论的影响，加速了量子论的发展。D项正确，1900年，德国物理学家普朗克大胆地提出了能量子假设，他认为黑体在吸收能量的时候，不是连续的，而是一份一份的，即能量有最小单位，这个最小的单位被称作“能量子”。能量子概念的提出，是物理学具有划时代意义的里程碑事件，它标志着量子力学的诞生，普朗克本人也被广泛赞誉为“量子力学之父”。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-635", "q": "2016 年8 月16 日我国发射了世界首颗量子科学实验卫星，这将使我国在世界上首次实现卫星和地面之间的量子通信。这颗卫星被命名为：", "options": ["“孔子号”", "“墨子号”", "“孟子号”", "“荀子号”"], "a": 1, "e": ".【B】B项正确：2016年8月16日，我国在酒泉卫星发射中心成功将世界首颗量子科学实验卫星（简称“量子卫星”）“墨子号”发射升空。这颗量子卫星以我国古代伟大科学先贤墨子的名字命名为“墨子号”。解析本题时，观察四个选项里，可发现只有墨子具有科学家的身份，墨子所著的《墨经》中就包含了丰富的关于力学、光学、几何学、工程技术知识和现代物理学、数学的基本要素。初中物理还介绍了墨经中的小孔成像的记载。灵活运用知识储备是常识要诀。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-636", "q": "据报道，一个小行星采矿公司释放了一颗试验性小行星采矿探测器，希望其深入太阳系寻找具有采矿前景的近地小行星。该探测实验第一步的中心任务是从小行星提取水分。下列关于探测器提取水分原因的解释最合理的是：", "options": ["太空提取的水分没有污染，有利于科学研究", "水是生命之源，提取水分有助于寻找地外生命", "水可以被分解为氧和氢，能为探测器提供优质燃料", "地球水资源严重污染，必须从太空获取洁净的水资源供给人类"], "a": 2, "e": ".【C】C项正确：报道中的小行星采矿公司为美国一家致力于开采自然资源和开展太空探索的科技公司——“行星资源”公司。该公司在新闻发布会上表示，除了开采行星上丰富的矿产资源，还将对太空进行探索。小行星上拥有丰富的水资源，水可以被分解为氧和氢，能够为外星探测设施提供燃料，成为深入探索太空的基石。C项最能解释为何探测实验第一步的中心任务是从小行星提取水分。ABD项的解释均不恰当。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-637", "q": "下列说法有误的是（）。", "options": ["最初的诺贝尔奖只包括物理学奖、化学奖、生理学或医学奖、文学奖、和平奖", "王选是我国第一个获得我国国家最高科学技术奖的科学家", "2012 年王澍获得有“建筑界诺贝尔奖”之称的普利兹克建筑奖，这是该奖项首次授予中国人", "中国科学家屠呦呦因发现青蒿素而获得国际医学大奖——拉斯克奖"], "a": 1, "e": ".【B】本题主要考查科技常识，需结合具体选项予以分析。A项正确，诺贝尔奖是根据瑞典化学家诺贝尔的遗愿在1900年创立的，起初诺贝尔奖只有物理、化学、生理学或医学、文学和和平五个奖项，于1901年首次颁发。经济学奖并非诺贝尔的遗嘱所设立的，而是在1968年设立，1969年首次颁发；B项错误，国家最高科学技术奖设立于2000年，并当年首次颁发国家最高科学奖，著名数学家吴文俊和杂交水稻之父袁隆平首次获得此奖，而王选是在2002年获得2001年度国家最高科学技术奖；C项正确，2012年2月27日，王澍获得了普利兹克建筑奖，成为获得该奖项的第一个中国人；D项正确，2011年9月23日，国际医学大奖美国拉斯克奖，将2011年临床研究奖颁发给屠呦呦，这是拉斯克奖设立65年来首次授予中国科学家。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-638", "q": "据媒体报道，近日海南航空由成都飞往北京的一航班在飞行途中遭遇晴空颠簸，导致旅客和机组人员受伤。下列关于晴空颠簸的说法错误的是（）。", "options": ["航班通过接受定时定点和飞机尺度颠簸范围的预报来避免颠簸", "遭遇晴空颠簸，旅客避免受伤的最好办法就是全程系好安全带", "从目前的科技水平来讲，晴空颠簸属于飞行中的一种不可抗力", "飞机可以通过升降高度，或者偏离航线来脱离晴空颠簸的影响"], "a": 0, "e": ".【A】A项错误，虽然目前航空气象部门根据高空探测资料可以预测激流带的存在和范围，但无法做到定时定点地预测。B项正确，无论如何，在飞行过程中全程系好安全带是聪明的做法。C项正确，飞机颠簸主要是由于飞机飞入扰动气流区，扰动气流使作用在飞机上的空气动力和力矩失去平衡，属于不可抗力因素的一种。D项正确，如果飞行中出现颠簸，可改变高度几百米或暂时偏离航线几十千米，一般可以脱离颠簸区。采取改变高度的脱离方法，往往能更迅速地脱离颠簸区。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-639", "q": "人工智能是指由人工制造的系统所表现出来的智能。人工智能的核心包括推理、知识、规划、学习、交流、感知、移动和操作物体的能力等。下列论述中所描述的各项技术突破，无关人工智能的是：", "options": ["科学家利用数学定理证明程序，证明了“数学原理”一书第二章的38 个定理", "中国象棋程序在人机对弈时，能够根据以往的棋局，学习到新的战术，从而避免因为类似的错误而失败", "小张家里新买的最新款电视机，能够根据电视机周围的环境光线强弱，自动地调整屏幕的亮度", "有种名为siri 的手机软件，采用自然语言处理技术，使用户能用自然的对话与手机进行互动"], "a": 0, "e": ".【A】A项错误，利用设定好的证明程序，证明了已经存在的定理，只能说明该程序设计正确，并不能体现人工智能的特点，其他如B项中的学习、C项中的感知、D项中的交流等直接体现了题干中人工智能的特点。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-640", "q": "随着数据通信与多媒体业务需求的发展，适应移动数据、移动计算及移动多媒体运作需要的第四代移动通信开始兴起。在国际电信联盟2012 年无线电通信全会上，我国主导研制的________正式被确定为4G 国际标准，标志着中国在移动通信标准制定领域再次走到了世界前列。", "options": ["TD-LTE.", "FDD-LTE.", "WiMAX", "TD-SCDMA."], "a": 0, "e": ".【A】A项正确：在国际电信联盟2012年无线电通信全会上，我国主导研制的TD-LTE正式被确定为4G国际标准。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-641", "q": "飞到月亮上去是人类千百年来的梦想，随着空间技术的发展，人类登月已经实现。下列有关人类登月的说法有误的是（）。", "options": ["前苏联宇航员加加林于1961 年乘东方1 号宇宙飞船奔向月球", "美国宇航员阿姆斯特朗1969 年在月球上率先跨出人类历史“一大步”", "2013 年我国成功将“玉兔号”巡视器顺利送抵月球表面", "美国是人类最早登上月球的国家"], "a": 0, "e": ".【A】A项错误：1961年4月12日，加加林乘坐东方1号宇宙飞船完成了世界上首次载人宇宙飞行，实现了人类进入太空的愿望，而不是奔向月球。B项正确：美国宇航员阿姆斯特朗1969年登月成功，在月球上率先跨出人类历史的“一大步”。C项正确：2013年我国成功将“玉兔号”巡视器顺利送抵月球表面。D项正确：1969年7月，美国阿波罗11号宇宙飞船实现了人类首次登月的壮举，美国是人类最早登上月球的国家。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-642", "q": "圆周率是一个在数学及物理学领域普遍存在的数学常数。它被定义为圆形之周长与直径之比，是精确计算圆周长、圆面积、球体积等几何形状的关键值。世界上最早计算圆周率数值的是（）。", "options": ["中国数学家祖冲之", "中国数学家刘徽", "印度数学家阿耶波多", "古希腊数学家阿基米德"], "a": 3, "e": ".【D】古希腊数学家阿基米德（公元前287—前212年）开创了人类历史上通过理论计算圆周率近似值的先河；公元", "tag": "科技常识"},
{"id": "tech-643", "q": "下列关于哈雷彗星的说法，错误的是（）。", "options": ["哈雷彗星的运行周期最早是英国人爱德蒙•哈雷测量出来的", "公元前613 年，我国在世界上第一次确切记录了哈雷彗星的回归", "哈雷彗星的平均公转周期为100 年", "哈雷彗星是人类首颗有记录的周期彗星"], "a": 2, "e": ".【C】哈雷彗星是著名的短周期彗星，每隔75～76年就能从地球上用肉眼看到，因英国物理学家爱德蒙哈雷（1656—", "tag": "科技常识"},
{"id": "tech-644", "q": "下列关于磁悬浮列车说法不正确的是：", "options": ["磁铁有同性相斥和异性相吸两种形式，磁悬浮列车也有相应的形式", "磁悬浮列车运行时会受到轨道的摩擦力和空气的阻力影响", "磁悬浮列车具有速度快、噪音低的特点", "我国已经研制出具有自主知识产权的中低速磁悬浮列车"], "a": 1, "e": ".【B】磁悬浮列车是一种靠磁悬浮力（即磁的吸力和斥力）来推动的列车。由于其轨道的磁力使之悬浮在空中，行走时不同于其他列车需要接触轨道，因此只受到来自空气的阻力。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-645", "q": "生活中常见的条形码是将宽度不等的多个黑条和白条，按一定的编码规则排列，用以表达一组信息的图形标示符。下列关于条形码的表述不正确的是：", "options": ["日本人最早使用了条形码", "要将条形码转化成有意义的信息，需要扫描和译码", "条形码有输入速度快、采集信息量大、可靠性高等优点", "通用商品条形码一般由前缀部分、制造厂商代码、商品代码和校验码组成"], "a": 0, "e": ".【A】A项错误，最早被打上条形码的产品是箭牌口香糖。条形码技术最早产生在风声鹤唳的20世纪20年代，诞生于美国威斯汀豪斯的实验室里。一位名叫约翰科芒德的性格古怪的发明家“异想天开”地想对邮政单据实现自动分检，那时候对电子技术应用方面的每一个设想都使人感到非常新奇。B项正确，要将条形码转化成有意义的信息，需要扫描和译码。C项正确，条形码有输入速度快、采集信息量大、可靠性高等优点。D项正确，通用商品条形码一般由前缀部分、制造厂商代码、商品代码和校验码组成。本题为选非题，故正确答案为A。", "tag": "科技常识"}
);
